import{d as e}from"./data_collaboration-BwD9_jUr.js";const t={id:"environnement-dev",part:"T",number:1,title:"Environnement de Développement",subtitle:"Comprendre la chaîne d'outils avant d'écrire du code",badge:"Fiche T01 — Vision Systémique",status:"Modèle stabilisé",meta:["11 nœuds · 3 OS","8 sections / nœud"],category:"Technique",level:"Débutant → Junior",readingTime:"25 min",description:"Une carte interactive pour comprendre comment VS Code, Git, GitHub, les runtimes, le shell et les gestionnaires de paquets s'articulent selon l'OS.",accent:"tool",tabs:[{id:"windows",label:"🪟 Windows"},{id:"macos",label:"🍎 macOS"},{id:"linux",label:"🐧 Linux"}],nodes:{vscode:{id:"vscode",label:"VS Code",icon:"🖊",kind:"tool",osLabel:"Tous OS",niveau:"Fondation",sections:{why:"<p>Avant les éditeurs modernes, on codait dans des éditeurs sans contexte — le fichier, rien d'autre. Pas d'erreurs en temps réel, pas d'autocomplétion, pas d'intégration avec l'environnement. <strong>VS Code est né du constat que l'éditeur doit être un environnement, pas un bloc-notes amélioré.</strong></p>",system:`<p>VS Code est le hub central du workflow. Il s'intègre avec <strong>Git</strong> (visualisation des diffs, staging inline), avec le <strong>terminal intégré</strong> (accès direct à WSL, bash, zsh sans changer de fenêtre), et avec le <strong>LSP</strong> (Language Server Protocol) qui alimente l'autocomplétion et les erreurs en temps réel.</p><p>Sur Windows, l'extension "Remote - WSL" fait tourner VS Code dans le contexte Linux, rendant la frontière entre les deux OS transparente.</p>`,choice:{kind:"structured",main:"VS Code domine par son écosystème d'extensions et sa légèreté relative. <strong>Le vrai choix se fait sur le curseur puissance / friction :</strong>",alternatives:[{name:"Cursor",description:"Fork de VS Code avec IA intégrée nativement. Recommandé quand tu maîtrises déjà VS Code."},{name:"WebStorm / IntelliJ",description:"Plus puissant pour les gros projets Java/Kotlin. Payant, plus lourd. Sens dans un contexte entreprise."},{name:"Neovim",description:"Vitesse maximale, entièrement au clavier. Courbe d'apprentissage abrupte. Pour plus tard."}]},senior:`<p>Un senior configure d'abord, code ensuite. Il installe ses extensions critiques (<strong>ESLint, Prettier, GitLens</strong>), active Settings Sync pour retrouver son environnement sur n'importe quelle machine, et configure le terminal intégré pour pointer sur le bon shell (WSL sur Windows, zsh sur macOS).</p><p>Il ne passe pas 3 heures à "personnaliser le thème" avant d'avoir écrit une ligne.</p>`,errors:"<p><strong>Pattern 1 — L'accumulation aveugle :</strong> accumuler des extensions sans comprendre ce qu'elles font. Résultat : éditeur lent, conflits silencieux, comportements imprévisibles.</p><p><strong>Pattern 2 — Ignorer le formatteur :</strong> ne pas configurer Prettier avec sauvegarde automatique. Le premier PR en équipe sera un enfer de diffs de formatage.</p><p><strong>Pattern 3 — Fuir le terminal :</strong> continuer à utiliser un terminal externe au lieu du terminal intégré. On perd la synchronisation de contexte.</p>",invariants:`<p>L'éditeur est un outil de feedback rapide. Peu importe l'outil futur, le besoin reste : <strong>voir les erreurs sans compiler, naviguer vite dans la base de code, intégrer le contrôle de version visuellement.</strong></p><p>Ce qui change : l'interface. Ce qui ne change pas : la nécessité de réduire le temps entre "j'écris une erreur" et "je la vois".</p>`,practice:{commands:[{type:"comment",value:"Téléchargement : code.visualstudio.com"},{type:"cmd",value:"code --version"},{type:"comment",value:"Extensions essentielles"},{type:"cmd",value:"code --install-extension eamodio.gitlens"},{type:"cmd",value:"code --install-extension esbenp.prettier-vscode"},{type:"cmd",value:"code --install-extension dbaeumer.vscode-eslint"}],verification:"code --version doit répondre, et les extensions essentielles doivent être installées dans le bon profil VS Code.",debt:'Extensions non maintenues → audit régulier. "Format on Save" à activer dans settings.json.'},verification:["Pourquoi un éditeur moderne est-il un environnement de feedback, et pas seulement un endroit où écrire du texte ?","Tu installes 25 extensions sans comprendre leur rôle et VS Code devient lent : quel principe systémique tu viens de violer ?","Ce qui change entre VS Code, Cursor et Neovim, et ce qui ne change pas dans le besoin qu'ils couvrent ?"]}},wsl:{id:"wsl",label:"WSL",icon:"🔗",kind:"infra",osLabel:"Windows uniquement",niveau:"Intermédiaire",sections:{why:"<p>Windows et Unix ont des philosophies d'OS radicalement différentes. La majorité des outils de dev (scripts, serveurs, Docker, pipelines CI) sont nés dans l'écosystème Unix et se comportent mal sous Windows — <strong>paths différents (\\ vs /), permissions différentes, scripts shell incompatibles.</strong></p><p>WSL (Windows Subsystem for Linux) fait tourner un vrai noyau Linux dans Windows, sans machine virtuelle dédiée. La frontière s'efface.</p>",system:`<p>WSL est <strong>la fondation de tout l'environnement de dev sur Windows.</strong> Git, Node.js, Python — tout tourne à l'intérieur de WSL. VS Code se connecte à WSL via "Remote - WSL", rendant l'expérience transparente. C'est le pont entre l'OS de bureau et l'environnement de dev réel.</p>`,choice:{kind:"structured",main:"WSL2 est la seule option sérieuse aujourd'hui. Les alternatives valent d'être connues :",alternatives:[{name:"WSL1",description:"Translation d'appels syscall. Plus lent, pas de noyau complet. À éviter."},{name:"Git Bash",description:"Émulation minimale, suffisant pour Git seul. Pas un vrai Linux."},{name:"VM dédiée (VirtualBox / VMware)",description:"Isolation totale mais lourde. Sens pour des tests d'OS uniquement."}]},senior:"<p>La règle d'or : <strong>les fichiers projet vivent dans le filesystem Linux</strong> (<code>~/projects/</code>), pas dans <code>/mnt/c/</code>. Accéder aux fichiers Windows depuis WSL via <code>/mnt/c/</code> est 5 à 10× plus lent à cause des appels cross-filesystem.</p><p>Pour accéder à ses projets depuis l'Explorateur Windows : <code>\\\\wsl$\\Ubuntu\\home\\user\\projects</code>.</p>",errors:"<p><strong>Pattern 1 — Le double install :</strong> installer Node.js côté Windows ET côté WSL. Les deux entrent en conflit dans le PATH. Règle : tout en WSL, rien côté Windows pour le dev.</p><p><strong>Pattern 2 — Le mauvais filesystem :</strong> mettre ses projets dans <code>C:\\Users\\...</code> puis y accéder via <code>/mnt/c/</code>. Latence I/O qui rend npm install et les watchers désagréables.</p><p><strong>Pattern 3 — Oublier WSL2 :</strong> ne pas vérifier qu'on est bien en WSL2 après installation.</p>",invariants:"<p>Quand les outils de dev assument un environnement Unix, l'alternative est toujours : une couche de compatibilité, une VM, ou changer d'OS. <strong>Ce qui change : la technologie de médiation entre Windows et Unix. Ce qui ne change pas : le besoin d'exécuter les outils dans l'environnement qu'ils supposent.</strong></p>",practice:{commands:[{type:"comment",value:"Dans PowerShell en mode Administrateur"},{type:"cmd",value:"wsl --install"},{type:"cmd",value:"wsl --set-default-version 2"},{type:"cmd",value:"wsl --status"},{type:"cmd",value:"wsl --update"}],verification:"wsl --status doit indiquer WSL2, et les projets doivent vivre dans le filesystem Linux plutôt que dans /mnt/c/.",debt:"WSL à mettre à jour après chaque mise à jour majeure de Windows."},verification:["Pourquoi WSL résout-il un problème de compatibilité systémique plutôt qu'un simple problème d'installation ?","Tu places ton projet dans C:\\Users puis tu l'ouvres depuis WSL : que va-t-il probablement se passer sur npm install ou les watchers ?","Ce qui change entre WSL, une VM et un vrai Linux, et ce qui ne change pas dans le besoin de fond ?"]}},ubuntu:{id:"ubuntu",label:"Ubuntu",icon:"🐧",kind:"infra",osLabel:"Windows / WSL",niveau:"Fondation",sections:{why:`<p>WSL est le moteur. <strong>Ubuntu est la distribution Linux qui tourne dedans.</strong> Il faut choisir un "OS invité". Ubuntu est le choix dominant car c'est la distribution la plus documentée, avec le plus grand écosystème de tutos, et elle utilise <code>apt</code> — le gestionnaire de paquets le plus commun et le mieux supporté pour débuter.</p>`,system:"<p>Ubuntu est l'OS invité dans WSL. C'est lui qui fournit <strong>apt</strong> pour installer des paquets système, le <strong>shell bash</strong> par défaut, et l'environnement complet dans lequel Git, Node.js et Python s'installent. Tout ce que tu lances dans le terminal WSL tourne dans Ubuntu.</p>",choice:{kind:"structured",main:"Le choix de distribution n'est pas critique pour débuter. Ce qui compte : LTS ou non.",alternatives:[{name:"Ubuntu 22.04 LTS",description:"Recommandé. Support 5 ans, documentation abondante, compatibilité maximale."},{name:"Debian",description:"Plus léger, ultra-stable. Paquets plus vieux. Bon choix serveur, moins pour dev moderne."},{name:"Fedora (WSL)",description:"Utilise dnf à la place d'apt. Paquets plus récents. Si tu connais déjà l'écosystème Red Hat."}]},senior:"<p>Il installe <strong>Ubuntu LTS (Long Term Support)</strong>, jamais la dernière version. La stabilité prime sur la nouveauté dans un environnement de travail quotidien.</p><p>Et il met à jour <strong>immédiatement</strong> après installation. Une distribution fraîche ≠ une distribution à jour — les paquets du CD d'installation peuvent avoir 6 mois de retard.</p>",errors:"<p><strong>Pattern 1 — La version floue :</strong> installer Ubuntu sans spécifier de version → risque de récupérer une version non-LTS qui ne sera plus maintenue dans 9 mois.</p><p><strong>Pattern 2 — L'install immobile :</strong> ne jamais lancer <code>apt update && apt upgrade</code> → paquets obsolètes, dépendances manquantes, erreurs inexplicables lors d'installations futures.</p><p><strong>Pattern 3 — La distro comme identité :</strong> débattre de distributions avant de comprendre apt, le shell et les permissions. Le choix de distro devient une distraction au lieu d'un support de travail.</p>",invariants:"<p>La distribution n'est qu'un packaging du noyau Linux avec des conventions. <strong>Ce qui change : la distribution et son gestionnaire de paquets. Ce qui ne change pas : le besoin d'un environnement Unix cohérent, maintenu, et capable d'installer les outils système.</strong></p>",practice:{commands:[{type:"comment",value:"Dans PowerShell"},{type:"cmd",value:"wsl --install -d Ubuntu-22.04"},{type:"comment",value:"Une fois dans Ubuntu"},{type:"cmd",value:"sudo apt update && sudo apt upgrade -y"},{type:"cmd",value:"lsb_release -a"},{type:"cmd",value:"sudo apt install -y curl git build-essential"}],verification:"lsb_release -a doit afficher une version LTS attendue, puis apt update/upgrade doit s'exécuter sans erreur bloquante.",debt:"Planifier des sessions de mise à jour régulières. `apt` ne met pas à jour automatiquement."},verification:["Pourquoi Ubuntu est-il présenté comme une distribution de travail, et pas comme le cœur du problème à apprendre ?","Tu installes Ubuntu puis tu ne fais jamais apt update : quels symptômes risquent d'apparaître plus tard ?","Ce qui change entre Ubuntu, Debian et Fedora, et ce qui ne change pas pour un développeur qui installe ses outils ?"]}},git:{id:"git",label:"Git",icon:"⎇",kind:"vcs",osLabel:"Tous OS",niveau:"Fondation",sections:{why:"<p>Avant Git, le versioning se faisait en copiant des dossiers : <code>projet_final</code>, <code>projet_final_v2</code>, <code>projet_VRAIMENT_final</code>. En équipe, c'était un enfer — qui a modifié quoi, quand, pourquoi ? Les fusions étaient manuelles et destructrices.</p><p><strong>Git résout ça en traquant chaque changement comme un delta, en permettant des branches parallèles, et en gérant les fusions de façon reproductible.</strong></p>",system:"<p>Git est le tissu conjonctif du workflow entier. Il s'intègre avec <strong>GitHub</strong> (dépôt remote), avec <strong>VS Code</strong> (UI de diff, staging visuel, historique), et avec tous les outils CI/CD dont les pipelines se déclenchent sur des événements Git (push, pull request, tag).</p><p>Sans Git, pas de collaboration structurée possible. Tout le reste assume qu'il existe.</p>",choice:{kind:"structured",main:"Git est le standard incontesté. La vraie décision est sur l'hébergeur remote :",alternatives:[{name:"GitHub",description:"Standard dominant. Plus grand écosystème, GitHub Actions, hiring. Défaut absolu pour commencer."},{name:"GitLab",description:"DevOps plus complet intégré, auto-hébergeable. Bon si CI/CD avancé ou besoin de self-hosting."},{name:"Bitbucket",description:"Atlassian. Pertinent si l'équipe utilise déjà Jira. Pas de raison de choisir sinon."}]},senior:'<p>Il configure son identité globale en premier, avant tout commit. Il comprend les <strong>3 zones distinctes</strong> : working tree (modifications locales), index/staging (ce qui sera commité), remote (GitHub). <code>git add</code> ≠ <code>git commit</code> ≠ <code>git push</code> — trois opérations, trois effets.</p><p>Il écrit des messages de commit utiles : <em>"fix login form validation"</em>, pas <em>"fix bug"</em>. Et il ne commit jamais directement sur <code>main</code>.</p>',errors:`<p><strong>Pattern 1 — Le commit monolithique :</strong> travailler pendant 3 jours et tout commiter d'un coup. Impossible à relire, à revenir en arrière partiellement, à déboguer.</p><p><strong>Pattern 2 — Le .gitignore oublié :</strong> pousser <code>node_modules/</code>, des fichiers <code>.env</code> avec des secrets, des binaires compilés. Le dépôt grossit, les secrets sont exposés.</p><p><strong>Pattern 3 — La confusion push/save :</strong> croire que "commiter" équivaut à "sauvegarder dans le cloud". Il faut aussi push.</p>`,invariants:"<p>Le contrôle de version est un filet de sécurité cognitif — il te permet de prendre des risques en sachant que tu peux revenir en arrière. <strong>Ce qui change : l'outil, l'hébergeur et le workflow de branches. Ce qui ne change pas : le besoin de tracer les changements, collaborer en parallèle, et revenir à un état antérieur.</strong></p>",practice:{commands:[{type:"comment",value:"Windows/Linux (Ubuntu)"},{type:"cmd",value:"sudo apt install -y git"},{type:"comment",value:"macOS (via Homebrew ou CLT)"},{type:"cmd",value:"brew install git"},{type:"comment",value:"Configuration initiale (obligatoire)"},{type:"cmd",value:'git config --global user.name "Ton Nom"'},{type:"cmd",value:'git config --global user.email "ton@email.com"'},{type:"cmd",value:"git config --global init.defaultBranch main"},{type:"cmd",value:"git --version"}],verification:"git --version doit répondre, et git config --global --list doit contenir user.name, user.email et init.defaultBranch.",debt:"Sans configuration user.name/user.email, les commits ne sont pas identifiés correctement."},verification:["Pourquoi Git doit-il être configuré avant les premiers commits, et pas quand le projet devient sérieux ?","Tu fais git add sans .gitignore sur un projet Node : quel dommage devient difficile à nettoyer ?","Ce qui change entre GitHub, GitLab ou Bitbucket, et ce qui ne change pas dans le rôle de Git ?"]}},nodejs:{id:"nodejs",label:"Node.js",icon:"⬡",kind:"runtime",osLabel:"Tous OS - via nvm",niveau:"Fondation",sections:{why:"<p>JavaScript était confiné au navigateur — impossible de l'utiliser côté serveur ou pour des scripts système. <strong>Node.js a extrait le moteur V8 de Chrome et l'a rendu exécutable en dehors du navigateur</strong>, créant un runtime JavaScript universel.</p><p>Résultat : le même langage côté client ET côté serveur, un écosystème npm de 2M+ de bibliothèques, et la base de tout projet frontend moderne (bundlers, transpileurs, frameworks).</p>",system:"<p>Node.js est le runtime qui fait tourner ton code JS/TS. <strong>npm</strong> (inclus) est le gestionnaire de paquets qui donne accès à l'écosystème. Il est nécessaire pour tout projet frontend moderne — React, Vue, etc. — même si le code final tourne dans le navigateur.</p><p>Il s'installe via <strong>nvm</strong> (Node Version Manager), qui s'intercale entre l'OS et Node.js pour permettre de switcher de version selon le projet.</p>",choice:{kind:"structured",main:"Node.js vs ses alternatives récentes — le choix du runtime :",alternatives:[{name:"nvm (recommandé)",description:"Gestionnaire de versions Node. Obligatoire pour gérer plusieurs projets avec des versions différentes."},{name:"Bun",description:"Ultra-rapide (Zig), remplace Node.js + npm + bundler. Compatibilité npm excellente. À considérer pour de nouveaux projets."},{name:"Deno",description:"Même créateur que Node, TypeScript natif, plus sécurisé. Écosystème plus petit. Intéressant mais pas le défaut."}]},senior:`<p>Il ne touche jamais à <code>apt install nodejs</code> — les dépôts Ubuntu ont souvent Node 12 alors qu'on est à Node 22. Tout passe par nvm.</p><p>Il utilise un fichier <strong><code>.nvmrc</code></strong> dans chaque projet avec la version requise. Quand il entre dans le projet, <code>nvm use</code> lit ce fichier et switch automatiquement. Zéro "ça marchait sur ma machine".</p><p>Il distingue clairement <code>dependencies</code> et <code>devDependencies</code> dans package.json.</p>`,errors:"<p><strong>Pattern 1 — L'install directe :</strong> <code>sudo apt install nodejs</code> → version obsolète + conflit avec nvm dans le PATH. Désinstaller et repartir sur nvm.</p><p><strong>Pattern 2 — node_modules dans Git :</strong> oublier <code>node_modules/</code> dans <code>.gitignore</code> → dépôt de 200MB, CI cassé, dépendances sur-committées.</p><p><strong>Pattern 3 — La version instable :</strong> <code>nvm install node</code> sans préciser de version → récupère la latest, pas forcément la LTS.</p>",invariants:"<p>Le runtime est distinct du langage. JavaScript peut tourner dans un navigateur, dans Node.js, dans Deno, dans Bun. <strong>Ce qui change : le runtime, son gestionnaire de paquets et ses performances. Ce qui ne change pas : le besoin d'un moteur qui exécute JavaScript hors du navigateur avec des dépendances reproductibles.</strong></p>",practice:{commands:[{type:"comment",value:"Installer nvm d'abord"},{type:"cmd",value:"curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.7/install.sh | bash"},{type:"cmd",value:"source ~/.bashrc  # ou ~/.zshrc"},{type:"comment",value:"Installer Node.js LTS"},{type:"cmd",value:"nvm install --lts"},{type:"cmd",value:"nvm use --lts"},{type:"cmd",value:"node --version && npm --version"},{type:"comment",value:"Fichier .nvmrc dans chaque projet"},{type:"cmd",value:'echo "lts/*" > .nvmrc'}],verification:"node --version et npm --version doivent répondre depuis le même shell, et nvm current doit correspondre à la version attendue.",debt:"node_modules/ dans .gitignore dès le départ. .nvmrc dans chaque projet dès le départ."},verification:["Pourquoi installer Node via nvm protège-t-il mieux les projets qu'une installation globale via apt ?","Tu clones un projet avec une version Node différente de la tienne : quel rôle joue .nvmrc dans ce scénario ?","Ce qui change entre Node, Bun et Deno, et ce qui ne change pas dans la notion de runtime ?"]}},python:{id:"python",label:"Python",icon:"🐍",kind:"runtime",osLabel:"Tous OS",niveau:"Fondation",sections:{why:"<p>Python s'est imposé comme <strong>lingua franca</strong> du scripting, de la data science, du backend et de l'automatisation. Sa syntaxe lisible, son écosystème (Django, FastAPI, NumPy, Pandas, TensorFlow) et son ubiquité dans les serveurs en font un outil transversal incontournable.</p>",system:"<p>Python coexiste avec Node.js — chaque projet choisit son runtime selon le contexte. <strong>pip</strong> est le gestionnaire de paquets. Les <strong>environnements virtuels</strong> (<code>venv</code>) isolent les dépendances projet par projet, comme <code>node_modules/</code> mais stocké en dehors du projet.</p><p>Il s'intègre avec VS Code via l'extension Python (Pylance), qui active l'autocomplétion, le linting, et la gestion des environnements virtuels.</p>",choice:{kind:"structured",main:"Python 2 est mort depuis 2020 — toujours Python 3. La vraie décision : comment gérer les versions et environnements.",alternatives:[{name:"venv (standard)",description:"Intégré à Python 3, léger, suffisant pour 95% des cas."},{name:"pyenv",description:"Comme nvm pour Python. Gère plusieurs versions de Python. Recommandé si tu jongle entre des projets Python 3.9 / 3.11 / 3.12."},{name:"uv",description:"Nouveau (Rust), ultra-rapide, remplace pip + venv + pyenv en un outil. L'avenir probable. À surveiller."},{name:"conda",description:"Standard data science. Gère aussi les environnements. Lourd pour un projet backend classique."}]},senior:"<p>Il crée <strong>toujours un venv par projet</strong>. Il ne pip-installe jamais globalement — c'est une pollution qui crée des conflits invisibles entre projets.</p><p>Il vérifie toujours avec <code>python3 --version</code> — selon le système, <code>python</code> peut pointer sur Python 2. Il pin ses dépendances dans <code>requirements.txt</code> ou <code>pyproject.toml</code> pour la reproductibilité.</p>",errors:"<p><strong>Pattern 1 — L'install globale :</strong> <code>pip install django</code> sans activer un venv → le package s'installe globalement, pollue l'environnement système, crée des conflits entre projets.</p><p><strong>Pattern 2 — Le venv oublié :</strong> travailler dans un projet sans activer le venv → les imports trouvent les mauvaises versions ou ne trouvent rien.</p><p><strong>Pattern 3 — La confusion python/python3 :</strong> sur certains systèmes, <code>python</code> pointe sur Python 2. Toujours utiliser <code>python3</code> explicitement.</p>",invariants:"<p>La gestion d'environnements isolés par projet est un besoin universel en dev. <strong>Ce qui change : l'outil d'isolation, venv, conda, uv, Docker ou autre. Ce qui ne change pas : les dépendances d'un projet ne doivent pas affecter les autres projets de la machine.</strong></p>",practice:{commands:[{type:"comment",value:"Linux / Windows (Ubuntu/WSL)"},{type:"cmd",value:"sudo apt install -y python3 python3-pip python3-venv"},{type:"comment",value:"macOS (via Homebrew)"},{type:"cmd",value:"brew install python"},{type:"cmd",value:"python3 --version"},{type:"comment",value:"Créer et activer un venv dans chaque projet"},{type:"cmd",value:"python3 -m venv .venv"},{type:"cmd",value:"source .venv/bin/activate"},{type:"cmd",value:"pip install -r requirements.txt"}],verification:"python3 --version doit répondre, et which python après activation doit pointer vers le dossier .venv du projet.",debt:"Ajouter .venv/ dans .gitignore et pin les versions."},verification:["Pourquoi Python exige-t-il une isolation par projet plus tôt qu'on ne le pense ?","Tu installes Django sans venv activé : quel genre de conflit peut apparaître dans un autre projet ?","Ce qui change entre venv, conda et uv, et ce qui ne change pas dans le besoin d'isolation ?"]}},github:{id:"github",label:"GitHub",icon:"⬡",kind:"tool",osLabel:"Tous OS",niveau:"Fondation",sections:{why:"<p>Git est local — il versionne ton code sur ta machine. Sans remote, Git ne sauvegarde pas dans le cloud et ne permet pas la collaboration. <strong>GitHub est le remote : il héberge les dépôts, facilite la collaboration via les Pull Requests, et s'est imposé comme la plateforme sociale du code.</strong></p>",system:"<p>GitHub est le bout de la chaîne : Local (Git) → Remote (GitHub). Il s'intègre aussi avec les pipelines CI/CD via <strong>GitHub Actions</strong>, les revues de code (Pull Requests, code review), et la gestion de projet (Issues, Projects, Milestones).</p><p>Il se connecte à Git via SSH — une clé qu'on génère une fois et qui authentifie tous les push/pull ensuite.</p>",choice:{kind:"structured",main:"GitHub est le défaut incontestable pour commencer. Les alternatives méritent d'être connues :",alternatives:[{name:"GitHub",description:"Standard. Plus grand écosystème, GitHub Actions, communauté open source. Défaut absolu."},{name:"GitLab",description:"DevOps plus complet intégré nativement. Auto-hébergeable. Bon si l'équipe a des besoins CI/CD avancés."},{name:"Bitbucket",description:"Atlassian. Pertinent si l'équipe utilise Jira. Pas de raison de choisir sinon."}]},senior:"<p>Il configure <strong>SSH dès le départ</strong> — pas de HTTP avec mot de passe à chaque push. Une clé <code>ed25519</code> générée une fois, ajoutée sur GitHub, et tous les dépôts sont accessibles sans friction.</p><p>Il sait que <strong>GitHub n'est pas Git</strong>. C'est un service au-dessus de Git, avec ses propres concepts (fork, PR, Actions). Les confondre crée des incompréhensions fondamentales.</p>",errors:"<p><strong>Pattern 1 — Les secrets exposés :</strong> pousser un fichier <code>.env</code> avec des tokens ou mots de passe dans un dépôt public. Exposé en secondes, indexé par des bots. Le <code>.gitignore</code> est non-négociable.</p><p><strong>Pattern 2 — Le commit direct sur main :</strong> en équipe, travailler directement sur <code>main</code> sans branches ni Pull Requests → conflits, historique pollué, pas de revue de code.</p><p><strong>Pattern 3 — La confusion push/sauvegardé :</strong> croire que push = code sauvegardé. Si tu n'as pas commité, push ne fait rien.</p>",invariants:"<p>La distinction local/remote est fondamentale dans tout système distribué. <strong>Ce qui change : l'hébergeur, ses interfaces et ses automatisations. Ce qui ne change pas : le besoin d'un dépôt central partagé pour coordonner, sauvegarder et relire le travail.</strong></p>",practice:{commands:[{type:"comment",value:"Créer un compte sur github.com, puis configurer SSH"},{type:"cmd",value:'ssh-keygen -t ed25519 -C "ton@email.com"'},{type:"comment",value:"Copier la clé publique et l'ajouter dans GitHub > Settings > SSH Keys"},{type:"cmd",value:"cat ~/.ssh/id_ed25519.pub"},{type:"comment",value:"Tester la connexion"},{type:"cmd",value:"ssh -T git@github.com"},{type:"comment",value:"Cloner un dépôt"},{type:"cmd",value:"git clone git@github.com:user/repo.git"}],verification:"ssh -T git@github.com doit confirmer l'authentification, puis git remote -v doit afficher une URL SSH cohérente.",debt:'.env dans .gitignore obligatoire dès le premier commit. Activer "branch protection" sur main.'},verification:["Pourquoi GitHub n'est-il pas Git, même s'il est souvent le premier endroit où l'on voit Git en équipe ?","Tu as commité localement mais tu n'as pas push : qu'est-ce qui existe sur ta machine et qu'est-ce qui n'existe pas encore sur GitHub ?","Ce qui change entre GitHub, GitLab et Bitbucket, et ce qui ne change pas dans la notion de remote ?"]}},apt:{id:"apt",label:"apt",icon:"📦",kind:"infra",osLabel:"Linux / WSL",niveau:"Fondation",sections:{why:"<p>Linux ne vient pas avec un store pour les outils de dev. <strong>apt (Advanced Package Tool) est le gestionnaire de paquets de Debian/Ubuntu</strong> — il installe, met à jour, supprime des logiciels depuis des dépôts centralisés, avec résolution automatique des dépendances. Sans apt, chaque installation est manuelle et sans garde-fou.</p>",system:"<p>apt est l'infrastructure d'installation sur Linux. <strong>Comme Homebrew sur macOS.</strong> Avant d'installer quoi que ce soit, <code>sudo apt update</code> synchronise les listes de paquets disponibles. Il gère les dépendances automatiquement — si git a besoin de libcurl, apt l'installe.</p>",choice:{kind:"structured",main:"apt est imposé par Ubuntu/Debian. Les alternatives existent selon la distribution :",alternatives:[{name:"apt (Debian/Ubuntu)",description:"Standard ici. Large écosystème, documentation abondante."},{name:"dnf / yum (Fedora/RHEL)",description:"Équivalent sur les distributions Red Hat."},{name:"pacman (Arch)",description:"Paquets plus récents, AUR communautaire. Distributions rolling-release."}]},senior:"<p>Il connaît la limite d'apt : <strong>les versions dans les dépôts sont souvent très en retard.</strong> <code>sudo apt install nodejs</code> donne Node 12 sur Ubuntu 20.04. Il utilise apt pour les outils système stables (git, curl, build-essential) et des gestionnaires de version dédiés (nvm, pyenv) pour les runtimes.</p><p>Il fait toujours <code>apt update</code> avant <code>apt install</code>.</p>",errors:"<p><strong>Pattern 1 — L'install de runtime via apt :</strong> <code>sudo apt install nodejs</code> → version obsolète, conflit avec nvm. Utiliser nvm pour Node.js, pas apt.</p><p><strong>Pattern 2 — L'install sans update :</strong> <code>sudo apt install X</code> sans <code>sudo apt update</code> d'abord → paquets introuvables ou version pas à jour dans le cache local.</p><p><strong>Pattern 3 — sudo pip sur le système :</strong> <code>sudo pip install</code> interagit avec Python système et peut casser des outils system critiques.</p>",invariants:"<p>Un gestionnaire de paquets centralise et sécurise les installations — la source est auditée, les dépendances sont résolues, la désinstallation est propre. <strong>Ce qui change : le gestionnaire de paquets, apt, dnf, pacman ou Homebrew. Ce qui ne change pas : le besoin d'un registre central et d'une résolution automatique des dépendances système.</strong></p>",practice:{commands:[{type:"comment",value:"Toujours update avant install"},{type:"cmd",value:"sudo apt update"},{type:"comment",value:"Paquets essentiels pour le dev"},{type:"cmd",value:"sudo apt install -y curl git build-essential python3 python3-pip python3-venv"},{type:"comment",value:"Vérification"},{type:"cmd",value:"apt --version"},{type:"comment",value:"Mise à jour du système"},{type:"cmd",value:"sudo apt update && sudo apt upgrade -y"}],verification:"apt --version doit répondre, et sudo apt update doit synchroniser les dépôts sans erreur critique.",debt:"Ne jamais installer Node.js via apt. Utiliser nvm. Ne jamais pip install --system."},verification:["Pourquoi apt est-il adapté aux paquets système mais pas forcément aux runtimes modernes comme Node.js ?","Tu lances apt install sans apt update depuis longtemps : quel type d'erreur ou de version obsolète peux-tu rencontrer ?","Ce qui change entre apt, dnf et pacman, et ce qui ne change pas dans le rôle d'un gestionnaire de paquets ?"]}},homebrew:{id:"homebrew",label:"Homebrew",icon:"🍺",kind:"infra",osLabel:"macOS uniquement",niveau:"Fondation",sections:{why:"<p>macOS ne vient pas avec un gestionnaire de paquets système pour les outils en ligne de commande. Installer un CLI impliquait de trouver le binaire, le télécharger, le placer dans le bon PATH... <strong>Homebrew a résolu ça en apportant un gestionnaire de paquets moderne sur macOS</strong> — une commande, un outil, une source de vérité.</p>",system:"<p>Homebrew est <strong>l'infrastructure d'installation sur macOS</strong>. Git, Python, nvm, les CLIs — tout passe par Homebrew. Il gère aussi les applications GUI via <code>--cask</code>. Sans Homebrew, chaque outil s'installe via un process différent, souvent manuel.</p><p>Il dépend des Command Line Tools (CLT) — ils doivent être installés en premier.</p>",choice:{kind:"structured",main:"Homebrew n'a pas de vraie alternative sérieuse sur macOS aujourd'hui :",alternatives:[{name:"Homebrew",description:"Standard absolu. Communauté énorme, formules à jour, intégration propre."},{name:"MacPorts",description:"Plus ancien, moins populaire, installe dans /opt/local. Moins de formules. Pas de raison de choisir."},{name:"Nix",description:"Gestion fonctionnelle et reproductible des paquets. Puissant, complexe. Pour des setups avancés."}]},senior:"<p>Il fait la distinction entre <code>brew install</code> (CLIs, outils en ligne de commande) et <code>brew install --cask</code> (applications GUI comme VS Code, Firefox, Docker Desktop).</p><p>Il connaît <code>brew doctor</code> — commande de diagnostic qui révèle les problèmes de configuration. Et il maintient son install avec <code>brew update && brew upgrade</code> régulièrement.</p>",errors:`<p><strong>Pattern 1 — Le mélange des sources :</strong> installer Homebrew ET télécharger manuellement certains outils. Les deux finissent dans le PATH avec des priorités imprévisibles.</p><p><strong>Pattern 2 — L'install sans update :</strong> ne pas lancer <code>brew update</code> depuis longtemps → formules obsolètes, versions trop vieilles, dépendances manquantes lors des nouvelles installations.</p><p><strong>Pattern 3 — Le PATH ignoré :</strong> installer Homebrew correctement mais ne pas appliquer les lignes "Next steps" → brew existe, mais le shell ne le trouve pas.</p>`,invariants:"<p>Tout OS de dev sérieux a besoin d'un gestionnaire de paquets. <strong>Ce qui change : l'outil spécifique à l'OS, Homebrew, apt, dnf ou pacman. Ce qui ne change pas : un registre central de logiciels, des dépendances résolues automatiquement, et une source de vérité unique.</strong></p>",practice:{commands:[{type:"cmd",value:'/bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"'},{type:"comment",value:'Après installation, suivre les instructions "Next steps" dans le terminal'},{type:"cmd",value:"brew doctor"},{type:"cmd",value:"brew --version"},{type:"comment",value:"Usage"},{type:"cmd",value:"brew install git"},{type:"cmd",value:"brew install --cask visual-studio-code"},{type:"cmd",value:"brew update && brew upgrade"}],verification:"brew doctor doit ne signaler aucun problème bloquant, et brew --version doit répondre depuis un nouveau terminal.",debt:"brew update && brew upgrade à lancer régulièrement. brew cleanup pour libérer de l'espace."},verification:["Pourquoi Homebrew doit-il être la source de vérité principale des outils CLI sur macOS ?","Tu installes un outil à la main puis via brew : quel problème de PATH peux-tu créer ?","Ce qui change entre Homebrew et apt, et ce qui ne change pas dans leur rôle systémique ?"]}},clt:{id:"clt",label:"CLT Xcode",icon:"🛠",kind:"infra",osLabel:"macOS uniquement",niveau:"Fondation",sections:{why:`<p>macOS ne vient pas avec les compilateurs et outils Unix de base (clang, gcc, make, ld). Apple les sépare dans les "Command Line Tools" pour Xcode. <strong>Sans eux, Homebrew ne peut pas compiler les paquets, et de nombreux outils de dev refusent de s'installer.</strong> C'est la fondation silencieuse de tout l'environnement de dev macOS.</p>`,system:"<p>Les CLT sont la couche la plus basse de l'environnement macOS. <strong>Homebrew en dépend. Git en dépend (version Apple fournie). C'est la première chose à installer — tout le reste vient après.</strong> Ils fournissent les toolchains de compilation, les headers système, et les utilitaires de base.</p>",choice:{kind:"structured",main:"CLT seuls vs Xcode complet — une question de besoin réel :",alternatives:[{name:"CLT seuls (recommandé)",description:"Légers (~1GB), suffisants pour 99% du dev web/backend/mobile JS. Téléchargement rapide."},{name:"Xcode complet",description:"10GB+. Nécessaire UNIQUEMENT pour dev iOS/macOS natif (Swift, Objective-C). Pas pour le web."}]},senior:"<p>Après chaque <strong>upgrade majeur de macOS</strong>, les CLT peuvent se retrouver invalides — Apple les lie à la version d'OS. Si des outils de build cessent de fonctionner après une mise à jour macOS, c'est souvent là qu'il faut chercher.</p><p><code>xcode-select --install</code> est une commande à connaître par cœur. Simple, rapide, résout 80% des problèmes de toolchain.</p>",errors:"<p><strong>Pattern 1 — L'Xcode inutile :</strong> installer Xcode complet alors qu'on ne développe pas pour iOS → 10GB occupés, mise à jour longue à chaque macOS, sans bénéfice réel.</p><p><strong>Pattern 2 — L'upgrade OS non suivi :</strong> mettre à jour macOS sans vérifier que les CLT suivent → outils de build cassés silencieusement, erreurs cryptiques lors des installations npm ou brew.</p><p><strong>Pattern 3 — Le diagnostic oublié :</strong> réinstaller des dépendances au hasard alors que <code>xcode-select -p</code> aurait montré que la toolchain Apple est absente ou cassée.</p>",invariants:"<p>Tout OS a besoin d'une couche de compilateurs et d'outils de bas niveau pour construire des logiciels. <strong>Ce qui change : la source de la toolchain, Apple CLT, GCC ou MSVC. Ce qui ne change pas : le besoin d'une toolchain de compilation disponible avant d'installer des paquets qui compilent du natif.</strong></p>",practice:{commands:[{type:"cmd",value:"xcode-select --install"},{type:"comment",value:"Une fenêtre graphique s'ouvre pour confirmer l'installation"},{type:"cmd",value:"xcode-select -p"},{type:"comment",value:"Si problème après update macOS"},{type:"cmd",value:"sudo rm -rf /Library/Developer/CommandLineTools"},{type:"cmd",value:"xcode-select --install"}],verification:"xcode-select -p doit retourner un chemin existant vers les Command Line Tools.",debt:"Vérifier après chaque mise à jour majeure de macOS. xcode-select -p doit retourner un path."},verification:["Pourquoi les CLT sont-ils une fondation silencieuse plutôt qu'un outil que tu utilises directement chaque jour ?","Après une mise à jour macOS, brew et npm échouent sur des builds natifs : quelle hypothèse dois-tu vérifier en premier ?","Ce qui change entre CLT, GCC et MSVC, et ce qui ne change pas dans le besoin de compilation ?"]}},shell:{id:"shell",label:"Shell",icon:">_",kind:"infra",osLabel:"macOS / Linux",niveau:"Intermédiaire",sections:{why:"<p>Le shell est l'interface entre le développeur et l'OS. Il interprète les commandes, gère les pipes, les redirections, les variables d'environnement, les scripts. <strong>C'est le langage de la machine — ce que les interfaces graphiques cachent, le shell l'expose directement.</strong></p>",system:"<p>Tout ce qui se passe dans le terminal passe par le shell. Le <strong>PATH</strong> (où l'OS cherche les binaires), les alias, les exports de variables d'environnement — tout est configuré dans le fichier de config du shell (<code>.zshrc</code>, <code>.bashrc</code>).</p><p>nvm, Homebrew, et la plupart des CLIs s'installent en ajoutant des lignes dans ce fichier. <strong>Le shell est le point de convergence de tout le tooling.</strong></p>",choice:{kind:"structured",main:"Le shell est dicté par l'OS par défaut, mais configurable :",alternatives:[{name:"zsh (recommandé macOS)",description:"Défaut sur macOS depuis Catalina. Plus de features que bash, oh-my-zsh, plugins. Standard moderne."},{name:"bash",description:"Universel, présent sur tout Unix. Plus compatible, moins de features. Défaut sur Linux."},{name:"fish",description:"Syntax différente (non-POSIX), autocomplétion très avancée. Incompatible avec certains scripts bash. Pour plus tard."},{name:"nushell",description:"Shell structuré ultra-moderne. Rupture complète avec le paradigme texte. Expérimental en prod."}]},senior:"<p>Il sait exactement ce qu'il y a dans son <code>.zshrc</code>/<code>.bashrc</code>. <strong>Chaque ligne a une raison d'être documentée.</strong> Il versionne ce fichier (dotfiles dans un repo Git) pour retrouver son environnement sur n'importe quelle machine.</p><p>Il comprend la différence entre <code>.zshrc</code> (shell interactif) et <code>.zprofile</code> (shell de login) — confondre les deux crée des bugs subtils selon comment le terminal est lancé.</p>",errors:`<p><strong>Pattern 1 — Le copier-coller aveugle :</strong> copier des lignes dans <code>.zshrc</code> depuis Stack Overflow sans comprendre. Résultat : PATH corrompu, outils introuvables, shell lent à démarrer.</p><p><strong>Pattern 2 — oh-my-zsh sans entretien :</strong> installer 30 plugins oh-my-zsh et ne jamais les auditer → shell qui met 3 secondes à démarrer. Moins c'est plus.</p><p><strong>Pattern 3 — Modifier PATH sans comprendre :</strong> ajouter des chemins dans le mauvais ordre peut "cacher" des binaires système par d'autres, créant des comportements inattendus.</p>`,invariants:"<p>Le shell est la couche d'automatisation fondamentale. <strong>Ce qui change : le shell, bash, zsh, fish ou nushell, et sa syntaxe. Ce qui ne change pas : le besoin d'une interface scriptable avec l'OS, le PATH, les variables d'environnement et les commandes réelles.</strong></p>",practice:{commands:[{type:"comment",value:"Vérifier le shell actuel"},{type:"cmd",value:"echo $SHELL"},{type:"comment",value:"Installer zsh (Linux)"},{type:"cmd",value:"sudo apt install -y zsh"},{type:"cmd",value:"chsh -s $(which zsh)"},{type:"comment",value:"Recharger la config après modification"},{type:"cmd",value:"source ~/.zshrc"},{type:"comment",value:"oh-my-zsh (optionnel)"},{type:"cmd",value:'sh -c "$(curl -fsSL https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)"'}],verification:"echo $SHELL doit afficher le shell attendu, et source ~/.zshrc ne doit pas produire d'erreur.",debt:'Versionner .zshrc dans un repo "dotfiles". Documenter chaque ajout avec un commentaire.'},verification:["Pourquoi modifier le shell sans comprendre le PATH peut-il casser tout l'environnement de dev ?","Tu copies une ligne dans .zshrc et node disparaît du terminal : quelle zone du système dois-tu inspecter ?","Ce qui change entre bash, zsh et fish, et ce qui ne change pas dans le rôle du shell ?"]}}},maps:{windows:{viewBox:"0 0 860 260",nodes:[{id:"wsl",x:30,y:90,w:110,h:70},{id:"ubuntu",x:180,y:90,w:110,h:70},{id:"git",x:340,y:30,w:110,h:70},{id:"nodejs",x:340,y:150,w:110,h:70},{id:"python",x:500,y:90,w:110,h:70},{id:"vscode",x:660,y:30,w:130,h:70},{id:"github",x:670,y:150,w:110,h:70}],edges:[{x1:140,y1:125,x2:178,y2:125,label:"héberge"},{x1:290,y1:105,x2:338,y2:75,label:"outils"},{x1:290,y1:145,x2:338,y2:175,label:"runtime"},{x1:450,y1:65,x2:498,y2:110,label:"coexiste"},{x1:450,y1:185,x2:498,y2:140,label:"scripts"},{x1:610,y1:110,x2:658,y2:80,label:"édite"},{x1:610,y1:120,x2:668,y2:170,label:"remote"},{x1:450,y1:80,x2:658,y2:60,label:"intègre"}]},macos:{viewBox:"0 0 900 260",nodes:[{id:"clt",x:20,y:90,w:100,h:70},{id:"homebrew",x:170,y:90,w:120,h:70},{id:"git",x:340,y:30,w:110,h:70},{id:"nodejs",x:340,y:150,w:110,h:70},{id:"python",x:500,y:90,w:110,h:70},{id:"shell",x:500,y:175,w:110,h:70},{id:"vscode",x:665,y:30,w:120,h:70},{id:"github",x:665,y:150,w:110,h:70}],edges:[{x1:120,y1:125,x2:168,y2:125,label:"requiert"},{x1:290,y1:105,x2:338,y2:70,label:"installe"},{x1:290,y1:140,x2:338,y2:178,label:"installe"},{x1:450,y1:65,x2:498,y2:105,label:"coexiste"},{x1:610,y1:110,x2:663,y2:75,label:"édite"},{x1:610,y1:130,x2:663,y2:170,label:"remote"}]},linux:{viewBox:"0 0 820 260",nodes:[{id:"apt",x:20,y:90,w:100,h:70},{id:"git",x:170,y:30,w:110,h:70},{id:"nodejs",x:170,y:150,w:110,h:70},{id:"python",x:340,y:90,w:110,h:70},{id:"shell",x:340,y:175,w:110,h:70},{id:"vscode",x:510,y:30,w:120,h:70},{id:"github",x:510,y:150,w:110,h:70}],edges:[{x1:120,y1:105,x2:168,y2:70,label:"installe"},{x1:120,y1:140,x2:168,y2:175,label:"runtime"},{x1:280,y1:65,x2:338,y2:110,label:"coexiste"},{x1:450,y1:110,x2:508,y2:75,label:"édite"},{x1:450,y1:125,x2:508,y2:175,label:"remote"}]}}},s={id:"initialisation-projet",part:"T",number:2,title:"Initialisation du Projet",subtitle:"Poser les fondations avant la première fonctionnalité",badge:"Fiche T02 — Vision Systémique",status:"Modèle stabilisé",meta:["9 nœuds · 2 types","8 sections / nœud"],category:"Technique",level:"Débutant → Junior",readingTime:"30 min",description:"Une carte interactive pour initialiser proprement un projet JavaScript ou Python : Git, structure, dépendances, environnement, qualité et commits.",accent:"vcs",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{"git-init":{id:"git-init",label:"Git Init",icon:"⎇",kind:"vcs",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Un projet sans contrôle de version, c'est du code sans filet. Chaque modification peut en détruire une autre sans possibilité de revenir en arrière. Git init crée le dépôt local — la première étape avant d'écrire une seule ligne de code. L'ordre est non-négociable : on initialise Git avant tout le reste, pas après.</p>",system:"<p>Git init est le point de départ de la chaîne entière. Le .gitignore dépend de lui. Le README.md est le premier fichier commité. Les conventions de commit s'appliquent dès le premier commit. GitHub (remote) est connecté après l'init local. C'est la fondation structurelle sur laquelle tout le reste repose.</p>",choice:{kind:"structured",main:"<p>Deux cas d'usage : <code>init</code> (nouveau projet local) ou <code>clone</code> (projet existant sur GitHub). Si le projet existe déjà sur GitHub, toujours clone, jamais init + remote add — c'est une étape inutile. Alternatives au workflow mono-repo classique : monorepo (Turborepo, Nx) pour plusieurs projets liés, multi-repo pour des services indépendants. Pour débuter : un projet = un dépôt.</p>",alternatives:[{name:"git init",description:"Nouveau projet local à créer depuis zéro."},{name:"git clone",description:"Projet existant sur GitHub. À privilégier dès qu'un remote existe déjà."},{name:"Monorepo",description:"Plusieurs projets liés dans un seul dépôt, utile quand l'écosystème grandit."}]},senior:`<p>Il initialise Git avant d'écrire du code, pas après. Il crée immédiatement le .gitignore et le README.md avant le premier commit — pour ne jamais commiter des fichiers qui n'auraient pas dû l'être. Il configure la branche principale sur "main" dès le départ (<code>git init -b main</code>). Il fait un premier commit propre avec juste la structure de base, avant d'ajouter la moindre dépendance.</p>`,errors:"<p><strong>Pattern 1 — L'init tardif :</strong> commencer à coder, puis initialiser Git. Résultat : premier commit géant de 50 fichiers, historique illisible dès le départ, impossible à isoler les responsabilités.</p><p><strong>Pattern 2 — Le clone HTTPS :</strong> cloner en HTTPS au lieu de SSH quand GitHub est déjà configuré en SSH → saisir le mot de passe ou token à chaque push. Toujours SSH.</p><p><strong>Pattern 3 — Le git add . prématuré :</strong> faire <code>git add .</code> avant d'avoir créé le .gitignore → node_modules, .env, fichiers compilés dans l'historique pour toujours. Irréversible proprement.</p>",invariants:"<p>Tout projet de code sérieux vit dans un dépôt versionné. Le moment de l'init n'est pas négociable : avant le premier fichier de code. <strong>Ce qui change : l'hébergeur, GitHub ou GitLab, et le workflow de branches. Ce qui ne change pas : l'init en premier, le .gitignore avant le premier add, et un historique lisible dès le départ.</strong></p>",practice:{commands:[{type:"cmd",value:"git init -b main                                    # nouveau projet, branche main"},{type:"cmd",value:"git clone git@github.com:user/repo.git              # projet existant (SSH)"},{type:"cmd",value:"git remote add origin git@github.com:user/repo.git  # lier un init local à GitHub"},{type:"cmd",value:"git remote -v                                       # vérifier la connexion remote"},{type:"comment",value:"Vérification : ls -la → doit voir un dossier .git/"}],verification:"ls -la doit montrer un dossier .git/, et git remote -v doit afficher le remote dès qu'il est connecté.",debt:"Un dépôt sans remote = pas de backup. Connecter GitHub immédiatement après l'init."},verification:["Pourquoi Git doit-il être initialisé avant le premier vrai fichier de code ?","Tu fais git add . avant de créer .gitignore : quel type de fichiers peut entrer dans l'historique pour longtemps ?","Ce qui change entre git init, git clone et un monorepo, et ce qui ne change pas dans le besoin de versionner ?"]}},gitignore:{id:"gitignore",label:".gitignore",icon:"🚫",kind:"infra",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Git traque tout par défaut. Mais un projet contient des fichiers qui ne doivent jamais être versionnés : les dépendances (node_modules — des centaines de MB), les secrets (.env avec API keys), les fichiers compilés (dist/, __pycache__), les configurations locales (.DS_Store, .idea/). Le .gitignore dit à Git quoi ignorer. Sans lui, le premier <code>git add .</code> est un désastre silencieux dont on hérite pour toute la vie du dépôt.</p>",system:"<p>Le .gitignore doit être le deuxième fichier créé après git init, avant le premier commit. Il protège tout le reste du système : empêche que node_modules soit commité, que .env soit exposé, que les fichiers de build polluent l'historique. C'est un gardien passif mais critique — il ne fait rien d'actif, mais son absence crée des dégâts permanents.</p>",choice:{kind:"structured",main:"<p>Écrire son .gitignore manuellement ou partir d'un template (gitignore.io, ou sélection GitHub à la création du repo). Toujours partir d'un template adapté au stack et l'ajuster. La règle de décision : si un fichier peut être régénéré (node_modules depuis package.json, dist depuis le build, .venv depuis requirements.txt), il n'appartient pas au dépôt. Un .gitignore global personnel (<code>~/.gitignore_global</code>) pour les fichiers système qui ne concernent pas le projet (.DS_Store, .idea/).</p>",alternatives:[{name:"Template stack",description:"Base sûre pour JavaScript, Python, IDE et OS courants."},{name:"Manuel",description:"Possible, mais plus risqué au début."},{name:"Global personnel",description:"Pour les fichiers de machine qui ne concernent pas le projet."}]},senior:"<p>Il crée le .gitignore avant le premier <code>git add</code> — jamais après. Il sait que si un fichier est déjà commité, l'ajouter au .gitignore ne le supprime pas de l'historique (il faut <code>git rm --cached</code>). Il versionne toujours un <code>.env.example</code> avec des valeurs vides pour documenter les variables nécessaires, sans exposer de vraies valeurs.</p>",errors:`<p><strong>Pattern 1 — Le .gitignore tardif :</strong> <code>git add .</code> avant le .gitignore → node_modules ou .env dans le dépôt. Récupérer nécessite <code>git rm -r --cached</code> + commit + réécriture de l'historique si des secrets sont en jeu.</p><p><strong>Pattern 2 — Le secret commité :</strong> pousser un .env avec de vraies API keys → invalider toutes les clés immédiatement. Elles sont exposées même en dépôt "privé" — les accès futurs, les forks, les collaborateurs voient l'historique.</p><p><strong>Pattern 3 — Le .gitignore trop permissif :</strong> ignorer des dossiers entiers par paresse → fichiers de configuration importants ignorés accidentellement, absents du dépôt.</p>`,invariants:"<p>Les fichiers régénérables ne se committent pas. Les secrets ne se committent jamais. <strong>Ce qui change : les patterns spécifiques au stack, Node, Python, IDE ou OS. Ce qui ne change pas : la séparation entre ce qui appartient au dépôt et ce qui n'y appartient pas.</strong></p>",practice:{commands:[{type:"comment",value:"JavaScript minimum"},{type:"snippet",value:"node_modules/"},{type:"snippet",value:"dist/"},{type:"snippet",value:".env"},{type:"snippet",value:"coverage/"},{type:"comment",value:"Python minimum"},{type:"snippet",value:".venv/"},{type:"snippet",value:"__pycache__/"},{type:"snippet",value:"*.pyc"},{type:"snippet",value:"*.egg-info/"},{type:"comment",value:"Commandes"},{type:"cmd",value:"touch .gitignore"},{type:"cmd",value:"git check-ignore -v nomfichier"},{type:"cmd",value:"git rm --cached nomfichier"}],verification:"git status ne doit pas lister node_modules, .venv, .env ou des fichiers de build comme fichiers non suivis.",debt:"Fichiers sensibles déjà dans l'historique → BFG Repo Cleaner ou git filter-repo pour nettoyer."},verification:["Pourquoi un .gitignore créé après le premier git add arrive-t-il trop tard ?","Tu as déjà commité .env puis tu l'ajoutes au .gitignore : qu'est-ce que cela corrige, et qu'est-ce que cela ne corrige pas ?","Ce qui change entre un .gitignore JavaScript et Python, et ce qui ne change pas dans la logique d'exclusion ?"]}},structure:{id:"structure",label:"Structure",icon:"🗂",kind:"infra",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Un projet sans structure explicite devient ingérable passé quelques fichiers. Quand tout est à la racine ou organisé arbitrairement, retrouver un fichier, comprendre où ajouter du code, onboarder un nouveau dev — tout devient coûteux. La structure de dossiers est une décision d'architecture, pas de rangement. Elle encode les intentions du projet.</p>",system:"<p>La structure est le conteneur de tout le reste. Elle détermine où vivent le code source (src/), les tests (tests/), la configuration (à la racine ou config/), les assets (public/). Les outils cherchent leurs fichiers de config à des emplacements conventionnels — ESLint à la racine, pytest dans tests/, TypeScript dans tsconfig.json. Une structure qui respecte ces conventions évite la friction avec le tooling.</p>",choice:{kind:"structured",main:"<p>Deux philosophies : organisation par type de fichier (tous les composants ensemble, tous les services ensemble — simple, prévisible pour les petits projets) vs organisation par feature (tout ce qui concerne une feature ensemble — scalable, meilleur pour les grands projets). Pour débuter : par type. La structure doit aussi suivre les conventions du framework — React, Express, Django, FastAPI ont chacun leurs idiomes. Lutter contre ces conventions coûte cher.</p>",alternatives:[{name:"Par type",description:"Simple et prévisible pour démarrer."},{name:"Par feature",description:"Plus scalable quand le produit grandit."},{name:"Convention framework",description:"À suivre par défaut pour éviter la friction."}]},senior:"<p>Il ne sur-architecture pas dès le départ. Un projet de 3 fichiers n'a pas besoin de 8 dossiers. Il crée la structure minimale qui reflète l'intention, et laisse évoluer organiquement. Il documente les conventions dans le README (où va quoi, pourquoi). Il anticipe les exigences du framework plutôt que d'inventer une structure maison qui devra être refactorisée.</p>",errors:"<p><strong>Pattern 1 — La sur-architecture prématurée :</strong> créer une structure de grande entreprise pour un projet solo → overhead cognitif, dossiers vides qui attendent du code qui ne viendra peut-être pas, paralysie.</p><p><strong>Pattern 2 — Tout à la racine :</strong> 50 fichiers à la racine → navigation impossible, pas de séparation des responsabilités, impossible de comprendre le projet d'un regard.</p><p><strong>Pattern 3 — Ignorer les conventions du framework :</strong> React attend src/components, Express attend routes/, Django impose son propre layout. Inventer une structure alternative crée une friction permanente avec les outils et la documentation.</p>",invariants:`<p>La structure doit répondre à une question : "où dois-je chercher X ?" Si la réponse n'est pas évidente, la structure est insuffisante. <strong>Ce qui change : les dossiers spécifiques au langage, au framework et à la taille du projet. Ce qui ne change pas : l'exigence de lisibilité intentionnelle.</strong></p>`,practice:{commands:[{type:"comment",value:"JavaScript/Node"},{type:"snippet",value:"project/src/index.js"},{type:"snippet",value:"project/tests/"},{type:"snippet",value:"project/public/"},{type:"snippet",value:"project/package.json"},{type:"comment",value:"Python"},{type:"snippet",value:"project/src/__init__.py"},{type:"snippet",value:"project/src/main.py"},{type:"snippet",value:"project/tests/"},{type:"snippet",value:"project/requirements.txt"},{type:"comment",value:"Commandes"},{type:"cmd",value:"mkdir -p src tests public"},{type:"cmd",value:"touch src/index.js README.md .gitignore .env.example"}],verification:"La racine doit rester lisible, et un nouveau fichier doit avoir un emplacement évident sans demander au hasard.",debt:"Structure trop rigide trop tôt → refactoring coûteux. Documenter les conventions dans le README dès le départ."},verification:["Pourquoi la structure d'un projet est-elle une décision d'architecture plutôt qu'un simple rangement ?","Tu as 50 fichiers à la racine : quelles questions deviennent coûteuses pour un nouveau développeur ?","Ce qui change entre une structure par type et par feature, et ce qui ne change pas dans le besoin de lisibilité ?"]}},readme:{id:"readme",label:"README.md",icon:"📄",kind:"tool",osLabel:"Universel",niveau:"Fondation",sections:{why:`<p>Un projet sans README est un projet fermé. La première question de n'importe qui qui arrive sur le dépôt — y compris soi-même dans 3 mois — est : "qu'est-ce que c'est et comment ça marche ?". Le README est la porte d'entrée. Sans lui, le projet n'existe pas vraiment pour les autres. Il est affiché automatiquement sur GitHub, c'est la première chose que tout le monde voit.</p>`,system:"<p>Le README est le premier fichier commité avec le .gitignore. Il documente les prérequis (versions de Node ou Python requises — renvoi à la fiche #01), les commandes pour installer et lancer le projet, la structure du code, les conventions. Il est vivant : il évolue avec le projet et doit rester à jour. Un README obsolète est activement nuisible — plus trompeur qu'une absence.</p>",choice:{kind:"structured",main:"<p>Markdown est le standard incontesté sur GitHub. La vraie décision est sur la profondeur : minimaliste (juste assez pour lancer le projet) vs exhaustif (architecture, décisions techniques, API reference). Pour débuter : minimaliste mais complet — description, prérequis, installation, lancement, variables d'environnement. Pour une documentation plus poussée : un dossier docs/ avec MkDocs (Python) ou Docusaurus (JS).</p>",alternatives:[{name:"Minimaliste complet",description:"Description, prérequis, installation, lancement, env vars."},{name:"docs/",description:"Documentation longue séparée du README."},{name:"Site docs",description:"MkDocs ou Docusaurus quand la doc devient un produit."}]},senior:`<p>Il écrit le README avant d'écrire du code — pas après. Rédiger le README en premier force à clarifier les intentions du projet et les prérequis. Il inclut toujours une section "Prérequis" (versions exactes) et "Démarrage rapide" (commandes dans l'ordre exact, sans rien omettre). Il traite le README comme du code : une PR qui change le comportement du projet met à jour le README.</p>`,errors:"<p><strong>Pattern 1 — Le README fantôme :</strong> créer le fichier vide et ne jamais le remplir → GitHub affiche un fichier vide, le projet semble abandonné ou inachevé.</p><p><strong>Pattern 2 — Le README gelé :</strong> écrire un bon README au début puis ne jamais le mettre à jour → les instructions deviennent incorrectes, les développeurs suivent une documentation qui ne correspond plus à la réalité.</p><p><strong>Pattern 3 — Le README bavard sans structure :</strong> prose sans titres Markdown, pas de code blocks pour les commandes, pas de section claire → illisible, les infos importantes sont introuvables.</p>",invariants:"<p>Tout projet partagé a besoin d'une porte d'entrée textuelle. <strong>Ce qui change : l'outil de documentation, Markdown, reStructuredText, Confluence ou un site docs. Ce qui ne change pas : le besoin de répondre à trois questions — qu'est-ce que c'est, comment ça marche, comment contribuer.</strong></p>",practice:{commands:[{type:"cmd",value:"touch README.md"},{type:"comment",value:"# Nom du Projet"},{type:"comment",value:"## Prérequis"},{type:"comment",value:"## Installation"},{type:"comment",value:"## Lancement"},{type:"comment",value:"## Variables d'environnement"},{type:"comment",value:"## Structure du projet"}],verification:"La page GitHub du dépôt doit afficher un README utile avec prérequis, installation, lancement et variables d'environnement.",debt:'README non mis à jour = documentation mensongère. Ajouter "mise à jour du README si nécessaire" dans la checklist de PR.'},verification:["Pourquoi écrire le README tôt force-t-il à clarifier le projet avant même de coder ?","Tu reviens sur ton projet dans trois mois et le README est vide : quelles informations dois-tu reconstruire ?","Ce qui change entre README, docs/ et site de documentation, et ce qui ne change pas dans leur rôle d'entrée ?"]}},"env-vars":{id:"env-vars",label:".env",icon:"🔐",kind:"infra",osLabel:"Universel",niveau:"Fondation",sections:{why:"<p>Une application a besoin de configuration qui varie selon l'environnement (dev, staging, prod) et qui est sensible (API keys, mots de passe, tokens). Hardcoder ces valeurs dans le code est une erreur critique : elles finissent dans Git, elles sont exposées, et elles ne peuvent pas varier selon l'environnement sans modifier le code. Le fichier .env centralise cette configuration hors du code.</p>",system:"<p>Le .env est chargé au démarrage de l'application via une librairie (dotenv en JS, python-dotenv en Python). Il est dans .gitignore — il ne sera jamais commité. Son jumeau <code>.env.example</code> (commité, valeurs vides ou factices) documente quelles variables sont nécessaires. En production, les variables sont injectées via le système de déploiement (Vercel, Railway, Docker, GitHub Actions secrets) — le fichier .env n'existe pas en prod.</p>",choice:{kind:"structured",main:"<p>dotenv (JS) ou python-dotenv (Python) pour charger le .env en développement. En production : variables d'environnement injectées par la plateforme de déploiement — jamais un fichier .env sur le serveur. Pour les projets avec beaucoup de secrets ou plusieurs environnements : Doppler, HashiCorp Vault, ou AWS Secrets Manager. Pour débuter : .env en dev, variables natives en prod.</p>",alternatives:[{name:"dotenv",description:"Simple, local, parfait pour le développement."},{name:"Secrets plateforme",description:"Vercel, Railway, Docker, GitHub Actions en production."},{name:"Vault / Doppler",description:"Gestion avancée quand les environnements se multiplient."}]},senior:"<p>Il crée .env.example avec toutes les variables et des valeurs factices dès le début du projet. Il documente chaque variable avec un commentaire inline (à quoi elle sert, où la trouver). Il valide les variables d'environnement au démarrage de l'application — une variable manquante doit faire planter l'app immédiatement avec un message clair, pas créer une erreur obscure 3 niveaux plus bas.</p>",errors:`<p><strong>Pattern 1 — Le secret commité :</strong> pousser .env avec de vraies valeurs → invalider toutes les clés immédiatement. Même en repo privé, l'historique Git est permanent. Les bots qui scannent GitHub trouvent les clés en quelques minutes.</p><p><strong>Pattern 2 — Pas de .env.example :</strong> un nouveau dev clone le projet, rien ne fonctionne, il ne sait pas quelles variables configurer. Onboarding cassé.</p><p><strong>Pattern 3 — Variables hardcodées "provisoirement" :</strong> mettre l'API key directement dans le code "pour aller vite" → toujours là 6 mois plus tard, en production.</p>`,invariants:"<p>Configuration ≠ code. Ce qui varie entre les environnements n'appartient pas au code source. <strong>Ce qui change : le mécanisme, .env, Vault, SSM Parameter Store ou secrets de plateforme. Ce qui ne change pas : la séparation entre configuration, secrets et code versionné.</strong></p>",practice:{commands:[{type:"comment",value:"Contenu .env.example"},{type:"snippet",value:"DATABASE_URL=postgresql://user:password@localhost:5432/dbname"},{type:"snippet",value:"JWT_SECRET=your-secret-key-here"},{type:"snippet",value:"PORT=3000"},{type:"snippet",value:"NODE_ENV=development"},{type:"comment",value:"Installation JS"},{type:"cmd",value:"npm install dotenv"},{type:"comment",value:"Installation Python"},{type:"cmd",value:"pip install python-dotenv"}],verification:".env doit être ignoré par Git, et .env.example doit lister toutes les variables nécessaires sans vraie valeur sensible.",debt:"Variables non documentées dans .env.example = dette de connaissance. Validation des env vars au démarrage à implémenter dès que le projet grandit."},verification:["Pourquoi hardcoder une API key dans le code mélange-t-il deux responsabilités différentes ?","Un nouveau dev clone le projet sans .env.example : où l'onboarding casse-t-il concrètement ?","Ce qui change entre .env local, secrets de plateforme et Vault, et ce qui ne change pas dans la séparation configuration/code ?"]}},commits:{id:"commits",label:"Commits",icon:"✍",kind:"vcs",osLabel:"Universel",niveau:"Intermédiaire",sections:{why:`<p>Un historique Git sans conventions ressemble à : "fix", "wip", "ok", "test2", "vraiment fix cette fois". Impossible de comprendre ce qui a changé, pourquoi, ni de générer un changelog automatique. Les conventions de commit transforment l'historique en documentation navigable et permettent l'automatisation (changelogs générés, versioning sémantique automatique, releases).</p>`,system:"<p>Les conventions de commit s'appliquent à chaque <code>git commit</code> du projet. Elles s'intègrent avec commitlint (vérifie le format du message avant validation), husky (exécute commitlint via git hooks), et semantic-release (génère automatiquement versions et changelogs à partir des types de commits). Elles sont aussi lues par GitHub pour l'affichage des PRs et Issues.</p>",choice:{kind:"structured",main:"<p>Standard dominant : Conventional Commits. Format : <code>type(scope): description</code>. Types courants : <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>chore</code>, <code>refactor</code>, <code>test</code>, <code>ci</code>. Alternatives : Gitmoji, format maison. Conventional Commits est recommandé — outillage, intégration CI, standard industrie largement adopté.</p>",alternatives:[{name:"Conventional Commits",description:"Standard recommandé, automatisable et lisible."},{name:"Gitmoji",description:"Fun, mais moins lisible pour CI/changelog."},{name:"Format maison",description:"Possible, mais demande discipline et outillage."}]},senior:"<p>Il établit la convention dès le premier commit. Il installe commitlint + husky pour que la convention soit appliquée par des outils — pas par bonne volonté. Il sait que la convention n'a de valeur que si elle est appliquée mécaniquement : laissée au jugement, elle dégénère sous la pression.</p>",errors:`<p><strong>Pattern 1 — Les commits vagues :</strong> "fix", "update", "WIP", "changes" → historique inutile, aucune traçabilité, impossible de comprendre l'évolution du projet.</p><p><strong>Pattern 2 — Le commit fourre-tout :</strong> un commit qui touche 3 features et 2 bug fixes → impossible de revenir sur une seule modification, bisect inutilisable.</p><p><strong>Pattern 3 — La convention déclarée mais non appliquée :</strong> convention dans le README, pas de commitlint → ignorée sous la pression des deadlines après 2 semaines.</p>`,invariants:`<p>Un commit = une intention. Un message de commit doit répondre à : "qu'est-ce qui change et pourquoi ?" — pas "qu'est-ce que j'ai fait". <strong>Ce qui change : la syntaxe, Conventional Commits, Gitmoji ou format maison. Ce qui ne change pas : l'exigence d'un historique lisible, atomique et utile pour revenir en arrière.</strong></p>`,practice:{commands:[{type:"comment",value:"Exemples valides"},{type:"snippet",value:"feat(auth): add JWT refresh token rotation"},{type:"snippet",value:"fix(api): handle null response from payment gateway"},{type:"snippet",value:"docs(readme): update Node.js version requirement"},{type:"snippet",value:"chore(deps): upgrade eslint from 8 to 9"},{type:"comment",value:"Installation commitlint + husky"},{type:"cmd",value:"npm install --save-dev @commitlint/cli @commitlint/config-conventional husky"},{type:"cmd",value:"npx husky init"}],verification:"Un commit invalide doit être rejeté si commitlint est configuré, et git log --oneline doit rester lisible.",debt:"Pas de git hooks → convention non appliquée → historique dégradé progressivement sous la pression."},verification:["Pourquoi une convention de commit ne vaut presque rien si elle n'est pas appliquée mécaniquement ?","Tu lis un historique rempli de fix, update et wip : qu'est-ce qui devient impossible à comprendre ?","Ce qui change entre Conventional Commits, Gitmoji et un format maison, et ce qui ne change pas dans le rôle du message ?"]}},"package-json":{id:"package-json",label:"package.json",icon:"{}",kind:"tool",osLabel:"JavaScript uniquement",niveau:"Fondation",sections:{why:"<p>Un projet JavaScript sans package.json est un projet sans identité et sans gestion reproductible des dépendances. Le package.json est le manifeste : il déclare ce qu'est le projet (nom, version, description), ce dont il a besoin (dépendances), et comment l'utiliser (scripts). Sans lui, partager le projet ou le reproduire sur une autre machine requiert une documentation manuelle exhaustive — ce qui échoue toujours.</p>",system:"<p>package.json est le centre de gravité d'un projet JS. npm/yarn/pnpm le lisent pour installer les dépendances. Les outils (ESLint, Prettier, TypeScript, Jest) y cherchent leur configuration. Les scripts (start, build, test, dev) y sont définis et constituent l'interface standardisée du projet. Le package-lock.json est généré à partir de lui et doit être commité — c'est lui qui garantit la reproductibilité exacte.</p>",choice:{kind:"structured",main:"<p><code>npm init -y</code> pour générer rapidement, puis modifier manuellement les champs importants. La vraie décision : quel gestionnaire de paquets ? npm, yarn, pnpm. Pour débuter : npm. Le choix doit être cohérent dans le projet — un seul gestionnaire, un seul lock file.</p>",alternatives:[{name:"npm",description:"Universel, inclus avec Node, syntaxe de référence."},{name:"yarn",description:"Bon pour les workspaces, historiquement plus rapide."},{name:"pnpm",description:"Plus strict, plus économe en espace disque."}]},senior:"<p>Il distingue <code>dependencies</code> (nécessaires en production — Express, React) de <code>devDependencies</code> (dev uniquement — ESLint, Prettier, Jest, TypeScript). Il définit des scripts standards : <code>dev</code>, <code>build</code>, <code>test</code>, <code>lint</code>. Il spécifie la version de Node requise dans le champ <code>engines</code>. Il commit toujours le lock file.</p>",errors:`<p><strong>Pattern 1 — Le lock file ignoré :</strong> mettre package-lock.json dans .gitignore → chaque dev installe des versions potentiellement différentes.</p><p><strong>Pattern 2 — Tout en dependencies :</strong> mettre ESLint, types TypeScript, librairies de test dans <code>dependencies</code> au lieu de <code>devDependencies</code>.</p><p><strong>Pattern 3 — Les scripts absents ou non-standard :</strong> pas de script "dev", chaque dev lance l'app à sa façon.</p>`,invariants:"<p>Tout projet avec des dépendances a besoin d'un manifeste déclaratif et versionné. <strong>Ce qui change : le format, package.json, requirements.txt, pyproject.toml, go.mod ou Cargo.toml. Ce qui ne change pas : le besoin de déclarer l'identité du projet, ses dépendances et ses commandes de façon reproductible.</strong></p>",practice:{commands:[{type:"cmd",value:"npm init -y"},{type:"cmd",value:"npm install"},{type:"cmd",value:"npm install express"},{type:"cmd",value:"npm install --save-dev eslint"},{type:"comment",value:"Scripts recommandés : dev, start, test, lint, format"}],verification:"package.json doit contenir scripts, dependencies/devDependencies, engines si la version Node est importante, et un lock file commité.",debt:"Lock file non commité → reproductibilité cassée. Scripts non définis → onboarding difficile."},verification:["Pourquoi package.json est-il un manifeste du projet, et pas seulement une liste de librairies ?","Tu ignores package-lock.json : pourquoi deux machines peuvent-elles installer des arbres de dépendances différents ?","Ce qui change entre npm, yarn et pnpm, et ce qui ne change pas dans le rôle du manifeste ?"]}},"gestionnaire-paquets":{id:"gestionnaire-paquets",label:"npm / pnpm",icon:"📦",kind:"infra",osLabel:"JavaScript uniquement",niveau:"Fondation",sections:{why:"<p>JavaScript a plus de 2 millions de packages sur npm. Sans gestionnaire de paquets, intégrer une librairie implique de télécharger manuellement le code, de gérer ses propres dépendances, de maintenir les mises à jour. npm, yarn et pnpm automatisent tout ça : installation, résolution des conflits de dépendances, versioning, mise à jour.</p>",system:"<p>Le gestionnaire de paquets lit package.json, télécharge les dépendances dans node_modules/, génère le lock file (package-lock.json pour npm, pnpm-lock.yaml pour pnpm). node_modules/ ne se commite jamais — c'est le lock file qui garantit la reproductibilité. En CI/CD, on utilise <code>npm ci</code> ou <code>pnpm install --frozen-lockfile</code>.</p>",choice:{kind:"structured",main:"<p>npm (inclus avec Node, universal, légèrement lent, syntaxe de référence), pnpm (plus rapide, plus strict sur les dépendances fantômes, store partagé), yarn (bon pour les workspaces, PnP mode avancé). Pour débuter : npm. Pour des projets avec de nombreuses dépendances ou un monorepo : pnpm est clairement supérieur. La règle absolue : un seul gestionnaire par projet, ne pas mélanger.</p>",alternatives:[{name:"npm",description:"Défaut pour débuter, partout disponible."},{name:"pnpm",description:"Plus rapide, strict et efficace en stockage."},{name:"yarn",description:"Pertinent pour certains workspaces et projets existants."}]},senior:"<p>Il utilise <code>npm ci</code> en CI/CD plutôt que <code>npm install</code>. Il fait régulièrement <code>npm audit</code> pour détecter les vulnérabilités dans les dépendances et <code>npm outdated</code> pour voir les mises à jour disponibles.</p>",errors:"<p><strong>Pattern 1 — Le lock file gitignored :</strong> installs différents selon la machine et la date.</p><p><strong>Pattern 2 — npm install en CI :</strong> le CI peut upgrader silencieusement des packages.</p><p><strong>Pattern 3 — Mélanger les gestionnaires :</strong> deux lock files, comportements imprévisibles.</p>",invariants:"<p>Un gestionnaire de paquets résout deux problèmes distincts : accéder aux librairies et garantir la reproductibilité. <strong>Ce qui change : npm, pnpm, yarn, leurs performances et leurs conventions. Ce qui ne change pas : la logique registry + lock file + installation reproductible.</strong></p>",practice:{commands:[{type:"cmd",value:"npm install"},{type:"cmd",value:"npm install express"},{type:"cmd",value:"npm install --save-dev eslint"},{type:"cmd",value:"npm ci"},{type:"cmd",value:"npm audit"},{type:"cmd",value:"npm outdated"},{type:"cmd",value:"npm run dev"},{type:"cmd",value:"npm install -g pnpm"},{type:"cmd",value:"pnpm install --frozen-lockfile"}],verification:"node_modules doit exister localement, le lock file doit être présent, et un seul gestionnaire doit avoir généré un seul lock file.",debt:"node_modules/ dans .gitignore obligatoire. npm audit fix régulier. Ne jamais pousser node_modules."},verification:["Pourquoi npm ci est-il plus fiable que npm install dans une CI ?","Tu lances yarn dans un projet npm et tu obtiens deux lock files : quel signal architectural cela envoie ?","Ce qui change entre npm et pnpm, et ce qui ne change pas dans le besoin de reproductibilité ?"]}},"eslint-prettier":{id:"eslint-prettier",label:"ESLint + Prettier",icon:"✨",kind:"tool",osLabel:"JavaScript uniquement",niveau:"Intermédiaire",sections:{why:"<p>Sans linter, les erreurs mécaniques (variables non utilisées, comparaisons avec == au lieu de ===, imports manquants) sont découvertes à l'exécution ou pas du tout. Sans formatteur automatique, chaque dev a son style → les diffs de PR sont polluées. ESLint détecte les erreurs de logique et enforce les bonnes pratiques. Prettier uniformise le style sans débat.</p>",system:"<p>ESLint et Prettier s'intègrent dans VS Code, dans les scripts npm (<code>lint</code>, <code>format</code>), et dans les git hooks via husky. ESLint lit <code>eslint.config.js</code>. Prettier lit <code>.prettierrc</code>. Ils sont complémentaires : ESLint analyse la sémantique, Prettier gère le style — les deux doivent coexister sans se contredire via <code>eslint-config-prettier</code>.</p>",choice:{kind:"structured",main:"<p>ESLint + Prettier est la combinaison standard. Alternative émergente : Biome. oxlint existe aussi côté linter Rust ultra-rapide. Pour débuter : ESLint + Prettier — documentation abondante, écosystème complet. Le point essentiel : une seule source de vérité pour le style.</p>",alternatives:[{name:"ESLint + Prettier",description:"Standard, riche, très documenté."},{name:"Biome",description:"Un seul outil Rust, très rapide, moins de plugins."},{name:"oxlint",description:"Linter ultra-rapide, à évaluer selon le projet."}]},senior:`<p>Il configure Prettier en premier et installe <code>eslint-config-prettier</code> pour désactiver les règles ESLint qui conflictent avec Prettier. Il active "Format on Save" dans VS Code. Il démarre avec un ensemble de règles ESLint minimal et l'enrichit progressivement — pas 200 règles dès le début.</p>`,errors:"<p><strong>Pattern 1 — Les conflits ESLint/Prettier :</strong> sans eslint-config-prettier, les deux outils se battent.</p><p><strong>Pattern 2 — Le linter sans CI :</strong> ESLint configuré localement mais absent de la CI.</p><p><strong>Pattern 3 — La config trop stricte dès le début :</strong> 500 erreurs au premier fichier, découragement, règles désactivées.</p>",invariants:"<p>La qualité du code ne repose pas sur la discipline individuelle — elle repose sur des outils automatisés et coercitifs. <strong>Ce qui change : l'outil, ESLint, Prettier, Biome ou oxlint. Ce qui ne change pas : format on save, lint en CI, et zéro débat manuel de style en revue.</strong></p>",practice:{commands:[{type:"cmd",value:"npm install --save-dev eslint prettier eslint-config-prettier @eslint/js"},{type:"comment",value:".prettierrc"},{type:"snippet",value:'{ "semi": true, "singleQuote": true, "tabWidth": 2, "trailingComma": "es5", "printWidth": 100 }'},{type:"comment",value:"Scripts package.json"},{type:"snippet",value:'"lint": "eslint src/"'},{type:"snippet",value:'"format": "prettier --write src/"'},{type:"cmd",value:"npm run lint"},{type:"cmd",value:"npm run format"}],verification:"npm run lint doit passer sur un fichier propre, et npm run format doit produire un formatage stable sans conflit ESLint/Prettier.",debt:"ESLint sans CI = règles optionnelles. Ajouter npm run lint dans le pipeline CI dès le début du projet."},verification:["Pourquoi Prettier et ESLint doivent-ils avoir des responsabilités séparées ?","Tu configures ESLint localement mais pas en CI : que se passe-t-il sous pression d'équipe ?","Ce qui change entre ESLint + Prettier et Biome, et ce qui ne change pas dans l'automatisation de la qualité ?"]}},venv:{id:"venv",label:"venv",icon:"🫧",kind:"infra",osLabel:"Python uniquement",niveau:"Fondation",sections:{why:"<p>Python installe les packages globalement par défaut. Projet A a besoin de Django 3.2, projet B a besoin de Django 4.2. Sans isolation, ils entrent en conflit. Le venv crée un Python isolé par projet avec ses propres packages, totalement indépendant du reste du système et des autres projets.</p>",system:"<p>Le venv est la fondation de tout projet Python. Il doit être créé avant d'installer la première dépendance. Une fois activé, pip installe dans le venv uniquement, pas globalement. Le dossier <code>.venv/</code> est dans .gitignore — il est régénéré via <code>pip install -r requirements.txt</code>. VS Code détecte automatiquement le venv nommé <code>.venv</code>.</p>",choice:{kind:"structured",main:"<p>venv (inclus dans Python 3, zéro installation, suffisant pour 95% des cas), conda (data science), uv (nouveau gestionnaire en Rust, ultra-rapide, remplace pip + venv + pyenv). Pour débuter : venv. Pour data science : conda. Pour un setup moderne et rapide : uv.</p>",alternatives:[{name:"venv",description:"Défaut simple et intégré."},{name:"conda",description:"Fort en data science et packages non-Python."},{name:"uv",description:"Très rapide, futur probable du tooling Python."}]},senior:"<p>Il nomme toujours le venv <code>.venv</code>. Il l'active dès qu'il ouvre le terminal du projet. Il vérifie que VS Code utilise l'interpréteur du venv et pas le Python système — sans ça, les imports dans l'éditeur signalent des erreurs qui n'existent pas dans le terminal.</p>",errors:"<p><strong>Pattern 1 — L'install globale :</strong> <code>pip install django</code> sans venv activé.</p><p><strong>Pattern 2 — Le venv commité :</strong> oublier <code>.venv/</code> dans .gitignore.</p><p><strong>Pattern 3 — Le venv non activé :</strong> pip installe globalement ou trouve les mauvaises versions.</p>",invariants:"<p>L'isolation des dépendances par projet est un besoin universel. <strong>Ce qui change : le mécanisme d'isolation, node_modules, venv, conda, uv ou bundler. Ce qui ne change pas : chaque projet doit gérer ses propres versions de dépendances indépendamment des autres projets.</strong></p>",practice:{commands:[{type:"cmd",value:"python3 -m venv .venv"},{type:"cmd",value:"source .venv/bin/activate"},{type:"cmd",value:".venv\\Scripts\\activate"},{type:"cmd",value:"deactivate"},{type:"cmd",value:"which python"},{type:"cmd",value:"pip install -r requirements.txt"},{type:"comment",value:"VS Code : Python: Select Interpreter → .venv/bin/python"}],verification:"which python doit pointer vers .venv après activation, et .venv doit être ignoré par Git.",debt:".venv/ dans .gitignore obligatoire. VS Code avec le mauvais interpréteur → faux positifs d'erreurs."},verification:["Pourquoi installer des packages Python globalement casse-t-il la séparation entre projets ?","Tu ouvres VS Code sur le mauvais interpréteur : quels faux symptômes peux-tu voir dans l'éditeur ?","Ce qui change entre venv, conda et uv, et ce qui ne change pas dans le besoin d'isolation ?"]}},requirements:{id:"requirements",label:"requirements.txt",icon:"📋",kind:"tool",osLabel:"Python uniquement",niveau:"Fondation",sections:{why:"<p>Le venv isole les packages, mais ne les liste pas de façon persistante. Si on supprime le venv ou si quelqu'un clone le projet, les packages sont perdus. requirements.txt remplit ce rôle : il déclare toutes les dépendances avec leurs versions, permettant de reproduire l'environnement exactement. C'est l'équivalent Python du package.json + lock file.</p>",system:"<p>requirements.txt est commité dans le dépôt. <code>pip install -r requirements.txt</code> reproduit l'environnement sur n'importe quelle machine. En production, le même fichier est utilisé dans le Dockerfile ou le système de déploiement. Son pendant moderne est pyproject.toml.</p>",choice:{kind:"structured",main:"<p>requirements.txt (simple, universel, pip natif), pip-tools, Poetry, uv. Pour débuter : requirements.txt. Pour un projet sérieux en production : Poetry ou uv pour le lock file et la gestion des dépendances directes vs transitives.</p>",alternatives:[{name:"requirements.txt",description:"Simple, universel, parfait pour démarrer."},{name:"pip-tools",description:"Sépare dépendances directes et versions compilées."},{name:"Poetry / uv",description:"Gestion moderne avec lock file."}]},senior:"<p>Il sépare les dépendances de production (requirements.txt) des dépendances de développement (requirements-dev.txt — pytest, ruff, black). Il met à jour requirements.txt après chaque <code>pip install</code>. Il pin les versions exactes en production pour la reproductibilité.</p>",errors:"<p><strong>Pattern 1 — Le requirements.txt oublié :</strong> installer des packages sans les documenter.</p><p><strong>Pattern 2 — pip freeze sans discernement :</strong> fichier de 50 packages dont 40 ne sont pas des dépendances directes.</p><p><strong>Pattern 3 — Pas de versioning :</strong> <code>django</code> au lieu de <code>django==4.2.7</code>.</p>",invariants:"<p>Déclarer les dépendances de façon versionnée et reproductible est un invariant de tout projet logiciel. <strong>Ce qui change : requirements.txt, pyproject.toml, Poetry, uv ou pip-tools. Ce qui ne change pas : quelqu'un d'autre doit pouvoir reproduire ton environnement exactement, sur n'importe quelle machine, à n'importe quelle date future.</strong></p>",practice:{commands:[{type:"cmd",value:"pip install django"},{type:"cmd",value:"pip freeze > requirements.txt"},{type:"cmd",value:"pip install -r requirements.txt"},{type:"comment",value:"requirements-dev.txt"},{type:"snippet",value:"-r requirements.txt"},{type:"snippet",value:"pytest==7.4.3"},{type:"snippet",value:"ruff==0.1.6"},{type:"snippet",value:"black==23.11.0"},{type:"cmd",value:"pip list"},{type:"cmd",value:"pip show django"}],verification:"pip install -r requirements.txt dans un venv vierge doit installer le projet sans dépendance manquante.",debt:"requirements.txt non mis à jour après chaque pip install → dépendances non documentées. Envisager pip-tools ou uv."},verification:["Pourquoi le venv seul ne suffit-il pas à rendre un projet Python reproductible ?","Tu installes un package mais tu oublies requirements.txt : que va vivre la prochaine personne qui clone le dépôt ?","Ce qui change entre requirements.txt, Poetry et uv, et ce qui ne change pas dans le besoin de déclarer les dépendances ?"]}},"linter-python":{id:"linter-python",label:"Ruff + Black",icon:"✨",kind:"tool",osLabel:"Python uniquement",niveau:"Intermédiaire",sections:{why:"<p>Python a une culture de style forte formalisée dans PEP 8. Sans linter, le code d'une équipe diverge rapidement. Sans formatteur automatique, les diffs de PR sont polluées de changements de style. Ruff détecte les erreurs et violations de bonnes pratiques avec une vitesse extrême (Rust). Black formate le code automatiquement et sans configuration.</p>",system:"<p>Ruff et Black s'intègrent dans VS Code via l'extension officielle Ruff, dans les scripts du projet, et dans les git hooks via pre-commit. Leur configuration vit dans <code>pyproject.toml</code>. Black gère le formatage, Ruff gère tout ce que Black ne touche pas (imports, variables non utilisées, violations PEP 8 logiques).</p>",choice:{kind:"structured",main:"<p>Black (formatteur, zéro configuration volontaire), Ruff (linter ultra-rapide en Rust, remplace flake8 + isort + plusieurs plugins). Alternative moderne : Ruff seul peut maintenant aussi formatter (<code>ruff format</code>). L'ancienne approche flake8 + autopep8 + isort est à éviter pour un nouveau projet.</p>",alternatives:[{name:"Ruff + Black",description:"Combinaison moderne et très robuste."},{name:"Ruff seul",description:"Simplifie encore le tooling avec ruff format."},{name:"flake8 + autopep8 + isort",description:"Ancienne approche, plus fragmentée."}]},senior:`<p>Il centralise la configuration dans <code>pyproject.toml</code>. Il active "Format on Save" avec Black dans VS Code. Il ajoute <code>ruff check</code> et <code>black --check</code> dans la CI pour bloquer les PRs non conformes. Il s'assure que la longueur de ligne est cohérente partout (88 caractères — défaut Black).</p>`,errors:"<p><strong>Pattern 1 — Le linter sans CI :</strong> Ruff configuré localement mais absent de la CI.</p><p><strong>Pattern 2 — Black et isort en conflit :</strong> utiliser Ruff pour les imports plutôt qu'isort séparé.</p><p><strong>Pattern 3 — Configuration dispersée :</strong> config dans setup.cfg ET pyproject.toml ET .flake8.</p>",invariants:"<p>Automatiser la qualité du code est toujours plus efficace que la faire respecter manuellement en revue de code. <strong>Ce qui change : Ruff, Black, ruff format, flake8 ou autopep8. Ce qui ne change pas : un formatteur sur save + un linter en CI évitent les débats de style et les erreurs mécaniques.</strong></p>",practice:{commands:[{type:"cmd",value:"pip install ruff black"},{type:"comment",value:"pyproject.toml"},{type:"snippet",value:"[tool.ruff]"},{type:"snippet",value:"line-length = 88"},{type:"snippet",value:"[tool.black]"},{type:"snippet",value:'target-version = ["py311"]'},{type:"cmd",value:"ruff check src/"},{type:"cmd",value:"ruff check src/ --fix"},{type:"cmd",value:"black src/"},{type:"cmd",value:"black src/ --check"}],verification:"ruff check . et black --check . doivent passer sur un code propre, avec une configuration centralisée dans pyproject.toml.",debt:"Pas de CI → qualité dégradée progressivement. Ajouter ruff check et black --check dans le pipeline CI dès le début."},verification:["Pourquoi Ruff et Black doivent-ils être automatisés plutôt que laissés à la discipline individuelle ?","Tu as une config dans setup.cfg, pyproject.toml et .flake8 : quel type de bug de tooling peux-tu créer ?","Ce qui change entre Ruff + Black et Ruff seul, et ce qui ne change pas dans le rôle du linter/formatteur ?"]}}},maps:{js:{viewBox:"0 0 920 280",nodes:[{id:"git-init",x:20,y:80,w:110,h:65},{id:"gitignore",x:170,y:80,w:110,h:65},{id:"structure",x:320,y:80,w:110,h:65},{id:"readme",x:320,y:185,w:110,h:65},{id:"env-vars",x:470,y:185,w:110,h:65},{id:"package-json",x:470,y:80,w:120,h:65},{id:"gestionnaire-paquets",x:635,y:80,w:120,h:65},{id:"eslint-prettier",x:635,y:185,w:130,h:65},{id:"commits",x:790,y:130,w:110,h:65}],edges:[{x1:130,y1:112,x2:168,y2:112,label:"protège"},{x1:280,y1:112,x2:318,y2:112,label:"cadre"},{x1:375,y1:145,x2:375,y2:183,label:"documente"},{x1:430,y1:112,x2:468,y2:112,label:"manifeste"},{x1:430,y1:217,x2:468,y2:217,label:"configure"},{x1:590,y1:112,x2:633,y2:112,label:"installe"},{x1:695,y1:145,x2:700,y2:183,label:"qualité"},{x1:755,y1:112,x2:788,y2:150,label:"stabilise"},{x1:765,y1:217,x2:788,y2:175,label:"bloque"}]},python:{viewBox:"0 0 920 280",nodes:[{id:"git-init",x:20,y:80,w:110,h:65},{id:"gitignore",x:170,y:80,w:110,h:65},{id:"structure",x:320,y:80,w:110,h:65},{id:"readme",x:320,y:185,w:110,h:65},{id:"env-vars",x:470,y:185,w:110,h:65},{id:"venv",x:470,y:80,w:100,h:65},{id:"requirements",x:615,y:80,w:140,h:65},{id:"linter-python",x:615,y:185,w:140,h:65},{id:"commits",x:800,y:130,w:110,h:65}],edges:[{x1:130,y1:112,x2:168,y2:112,label:"protège"},{x1:280,y1:112,x2:318,y2:112,label:"cadre"},{x1:375,y1:145,x2:375,y2:183,label:"documente"},{x1:430,y1:112,x2:468,y2:112,label:"isole"},{x1:430,y1:217,x2:468,y2:217,label:"configure"},{x1:570,y1:112,x2:613,y2:112,label:"déclare"},{x1:685,y1:145,x2:685,y2:183,label:"qualité"},{x1:755,y1:112,x2:798,y2:150,label:"stabilise"},{x1:755,y1:217,x2:798,y2:175,label:"bloque"}]}}},n={id:"architecture-application",part:"T",number:3,title:"Architecture d'une Application",subtitle:"Séparer les responsabilités à l'intérieur d'un système",badge:"Fiche T03 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte des couches architecturales d'une application : point d'entrée, modules, routes, middlewares, services, repositories et composants.",accent:"tool",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{entree:{id:"entree",label:"Point d'entrée",icon:"▶",kind:"infra",osLabel:"Universel",sections:{why:"<p>Tout programme commence quelque part. Le point d'entrée est le fichier que le runtime exécute en premier — il initialise l'application, connecte les pièces ensemble, et démarre les processus. Sans point d'entrée clair, le programme n'est pas un système cohérent — c'est une collection de fichiers sans ordre de démarrage.</p><p>Mais le point d'entrée révèle aussi l'architecture entière par ce qu'il initialise et dans quel ordre : la base de données, les middlewares, les routes, la configuration. Lire le point d'entrée d'un projet inconnu est la première chose à faire pour le comprendre — il dit tout sur la structure.</p>",system:"<p>Le point d'entrée est la racine de l'arbre d'initialisation. Il importe et initialise les modules, configure le serveur, branche les routes et les middlewares, établit la connexion à la base de données, et démarre le processus d'écoute. Tout le reste du système est connecté à travers lui — pas en logique (la logique est dans les services), mais en câblage (qui est branché sur quoi).</p>",choice:{kind:"structured",main:"<p>La vraie décision est de séparer la configuration du serveur du démarrage du serveur. Convention JS : <code>app.js</code> configure Express et exporte l'app — <code>index.js</code> importe l'app et appelle listen. Pourquoi ? Les tests d'intégration importent <code>app</code> sans démarrer un vrai serveur réseau.</p><p>Conventions Python : <code>main.py</code> pour FastAPI, <code>manage.py</code> + <code>wsgi.py</code>/<code>asgi.py</code> pour Django, <code>app.py</code> avec Application Factory pour Flask.</p>",alternatives:[{name:"app.js + index.js",description:"Séparation JS recommandée : configuration testable, démarrage isolé."},{name:"main.py",description:"Convention FastAPI : instance app exportée et configurable."},{name:"Application Factory",description:"Pattern Flask pour créer une app testable et paramétrable."}]},senior:`<p>Il garde le point d'entrée court et déclaratif. C'est du câblage — pas de logique métier. Une règle simple : si une fonction dans le point d'entrée fait plus que "créer", "configurer", ou "connecter", elle est au mauvais endroit. La logique appartient aux services, pas au fichier qui démarre l'application.</p>`,errors:"<p><strong>Pattern 1 — La logique dans l'entrée :</strong> requêtes SQL directes, calculs métier, traitement de données dans index.js → code non testable, spaghetti architectural dès le départ.</p><p><strong>Pattern 2 — Le point d'entrée monolithique :</strong> app.js et index.js non séparés → impossible d'importer la configuration sans démarrer le serveur.</p><p><strong>Pattern 3 — La configuration hardcodée :</strong> ports, URLs, credentials écrits en dur dans le point d'entrée → configuration non portable, secrets exposés.</p>",invariants:"<p>Tout système exécutable a un point d'entrée unique et clair. Ce qui change : le fichier, la convention de nommage, le framework. Ce qui ne change pas : le point d'entrée initialise sans calculer, câble sans logique, démarre sans décider. La logique appartient ailleurs — toujours.</p>",practice:{commands:[{type:"comment",value:"JS — séparation app.js / index.js"},{type:"cmd",value:"src/app.js     # configuration exportée pour les tests"},{type:"cmd",value:"src/index.js   # démarrage uniquement"},{type:"cmd",value:"app.listen(process.env.PORT || 3000)"},{type:"comment",value:"Python FastAPI"},{type:"cmd",value:"src/main.py"},{type:"cmd",value:'app = FastAPI(title="Mon API", version="1.0.0")'},{type:"cmd",value:'app.include_router(users.router, prefix="/api/v1/users")'}],debt:"Logique dans le point d'entrée → code non testable. app.js et index.js non séparés → tests impossibles sans démarrer un vrai serveur."}}},modules:{id:"modules",label:"Modules",icon:"📦",kind:"infra",osLabel:"Universel",sections:{why:"<p>Sans système de modules, tout le code vit dans un seul fichier ou dans des fichiers qui partagent un espace de noms global. Les variables se marchent dessus, les fonctions ont des noms de plus en plus longs pour éviter les conflits, et comprendre ce que fait une partie du code exige de lire tout le reste. Les modules résolvent ça : chaque fichier est un espace de noms isolé qui exporte explicitement ce qu'il veut partager et importe explicitement ce dont il a besoin.</p>",system:"<p>Les modules sont la brique fondamentale de toute architecture. Tout — routes, services, repositories, composants — est un module. Le système de modules détermine comment les pièces se trouvent et se connectent. La qualité des imports d'un projet reflète directement la qualité de son architecture : imports circulaires, imports profonds, barrel files, path aliases.</p>",choice:{kind:"structured",main:`<p>JS : ESModules (<code>import</code>/<code>export</code>) est le standard moderne. CommonJS (<code>require</code>) est l'ancien système. Pour forcer ESModules : <code>"type": "module"</code> dans package.json.</p><p>Python : le système de modules est natif. La vraie décision est sur les imports absolus vs relatifs. Recommandation : imports absolus, plus lisibles et moins fragiles.</p>`,alternatives:[{name:"ESModules",description:"Standard moderne JavaScript pour les nouveaux projets."},{name:"CommonJS",description:"Ancien système Node, encore présent dans des projets existants."},{name:"Imports absolus Python",description:"Plus lisibles et robustes que les imports relatifs profonds."}]},senior:"<p>Il design ses modules pour qu'ils aient une responsabilité unique et une interface claire. Un module qui exporte 20 fonctions sans cohérence est un signe que le découpage est mauvais. Il surveille les imports circulaires — ils signalent un couplage trop fort qui nécessite une refactorisation ou un troisième module intermédiaire. Il configure des path aliases pour éviter les imports relatifs profonds.</p>",errors:"<p><strong>Pattern 1 — Les imports circulaires :</strong> module A importe B qui importe A → erreurs cryptiques, valeurs <code>undefined</code>.</p><p><strong>Pattern 2 — Le module fourre-tout :</strong> <code>utils.js</code> ou <code>helpers.py</code> de 500 lignes avec des fonctions sans rapport.</p><p><strong>Pattern 3 — Les imports relatifs profonds :</strong> <code>../../../../utils/helpers</code> → fragile et illisible.</p>",invariants:"<p>La modularité est la technique fondamentale pour gérer la complexité croissante d'un système. Diviser le code en unités indépendantes avec des interfaces explicites rend le système compréhensible, testable, et évolutif. Chaque module fait une chose, exporte explicitement, importe explicitement — les dépendances sont déclarées, pas supposées.</p>",practice:{commands:[{type:"comment",value:"JS — ESModules"},{type:"cmd",value:"export const calculateTotal = (items) => { ... }"},{type:"cmd",value:"import { calculateTotal } from '#utils/cart.js'"},{type:"comment",value:"package.json imports"},{type:"cmd",value:'"#services/*": "./src/services/*.js"'},{type:"comment",value:"Python — imports absolus"},{type:"cmd",value:"from src.services.user_service import UserService"},{type:"comment",value:"Vérification cycles"},{type:"cmd",value:"madge src/ --circular"},{type:"cmd",value:"pydeps src/"}],debt:"Path aliases non configurés → imports relatifs profonds ingérables. Barrel files mal gérés → chargement inutile de modules entiers."}}},routes:{id:"routes",label:"Routes",icon:"⇒",kind:"tool",osLabel:"Universel",sections:{why:"<p>Sans routing, il n'y a pas de façon structurée de mapper une action externe (requête HTTP, navigation frontend) vers le code qui la traite. Les routes définissent le contrat d'entrée de l'application — ce qui est accessible, comment, et sous quelle forme. Elles sont aussi la première ligne de contact : elles reçoivent des données du monde extérieur, hostile et imprévisible, et les traduisent en appels propres vers la logique interne.</p>",system:"<p>Les routes sont la couche entre l'extérieur et la logique interne. Elles reçoivent la requête, valident les données d'entrée, appellent le service approprié, et retournent la réponse. Elles ne contiennent pas de logique métier — elles délèguent. En backend, elles s'organisent par ressource. En frontend React, React Router gère la navigation entre composants.</p>",choice:{kind:"structured",main:"<p>La vraie décision n'est pas l'outil de routing, c'est la discipline de délégation. Deux patterns pour la validation : validation dans le middleware de route (Zod en JS, Pydantic en Python) ou validation dans le handler. Recommandation : middleware ou décorateur pour que le handler ne reçoive que des données déjà valides et typées.</p>",alternatives:[{name:"Validation middleware",description:"Zod ou équivalent avant le handler."},{name:"Validation framework",description:"Pydantic/FastAPI valide automatiquement."},{name:"Route par ressource",description:"Fichiers dédiés : user.routes.js, products.py, etc."}]},senior:"<p>Il garde les handlers de routes courts — 10 à 15 lignes maximum. La route valide les inputs, appelle le service, retourne la réponse. Tout ce qui dépasse est de la logique qui appartient au service. Il structure les réponses de façon cohérente : même format pour les succès, même format pour les erreurs, partout dans l'API.</p>",errors:"<p><strong>Pattern 1 — La route obèse :</strong> 100 lignes de logique dans un handler, requêtes SQL directes, calculs métier.</p><p><strong>Pattern 2 — La validation absente :</strong> passer n'importe quel input au service → erreurs cryptiques en profondeur.</p><p><strong>Pattern 3 — Les routes incohérentes :</strong> <code>GET /getUser</code>, <code>POST /deleteProduct</code> → API impossible à prédire.</p>",invariants:"<p>La couche de routing est uniquement responsable de la traduction entre le protocole de transport (HTTP) et la logique applicative. Elle ne décide pas, elle délègue. La route reçoit, valide, délègue, répond — dans cet ordre, rien de plus.</p>",practice:{commands:[{type:"comment",value:"Express — handler propre"},{type:"cmd",value:"const data = CreateUserSchema.parse(req.body)"},{type:"cmd",value:"const user = await userService.createUser(data)"},{type:"cmd",value:"res.status(201).json({ data: user })"},{type:"comment",value:"FastAPI — Pydantic valide automatiquement"},{type:"cmd",value:'@router.post("/", status_code=201)'},{type:"cmd",value:"async def create_user(data: CreateUserRequest):"},{type:"cmd",value:'return {"data": user}'}],debt:"Logique métier dans les routes → code non testable unitairement. Validation absente → données corrompues et comportements imprévisibles."}}},middleware:{id:"middleware",label:"Middlewares",icon:"⊟",kind:"infra",osLabel:"Universel",sections:{why:"<p>Certaines opérations doivent s'exécuter sur toutes les requêtes indépendamment de la route ciblée : authentification, logging, gestion d'erreurs, CORS, rate limiting, parsing du body. Sans middlewares, cette logique serait dupliquée dans chaque handler. Les middlewares centralisent ces préoccupations transversales en couches réutilisables.</p>",system:"<p>Les middlewares s'intercalent entre la requête entrante et le handler de route. Ils s'exécutent dans l'ordre dans lequel ils sont déclarés — l'ordre est critique. Auth avant routes protégées. Logging avant tout. Error middleware en dernier.</p>",choice:{kind:"structured",main:"<p>Deux catégories : globaux (logging, CORS, body parser, error handler) et spécifiques (auth, rôles admin). Librairies JS courantes : helmet, cors, morgan, express-rate-limit. Python FastAPI : middlewares ASGI pour le global, <code>Depends</code> pour l'injection ciblée.</p>",alternatives:[{name:"Global",description:"S'applique à toutes les routes : sécurité, logs, CORS."},{name:"Ciblé",description:"Auth, rôle, validation sur certaines routes."},{name:"Depends FastAPI",description:"Alternative ciblée très flexible côté Python."}]},senior:"<p>Il ordonne ses middlewares intentionnellement et documente cet ordre dans app.js. Un middleware mal placé peut silencieusement rendre un autre inefficace. Il teste ses middlewares indépendamment des routes.</p>",errors:"<p><strong>Pattern 1 — L'ordre incorrect :</strong> middleware d'erreur avant les routes ou auth après les routes.</p><p><strong>Pattern 2 — Le middleware fourre-tout :</strong> logique spécifique à une ressource dans un middleware global.</p><p><strong>Pattern 3 — Le next() oublié :</strong> requête suspendue indéfiniment.</p>",invariants:"<p>Les préoccupations transversales s'extraient en couches séparées. Middlewares Express, filtres Django, dépendances FastAPI, intercepteurs NestJS : la syntaxe change, le principe reste.</p>",practice:{commands:[{type:"comment",value:"Ordre Express critique"},{type:"cmd",value:"app.use(helmet())"},{type:"cmd",value:"app.use(cors({ origin: process.env.CORS_ORIGIN }))"},{type:"cmd",value:"app.use(express.json())"},{type:"cmd",value:"app.use('/api/v1/auth', authRoutes)"},{type:"cmd",value:"app.use(authMiddleware)"},{type:"cmd",value:"app.use('/api/v1/users', userRoutes)"},{type:"cmd",value:"app.use(errorMiddleware)"},{type:"comment",value:"FastAPI : Depends pour les routes protégées"}],debt:"Ordre des middlewares non documenté → auth cassée silencieusement. Middleware d'erreur absent → exceptions non gérées."}}},services:{id:"services",label:"Services",icon:"⚙",kind:"tool",osLabel:"Universel",sections:{why:"<p>C'est la couche la plus importante de l'architecture — et la plus souvent absente dans le code des débutants. La logique métier est ce que l'application fait vraiment : créer un utilisateur, calculer le prix d'une commande, valider un paiement. Si cette logique vit dans les routes, elle est couplée au protocole HTTP — impossible à tester sans vraies requêtes, impossible à réutiliser.</p>",system:"<p>Les services reçoivent des appels des routes (données déjà validées) et appellent les repositories (accès aux données). Ils ne savent rien d'Express ou de FastAPI — pas de <code>req</code>, pas de <code>res</code>, pas d'objet HTTP. Ils prennent des inputs typés, appliquent les règles métier, retournent un résultat ou lèvent une exception métier.</p>",choice:{kind:"structured",main:"<p>La structure des services suit la découpe du domaine métier, pas la structure de la base de données. Deux styles : services procéduraux (fonctions exportées) ou services orientés objet (classes facilitant l'injection de dépendances). Les deux fonctionnent. La cohérence est plus importante que le choix.</p>",alternatives:[{name:"Fonctions",description:"Simple, direct, sans état."},{name:"Classes",description:"Injection de dépendances plus facile pour les tests."},{name:"Use cases",description:"Découpe plus stricte pour domaines complexes."}]},senior:"<p>Il teste ses services sans base de données ni serveur HTTP — en mockant les repositories. Si un service est difficile à tester unitairement, c'est le signe qu'il dépend de trop de choses extérieures. Il garde aussi les services focalisés : un service qui fait 10 choses différentes est probablement plusieurs services mélangés.</p>",errors:"<p><strong>Pattern 1 — La logique dans les routes :</strong> SQL direct, calculs, emails dans les handlers.</p><p><strong>Pattern 2 — Le service qui connaît HTTP :</strong> retourne des codes HTTP au lieu de lever des exceptions métier.</p><p><strong>Pattern 3 — Le service qui accède directement à l'ORM :</strong> couplage à Prisma/SQLAlchemy et tests lents.</p>",invariants:"<p>La logique métier doit être indépendante du mécanisme de transport et du mécanisme de persistance. Ce principe est présent dans toutes les architectures sérieuses : Domain Layer, Business Logic Layer, Use Cases. Le nom change, le principe reste : la logique métier ne dépend de rien d'externe.</p>",practice:{commands:[{type:"comment",value:"Service JS propre — aucun import de framework"},{type:"cmd",value:"class UserService {"},{type:"cmd",value:"async createUser({ name, email, password }) {"},{type:"cmd",value:"const existing = await this.userRepository.findByEmail(email)"},{type:"cmd",value:"if (existing) throw new Error('EMAIL_ALREADY_EXISTS')"},{type:"comment",value:"Service Python propre"},{type:"cmd",value:"class UserService:"},{type:"cmd",value:"async def create_user(self, name: str, email: str, password: str):"}],debt:"Services couplés à la BDD → tests lents, fragiles et rares. La lenteur des tests est le premier symptôme d'un mauvais découpage."}}},repositories:{id:"repositories",label:"Repositories",icon:"🗄",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Les services contiennent la logique métier — mais pour faire leur travail, ils ont besoin de données. Si les services appellent directement l'ORM, ils deviennent difficiles à tester et changer d'ORM ou de base oblige à modifier la logique métier. Le repository pattern isole l'accès aux données derrière une interface stable.</p>",system:"<p>Les repositories sont la couche la plus proche de la base de données. Ils sont appelés par les services, jamais directement par les routes. Ils traduisent les appels de données en requêtes SQL ou ORM et retournent des objets du domaine. Cette traduction isole les services des détails de persistance.</p>",choice:{kind:"structured",main:"<p>Simple : wrappers légers autour de l'ORM. Suffisant pour isoler les services et faciliter le mocking. Complet : repositories qui implémentent une interface, permettant de changer d'implémentation sans toucher aux services. Pour débuter : approche simple.</p>",alternatives:[{name:"Wrapper ORM",description:"Simple, pragmatique, suffisant pour beaucoup de projets."},{name:"Interface / abstraction",description:"Plus robuste pour projets longs ou complexes."},{name:"SQL brut ciblé",description:"Possible pour requêtes complexes, caché dans le repository."}]},senior:"<p>Il surveille les N+1 queries — une requête retourne N éléments, puis pour chaque élément une autre requête est faite. Il charge les relations nécessaires en une seule requête (eager loading) plutôt que de les charger à la demande. Il active le logging SQL en développement pour voir exactement ce que l'ORM génère.</p>",errors:"<p><strong>Pattern 1 — L'ORM dans le service :</strong> service couplé à Prisma/SQLAlchemy.</p><p><strong>Pattern 2 — Le N+1 silencieux :</strong> invisible en dev avec 3 utilisateurs, catastrophique en prod.</p><p><strong>Pattern 3 — La logique métier dans le repository :</strong> décisions dispersées entre service et data layer.</p>",invariants:"<p>L'accès aux données est un détail d'implémentation de la logique métier. La logique métier ne doit pas savoir si les données viennent de PostgreSQL, MongoDB, ou d'une API externe. Repository Pattern, Data Access Layer, DAO : le nom change, le principe reste.</p>",practice:{commands:[{type:"comment",value:"Repository JS avec Prisma"},{type:"cmd",value:"findById(id) { return prisma.user.findUnique({ where: { id } }) }"},{type:"cmd",value:"findByEmail(email) { return prisma.user.findUnique({ where: { email } }) }"},{type:"cmd",value:"create(data) { return prisma.user.create({ data }) }"},{type:"comment",value:"Repository Python avec SQLAlchemy"},{type:"cmd",value:"def find_by_email(self, email: str):"},{type:"cmd",value:"return self.db.query(User).filter(User.email == email).first()"},{type:"comment",value:"Logging SQL en dev"},{type:"cmd",value:'DEBUG="prisma:query"'}],debt:"N+1 queries non détectées en développement → dégradation progressive en production. Logger les requêtes SQL en dev dès le premier jour."}}},composants:{id:"composants",label:"Composants",icon:"◫",kind:"tool",osLabel:"JavaScript uniquement",sections:{why:"<p>Une application frontend sans découpe en composants ressemble à une application backend sans routes ni services — tout dans un seul fichier, logique et affichage mélangés, rien de réutilisable. Les composants sont la réponse du frontend au même problème que les modules résolvent côté backend : découper le code en unités indépendantes, réutilisables, et compréhensibles.</p>",system:"<p>Les composants forment un arbre. Un composant racine (<code>App</code>) contient des pages, qui contiennent des composants de layout, qui contiennent des composants de feature, qui contiennent des composants UI génériques. Les données descendent via les props, les événements remontent via les callbacks.</p>",choice:{kind:"structured",main:"<p>Qu'est-ce qui mérite d'être un composant ? Si un bloc d'UI est réutilisé à deux endroits, s'il a une logique interne significative, ou s'il est assez complexe pour être testé isolément. Découpe : UI générique, feature, page.</p>",alternatives:[{name:"UI générique",description:"Button, Input, Modal : sans logique métier."},{name:"Feature",description:"UserCard, ProductList : logique spécifique."},{name:"Page",description:"UsersPage, CheckoutPage : assemblage lié aux routes."}]},senior:"<p>Il sépare les composants intelligents (fetch, état complexe) des composants bêtes (props uniquement). Il extrait la logique dans des hooks personnalisés. Il surveille le prop drilling : une prop qui traverse 3 niveaux sans être utilisée signale un besoin de Context ou de state manager.</p>",errors:"<p><strong>Pattern 1 — Le composant monolithique :</strong> 500 lignes de fetching, transformation, affichage et interactions.</p><p><strong>Pattern 2 — Le prop drilling :</strong> prop passée à travers 4 niveaux inutiles.</p><p><strong>Pattern 3 — Le fetch dans le JSX :</strong> logique de fetching répétée et non réutilisable.</p>",invariants:"<p>Un composant fait une chose et la fait bien. Il a une interface claire (ses props) et ne dépend pas de l'état global autant que possible. Ce principe vaut en React, Vue, Svelte ou tout autre framework à composants.</p>",practice:{commands:[{type:"comment",value:"Structure React"},{type:"cmd",value:"src/components/ui/Button.jsx"},{type:"cmd",value:"src/components/features/users/UserCard.jsx"},{type:"cmd",value:"src/components/features/users/useUsers.js"},{type:"cmd",value:"src/pages/UsersPage.jsx"},{type:"comment",value:"Règles de vérification"},{type:"cmd",value:"chaque composant < 100 lignes"},{type:"cmd",value:"aucun fetch direct dans le JSX"},{type:"cmd",value:"aucune prop traversant plus de 2 niveaux sans être utilisée"}],debt:"Composants trop couplés à la donnée → impossible à tester et réutiliser. Prop drilling non adressé → Context ou Zustand à introduire."}}}},maps:{js:{viewBox:"0 0 960 300",nodes:[{id:"entree",x:20,y:115,w:110,h:65},{id:"modules",x:180,y:115,w:110,h:65},{id:"routes",x:345,y:50,w:110,h:65},{id:"middleware",x:345,y:180,w:120,h:65},{id:"services",x:520,y:115,w:110,h:65},{id:"repositories",x:690,y:50,w:130,h:65},{id:"composants",x:690,y:180,w:120,h:65}],edges:[{x1:130,y1:147,x2:178,y2:147},{x1:290,y1:132,x2:343,y2:82},{x1:290,y1:162,x2:343,y2:212},{x1:455,y1:82,x2:518,y2:132},{x1:465,y1:212,x2:518,y2:162},{x1:630,y1:132,x2:688,y2:82},{x1:630,y1:162,x2:688,y2:212}]},python:{viewBox:"0 0 820 260",nodes:[{id:"entree",x:20,y:95,w:110,h:65},{id:"modules",x:180,y:95,w:110,h:65},{id:"routes",x:340,y:40,w:110,h:65},{id:"middleware",x:340,y:150,w:120,h:65},{id:"services",x:520,y:95,w:110,h:65},{id:"repositories",x:680,y:95,w:130,h:65}],edges:[{x1:130,y1:127,x2:178,y2:127},{x1:290,y1:112,x2:338,y2:72},{x1:290,y1:142,x2:338,y2:182},{x1:450,y1:72,x2:518,y2:112},{x1:460,y1:182,x2:518,y2:142},{x1:630,y1:127,x2:678,y2:127}]}}},i={viewBox:"0 0 960 280",nodes:[{id:"scripts",x:20,y:100,w:110,h:65},{id:"dev-server",x:180,y:100,w:120,h:65},{id:"logs",x:350,y:40,w:100,h:65},{id:"erreurs",x:350,y:160,w:100,h:65},{id:"debug",x:500,y:100,w:110,h:65},{id:"lint-format",x:660,y:40,w:120,h:65},{id:"tests",x:660,y:160,w:110,h:65},{id:"commit-push",x:830,y:100,w:110,h:65}],edges:[{x1:130,y1:132,x2:178,y2:132},{x1:300,y1:120,x2:348,y2:82},{x1:300,y1:145,x2:348,y2:190},{x1:450,y1:72,x2:498,y2:120},{x1:450,y1:192,x2:498,y2:145},{x1:610,y1:120,x2:658,y2:82},{x1:610,y1:145,x2:658,y2:190},{x1:780,y1:72,x2:828,y2:120},{x1:770,y1:192,x2:828,y2:145}]},r={id:"cycle-developpement-local",part:"T",number:4,title:"Cycle de Développement Local",subtitle:"Comprendre le flux quotidien d'une session de développement",badge:"Fiche T04 — Vision Systémique",status:"Modèle stabilisé",meta:["8 nœuds","7 sections / nœud"],category:"Technique",level:"Débutant → Junior",readingTime:"30 min",description:"Le flux quotidien du développeur : scripts, dev server, logs, erreurs, debug, lint, tests, commit et push.",accent:"tool",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{scripts:{id:"scripts",label:"Scripts",icon:"▶",kind:"infra",osLabel:"Universel",sections:{why:`<p>Sans scripts standardisés, chaque développeur lance le projet à sa façon. L'un tape <code>node src/index.js</code>, l'autre <code>nodemon app.js</code>, le troisième a une commande custom qu'il a oubliée. À chaque onboarding, la question "comment je lance le projet ?" prend 20 minutes. Les scripts sont l'interface publique du projet — les commandes standardisées qui font abstraction de la complexité interne. Un projet bien configuré se lance toujours avec la même commande, peu importe qui s'en occupe.</p>`,system:"<p>Les scripts sont le point d'entrée de tout le cycle de développement. Ils déclenchent le dev server, les tests, le linter, le formatteur, le build. En JS ils vivent dans <code>package.json</code> sous la clé <code>scripts</code>. En Python ils sont définis dans un <code>Makefile</code> ou dans <code>pyproject.toml</code>. Ils s'intègrent aussi dans la CI/CD — les pipelines appellent les mêmes scripts que les développeurs utilisent localement. Un script local qui marche = un pipeline qui marche.</p>",choice:{kind:"structured",main:"<p>JavaScript : les scripts npm sont le standard. Alternatives — <code>Makefile</code>, <code>just</code>. Pour un projet JS standard : scripts npm suffisent. Python : pas de standard natif équivalent aux scripts npm. Options — <code>Makefile</code>, <code>invoke</code>, <code>taskfile</code>. Recommandation : Makefile pour la compatibilité universelle.</p>",alternatives:[{name:"Scripts npm",description:"Standard JavaScript, simple et intégré à package.json."},{name:"Makefile",description:"Universel, langage-agnostique, robuste pour JS/Python."},{name:"just / taskfile / invoke",description:"Alternatives modernes selon l'écosystème."}]},senior:"<p>Il définit les scripts standards dès le premier jour et les documente dans le README. Les noms sont conventionnels et prévisibles — <code>dev</code>, <code>start</code>, <code>test</code>, <code>lint</code>, <code>build</code>, <code>format</code>. Quelqu'un qui clone le projet pour la première fois doit pouvoir lancer <code>npm run dev</code> ou <code>make dev</code> sans lire la documentation interne. Il s'assure aussi que les scripts locaux et CI utilisent exactement les mêmes commandes.</p>",errors:"<p><strong>Pattern 1 — Les scripts non documentés :</strong> des scripts existent dans package.json mais ne sont jamais mentionnés dans le README.</p><p><strong>Pattern 2 — Les scripts locaux-only :</strong> commandes avec chemins absolus, variables locales hardcodées, ou outils globaux non déclarés.</p><p><strong>Pattern 3 — Les scripts fourre-tout :</strong> un seul script <code>start</code> qui fait tout — lint, test, build, lancement — dans un ordre arbitraire.</p>",invariants:"<p>L'interface d'un projet doit être standardisée et documentée. Peu importe le langage, peu importe l'outil — quelqu'un de nouveau doit pouvoir cloner et lancer en moins de 5 minutes avec des commandes prévisibles. Ce qui change : l'outil de scripting. Ce qui ne change pas : la nécessité d'une interface standardisée entre le développeur et le projet.</p>",practice:{commands:[{type:"comment",value:"Scripts npm recommandés"},{type:"cmd",value:'"dev": "nodemon src/index.js"'},{type:"cmd",value:'"start": "node src/index.js"'},{type:"cmd",value:'"test": "jest"'},{type:"cmd",value:'"lint": "eslint src/"'},{type:"cmd",value:'"format": "prettier --write src/"'},{type:"comment",value:"Makefile Python recommandé"},{type:"cmd",value:"make dev"},{type:"cmd",value:"make test"},{type:"cmd",value:"make lint"},{type:"cmd",value:"make format"}],debt:"Scripts qui divergent entre local et CI → bugs impossibles à reproduire. Toujours utiliser les mêmes scripts dans les deux contextes."}}},"dev-server":{id:"dev-server",label:"Dev Server",icon:"⚡",kind:"tool",osLabel:"Universel",sections:{why:"<p>Sans serveur de développement, le cycle de travail est : modifier le code → arrêter le processus → relancer → tester → recommencer. Sur un projet actif, c'est des dizaines de fois par heure. Le dev server élimine cette friction — il surveille les fichiers, détecte les modifications, et recharge automatiquement. Il réduit le cycle de feedback à quelques secondes.</p>",system:"<p>Le dev server est le cœur du cycle local. Il maintient le processus en vie, alimente les logs en temps réel, et est le premier endroit où les erreurs apparaissent. En frontend, il inclut souvent le HMR. En backend, il redémarre le processus serveur à chaque modification.</p>",choice:{kind:"structured",main:"<p>JavaScript backend : <code>nodemon</code>, <code>tsx --watch</code>, ou <code>node --watch</code>. JavaScript frontend : <code>Vite</code>. Python : <code>uvicorn --reload</code>, <code>flask run --debug</code>, ou <code>python manage.py runserver</code>.</p>",alternatives:[{name:"Vite",description:"Standard moderne frontend, HMR très rapide."},{name:"node --watch / nodemon",description:"Rechargement automatique backend Node."},{name:"uvicorn --reload / Flask debug",description:"Rechargement automatique Python selon le framework."}]},senior:"<p>Il configure le dev server pour qu'il corresponde exactement à l'environnement de production — mêmes variables, même port si possible, même comportement des routes. Il configure aussi le proxy des requêtes API en développement pour éviter les problèmes CORS.</p>",errors:"<p><strong>Pattern 1 — Le rechargement ignoré :</strong> modifier <code>.env</code>, package.json ou un fichier de config sans redémarrer manuellement.</p><p><strong>Pattern 2 — Le port en conflit :</strong> <code>Error: address already in use</code> → identifier le processus, ne pas changer de port au hasard.</p><p><strong>Pattern 3 — Le dev server en production :</strong> utiliser nodemon ou reload automatique en prod.</p>",invariants:`<p>La vitesse du cycle feedback est un facteur de productivité fondamental. Plus le temps entre "j'écris du code" et "je vois l'effet" est court, plus le développement est rapide et moins les bugs s'accumulent.</p>`,practice:{commands:[{type:"comment",value:"JavaScript backend"},{type:"cmd",value:"npm install --save-dev nodemon"},{type:"comment",value:"JavaScript frontend"},{type:"cmd",value:"npm create vite@latest mon-projet"},{type:"cmd",value:"npm run dev"},{type:"comment",value:"Python FastAPI"},{type:"cmd",value:"pip install uvicorn[standard]"},{type:"cmd",value:"uvicorn src.main:app --reload --port 8000"},{type:"comment",value:"Python Flask"},{type:"cmd",value:"flask run --debug --port 5000"}],debt:"Nodemon non configuré → surveille trop de fichiers, rechargements inutiles. Configurer watch et ignore explicitement."}}},logs:{id:"logs",label:"Logs",icon:"📋",kind:"infra",osLabel:"Universel",sections:{why:"<p>Le code s'exécute dans un environnement opaque — on ne peut pas voir ce qui se passe à l'intérieur d'un processus en cours d'exécution. Les logs sont la fenêtre sur ce qui se passe réellement : requêtes reçues, valeurs des variables, temps d'exécution, erreurs, comportements inattendus. Sans logs, déboguer revient à deviner.</p>",system:"<p>Les logs sont produits par le dev server et lus dans le terminal. En développement, on les lit en direct. En production, ils sont collectés par la plateforme d'hébergement ou un système dédié. La discipline de logging en développement détermine la visibilité en production.</p>",choice:{kind:"structured",main:"<p><code>console.log</code> et <code>print</code> pour déboguer ponctuellement — à retirer avant de commiter. Pour du logging structuré : <code>pino</code> ou <code>winston</code> en JS, <code>loguru</code> ou <code>logging</code> en Python.</p>",alternatives:[{name:"console.log / print",description:"Ponctuel, temporaire, utile en dev."},{name:"pino / winston",description:"Logging structuré JavaScript."},{name:"loguru / logging",description:"Logging structuré Python."}]},senior:"<p>Il distingue les niveaux : <code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code>. Il ne logue jamais de données sensibles : mots de passe, tokens, données personnelles.</p>",errors:"<p><strong>Pattern 1 — Le console.log commité :</strong> logs polluants et données sensibles potentielles en production.</p><p><strong>Pattern 2 — Pas de logs du tout :</strong> débogage à l'aveugle au premier incident.</p><p><strong>Pattern 3 — Les logs trop verbeux :</strong> signal noyé dans le bruit.</p>",invariants:"<p>Observer le comportement d'un système opaque nécessite des traces explicites. Ce qui change : l'outil, le format, la destination. Ce qui ne change pas : sans traces, pas de compréhension, pas de débogage possible.</p>",practice:{commands:[{type:"cmd",value:"npm install pino pino-pretty"},{type:"cmd",value:"pip install loguru"},{type:"comment",value:"Niveaux à retenir"},{type:"cmd",value:"debug   → développement uniquement"},{type:"cmd",value:"info    → événements normaux"},{type:"cmd",value:"warn    → anomalies non bloquantes"},{type:"cmd",value:"error   → erreurs à investiguer"}],debt:"console.log/print laissés en production → pollution des logs, données exposées. Configurer LOG_LEVEL selon l'environnement."}}},erreurs:{id:"erreurs",label:"Erreurs",icon:"✗",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Les erreurs sont inévitables — la question n'est pas d'en avoir ou non, mais de savoir les lire et les gérer. Un développeur qui panique face à une stack trace n'a pas compris que les erreurs sont de l'information — elles disent exactement ce qui a échoué, où, et souvent pourquoi.</p>",system:"<p>Les erreurs apparaissent dans les logs du dev server, dans la console du navigateur, ou dans le terminal. Elles ont deux natures : erreurs de développement et erreurs d'exécution. Les erreurs non gérées font planter le processus. Les erreurs gérées permettent une réponse gracieuse.</p>",choice:{kind:"structured",main:"<p>Les erreurs attendues se gèrent avec des structures explicites : return early, codes d'erreur, réponses HTTP appropriées. Les erreurs inattendues se catchent au niveau le plus haut avec un handler global qui log l'erreur et retourne une réponse générique.</p>",alternatives:[{name:"Erreurs attendues",description:"Validation, 404, auth invalide, réponses explicites."},{name:"Erreurs inattendues",description:"Handler global, log complet, réponse générique."},{name:"Monitoring",description:"Sentry ou équivalent quand le projet part en production."}]},senior:"<p>Il lit la stack trace de bas en haut jusqu'à trouver la première ligne qui pointe vers son propre code. Il ne cherche pas à faire disparaître l'erreur — il cherche à comprendre pourquoi elle se produit.</p>",errors:"<p><strong>Pattern 1 — Le catch vide :</strong> <code>try { ... } catch (e) {}</code> avale l'erreur silencieusement.</p><p><strong>Pattern 2 — La gestion d'erreur en dernier :</strong> les erreurs non gérées rendent le projet instable.</p><p><strong>Pattern 3 — Googler l'erreur sans la lire :</strong> chercher avant d'identifier la ligne de son propre code.</p>",invariants:"<p>Une erreur non gérée qui atteint l'utilisateur final est une erreur de conception, pas de malchance. Tout code qui peut échouer doit avoir une stratégie de gestion d'erreur explicite.</p>",practice:{commands:[{type:"comment",value:"Lire une stack trace"},{type:"cmd",value:"1. Lire type d'erreur + message"},{type:"cmd",value:"2. Trouver la première ligne de son propre code"},{type:"cmd",value:"3. Aller à cette ligne dans l'éditeur"},{type:"cmd",value:"4. Comprendre pourquoi la valeur n'est pas celle attendue"}],debt:"Pas de error handler global → une erreur non anticipée plante tout le processus en production."}}},debug:{id:"debug",label:"Debug",icon:"🔍",kind:"tool",osLabel:"Universel",sections:{why:"<p><code>console.log</code> partout est la stratégie de debug par défaut des débutants — et la moins efficace. Le debugger arrête l'exécution à un point précis, permet d'inspecter toutes les variables de la callstack, d'exécuter le code pas à pas, et de modifier les valeurs en direct.</p>",system:"<p>Le debugger s'intègre à VS Code via <code>launch.json</code>. Il intercepte le processus Node.js ou Python en cours d'exécution. Les breakpoints sont posés directement dans l'éditeur. Quand l'exécution atteint le breakpoint, le processus se pause et l'état complet du programme est visible.</p>",choice:{kind:"structured",main:"<p>Debugger graphique pour comprendre un flux complexe et inspecter des structures imbriquées. Logs ciblés pour les bugs intermittents ou la production. Les deux se complètent : debugger pour le local, logs pour la production.</p>",alternatives:[{name:"Debugger VS Code",description:"Pas à pas, breakpoints, callstack, variables."},{name:"Logs ciblés",description:"Utile en prod ou pour bugs intermittents."},{name:"Logpoints",description:"Logger sans modifier le code ni arrêter l'exécution."}]},senior:'<p>Il configure <code>launch.json</code> une fois en début de projet. Il utilise les breakpoints conditionnels et les logpoints. Il commence par formuler une hypothèse précise : "je crois que la variable X vaut Y à ce point" — puis il vérifie.</p>',errors:"<p><strong>Pattern 1 — Le console.log de masse :</strong> ajouter des logs partout en espérant tomber sur le problème.</p><p><strong>Pattern 2 — Modifier le code pour faire disparaître l'erreur :</strong> le bug n'est pas compris, il est caché.</p><p><strong>Pattern 3 — Ignorer la callstack :</strong> regarder uniquement la ligne du symptôme sans remonter à la cause.</p>",invariants:"<p>Déboguer c'est formuler et tester des hypothèses sur le comportement d'un système. La méthode ne change pas : observer → hypothèse → vérification → conclusion.</p>",practice:{commands:[{type:"comment",value:"Raccourcis VS Code"},{type:"cmd",value:"F5        → lancer / continuer"},{type:"cmd",value:"F9        → poser/retirer un breakpoint"},{type:"cmd",value:"F10       → step over"},{type:"cmd",value:"F11       → step into"},{type:"cmd",value:"Shift+F11 → step out"}],debt:"launch.json non commité → chaque dev reconfigure son debugger. Commiter .vscode/launch.json dans le dépôt."}}},"lint-format":{id:"lint-format",label:"Lint & Format",icon:"✨",kind:"tool",osLabel:"Universel",sections:{why:`<p>Le lint et le format sont configurés en fiche #02 — ici on parle de les intégrer dans le cycle quotidien. La configuration seule ne sert à rien si elle n'est pas déclenchée automatiquement et systématiquement. Un linter qui tourne manuellement "quand on y pense" est un linter ignoré.</p>`,system:"<p>Lint et format s'intègrent à trois niveaux : en temps réel dans VS Code, avant chaque commit via git hooks, et en CI sur chaque PR. VS Code corrige pendant l'écriture, les hooks bloquent les erreurs oubliées, la CI empêche les merges non conformes.</p>",choice:{kind:"structured",main:"<p>JS : ESLint + Prettier avec extensions VS Code, husky + lint-staged, script npm <code>lint</code> en CI. Python : Ruff + Black avec extension Ruff, pre-commit framework, scripts en CI. Alternative JS : Biome.</p>",alternatives:[{name:"VS Code",description:"Feedback immédiat et format on save."},{name:"Git hooks",description:"Filet de sécurité avant commit."},{name:"CI",description:"Blocage final avant merge."}]},senior:"<p>Il configure lint-staged plutôt que de lancer le linter sur tout le projet à chaque commit. Il commit aussi <code>.vscode/settings.json</code> avec les settings essentiels : format on save, formatter par défaut, fix on save.</p>",errors:"<p><strong>Pattern 1 — Le hook lent :</strong> linter tout le projet à chaque commit → hooks désactivés.</p><p><strong>Pattern 2 — La config VS Code non partagée :</strong> comportements différents selon la machine.</p><p><strong>Pattern 3 — Lint en CI uniquement :</strong> feedback trop tardif.</p>",invariants:"<p>La qualité du code ne repose pas sur la discipline individuelle. Elle repose sur des outils automatisés qui rendent la bonne pratique le chemin de moindre résistance.</p>",practice:{commands:[{type:"comment",value:"JS"},{type:"cmd",value:"npm install --save-dev lint-staged"},{type:"cmd",value:"echo 'npx lint-staged' > .husky/pre-commit"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install pre-commit"},{type:"cmd",value:"pre-commit install"},{type:"comment",value:".vscode/settings.json"},{type:"cmd",value:'"editor.formatOnSave": true'}],debt:".vscode/settings.json non commité → configuration divergente. lint-staged non configuré → hooks trop lents."}}},tests:{id:"tests",label:"Tests",icon:"✓",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Sans tests, chaque modification du code est un pari. On espère ne pas avoir cassé quelque chose ailleurs — mais on ne sait pas. Les tests transforment cette peur en certitude : une suite de tests qui passe est la preuve que le comportement attendu est préservé.</p>",system:"<p>Les tests sont écrits en parallèle du code, pas après. Ils s'exécutent via le script <code>test</code>, en mode watch pendant le développement, et en CI sur chaque PR. Ils se divisent en unitaires, intégration et E2E.</p>",choice:{kind:"structured",main:"<p>JavaScript : Jest, Vitest, Mocha + Chai. Pour un nouveau projet : Vitest si Vite est utilisé, Jest sinon. Python : pytest est le standard de facto ; unittest est inclus mais plus verbeux.</p>",alternatives:[{name:"Vitest",description:"Rapide, moderne, idéal avec Vite."},{name:"Jest",description:"Standard historique JS, tout-en-un."},{name:"pytest",description:"Standard Python, fixtures puissantes."}]},senior:"<p>Il commence par tester le comportement observable, pas l'implémentation interne. Il suit AAA : Arrange, Act, Assert. Les tests robustes vérifient ce que le code doit faire, pas comment il le fait.</p>",errors:"<p><strong>Pattern 1 — Les tests après coup :</strong> ils s'adaptent au code existant au lieu de spécifier le comportement attendu.</p><p><strong>Pattern 2 — Tester l'implémentation :</strong> tests fragiles qui cassent à chaque refactoring.</p><p><strong>Pattern 3 — Pas de tests en mode watch :</strong> feedback trop lent.</p>",invariants:"<p>Les tests sont une spécification exécutable du comportement attendu. Un test qui passe prouve un comportement, un test qui échoue détecte une régression.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"npm test"},{type:"cmd",value:"npm run test:watch"},{type:"cmd",value:"npx vitest --coverage"},{type:"comment",value:"Python"},{type:"cmd",value:"pytest tests/"},{type:"cmd",value:"pytest --watch"},{type:"cmd",value:"pytest --cov=src"}],debt:"Tests non lancés en CI → régressions non détectées. Coverage non mesuré → zones non testées invisibles."}}},"commit-push":{id:"commit-push",label:"Commit & Push",icon:"↑",kind:"vcs",osLabel:"Universel",sections:{why:"<p>Le commit est le geste fondamental du développement — il cristallise un état du code avec une intention documentée. Mais le commit seul ne suffit pas : le push envoie le travail vers le remote, le rendant accessible aux autres et sauvegardé hors de la machine locale.</p>",system:"<p>Le commit-push est le dernier nœud du cycle. Il arrive après que le lint et les tests passent. Le hook pre-commit s'exécute automatiquement avant chaque commit. Le push déclenche la CI si elle est configurée.</p>",choice:{kind:"structured",main:"<p>La vraie décision est sur la fréquence et la granularité. Recommandation pour débuter : commit souvent, avec des messages Conventional Commits. On peut toujours squash avant une PR si l'historique est trop granulaire.</p>",alternatives:[{name:"Commit souvent",description:"Petits commits atomiques, faciles à relire et revert."},{name:"Commit par feature",description:"Moins bruité, mais risque de gros commits."},{name:"Squash PR",description:"Historique final propre après travail granulaire."}]},senior:"<p>Il ne commit que ce qui est intentionnel. <code>git add -p</code> lui permet de sélectionner des hunks spécifiques. Il vérifie toujours <code>git diff --staged</code> avant de commiter. Il ne push jamais sur <code>main</code> directement.</p>",errors:"<p><strong>Pattern 1 — Le commit de fin de journée :</strong> commit géant mélangeant des modifications sans relation.</p><p><strong>Pattern 2 — <code>git add .</code> systématique :</strong> console.log oubliés, fichiers temporaires, contenu non intentionnel.</p><p><strong>Pattern 3 — Push sans tests :</strong> CI cassée et travail des autres bloqué.</p>",invariants:"<p>Un commit est une unité de travail atomique avec une intention documentée. Il doit pouvoir être lu, compris, et revert indépendamment des autres.</p>",practice:{commands:[{type:"cmd",value:"git status"},{type:"cmd",value:"git diff"},{type:"cmd",value:"git add -p"},{type:"cmd",value:"git diff --staged"},{type:"cmd",value:"npm test"},{type:"cmd",value:'git commit -m "feat(cart): add quantity validation"'},{type:"cmd",value:"git push origin ma-branche"},{type:"comment",value:"Jamais git push origin main"}],debt:"Commits géants = historique inutilisable. git add . sans vérification = contenu non intentionnel dans l'historique permanent."}}}},maps:e(i)},a={id:"git-workflow",part:"T",number:5,title:"Git Workflow",subtitle:"Passer du versioning local au travail collaboratif propre",badge:"Fiche T05 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"30 min",description:"Branching, Pull Requests, review, conflits, merge et historique propre dans un workflow Git d'équipe.",accent:"vcs",tabs:[{id:"workflow",label:"Workflow"}],nodes:{branches:{id:"branches",label:"Branches",icon:"⑂",kind:"vcs",osLabel:"Git",sections:{why:"<p>Travailler directement sur <code>main</code> mélange le code stable et le code en cours. Une branche crée un espace de travail isolé pour une intention précise : corriger un bug, ajouter une fonctionnalité, préparer une refactorisation. Elle permet d'avancer sans casser la version de référence.</p>",system:"<p>La branche part de <code>main</code>, reçoit des commits atomiques, puis devient une Pull Request. Elle est la base du workflow collaboratif : CI, review, discussion et merge s'organisent autour d'elle.</p>",choice:{kind:"structured",main:"<p>Pour débuter, trunk-based simple : <code>main</code> reste stable, branches courtes, merge rapide. Git Flow est plus lourd et utile surtout avec releases longues. La règle : une branche = une intention.</p>",alternatives:[{name:"feature branch",description:"Défaut pour une fonctionnalité ou un bug."},{name:"trunk-based",description:"Branches courtes, intégration fréquente."},{name:"Git Flow",description:"Plus lourd, adapté à cycles de release structurés."}]},senior:"<p>Il crée une branche depuis un <code>main</code> à jour. Il nomme la branche selon le travail : <code>feat/auth-login</code>, <code>fix/payment-timeout</code>. Il évite les branches longues qui accumulent conflits et dérive.</p>",errors:"<p><strong>Pattern 1 — Branche fourre-tout :</strong> plusieurs sujets dans une même branche.</p><p><strong>Pattern 2 — Branche trop longue :</strong> conflit massif au moment du merge.</p><p><strong>Pattern 3 — Travail sur main :</strong> pas d'isolation, pas de review propre.</p>",invariants:"<p>Une branche est une hypothèse de changement isolée. Elle doit rester courte, lisible et rattachée à une intention. Ce principe ne dépend pas de GitHub ou GitLab.</p>",practice:{commands:[{type:"cmd",value:"git switch main"},{type:"cmd",value:"git pull --ff-only"},{type:"cmd",value:"git switch -c feat/auth-login"},{type:"cmd",value:"git branch --show-current"}],debt:"Branches longues → conflits, review impossible, intégration tardive."}}},commits:{id:"commits",label:"Commits",icon:"✍",kind:"vcs",osLabel:"Git",sections:{why:"<p>Un commit cristallise une intention. Dans un workflow d'équipe, l'historique n'est pas juste une sauvegarde : c'est une documentation de décisions. Des commits propres rendent les reviews, reverts et audits possibles.</p>",system:"<p>Les commits alimentent la PR, déclenchent la CI, et deviennent l'historique final après merge. Ils doivent être assez petits pour être compris et assez complets pour représenter un changement cohérent.</p>",choice:{kind:"structured",main:"<p>Conventional Commits reste le meilleur défaut : <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>refactor</code>, <code>test</code>, <code>chore</code>. On peut squash au merge pour nettoyer l'historique si l'équipe préfère.</p>",alternatives:[{name:"Commits atomiques",description:"Chaque commit porte une intention."},{name:"Squash merge",description:"Une PR devient un commit propre."},{name:"Rebase interactif",description:"Nettoyer avant review ou merge."}]},senior:"<p>Il vérifie <code>git diff --staged</code> avant chaque commit. Il utilise <code>git add -p</code> pour éviter les commits qui mélangent plusieurs sujets.</p>",errors:"<p><strong>Pattern 1 — WIP permanent :</strong> historique illisible.</p><p><strong>Pattern 2 — Commit géant :</strong> review pénible, revert impossible.</p><p><strong>Pattern 3 — git add . aveugle :</strong> fichiers temporaires et logs dans l'historique.</p>",invariants:"<p>Un commit doit être lisible, intentionnel et réversible. Le format change, l'exigence reste.</p>",practice:{commands:[{type:"cmd",value:"git status"},{type:"cmd",value:"git add -p"},{type:"cmd",value:"git diff --staged"},{type:"cmd",value:'git commit -m "feat(auth): add login form"'}],debt:"Historique sale → reviews lentes et reverts dangereux."}}},push:{id:"push",label:"Push",icon:"↑",kind:"vcs",osLabel:"Remote",sections:{why:"<p>Un commit local n'existe que sur ta machine. Le push publie la branche sur le remote, déclenche la CI, sauvegarde le travail et rend la collaboration possible.</p>",system:"<p>Le push relie Git local à GitHub. Une branche poussée peut ouvrir une Pull Request, recevoir des commentaires, être testée par CI et fusionnée.</p>",choice:{kind:"structured",main:"<p>SSH est le défaut recommandé pour pousser sans friction. HTTPS fonctionne mais demande souvent tokens et configuration supplémentaire.</p>",alternatives:[{name:"SSH",description:"Défaut fluide pour GitHub."},{name:"HTTPS",description:"Possible, mais souvent moins agréable."},{name:"Fork",description:"Pour contribuer à un dépôt sans accès direct."}]},senior:"<p>Il pousse sa branche, jamais directement <code>main</code>. Il vérifie que la CI se lance après le push et corrige immédiatement si elle échoue.</p>",errors:"<p><strong>Pattern 1 — Push sur main :</strong> contourne review et protection.</p><p><strong>Pattern 2 — Push sans pull :</strong> branche en retard, conflits évitables.</p><p><strong>Pattern 3 — CI rouge ignorée :</strong> dette transmise à l'équipe.</p>",invariants:"<p>Le remote est l'espace partagé. Tout ce qui y arrive doit être intentionnel, traçable et vérifié.</p>",practice:{commands:[{type:"cmd",value:"git push -u origin feat/auth-login"},{type:"cmd",value:"git remote -v"},{type:"cmd",value:"git fetch origin"}],debt:"Branche locale non poussée → pas de backup, pas de review, pas de CI."}}},pr:{id:"pr",label:"Pull Request",icon:"PR",kind:"tool",osLabel:"GitHub",sections:{why:"<p>La Pull Request transforme une branche en conversation. Elle montre ce qui change, pourquoi, comment tester, et quels risques existent. Sans PR, le merge est un acte opaque.</p>",system:"<p>La PR agrège commits, diff, CI, review, commentaires et décision de merge. Elle est la porte d'entrée vers <code>main</code>.</p>",choice:{kind:"structured",main:"<p>Une bonne PR est petite, ciblée et testable. Draft PR pour signaler un travail en cours. Ready for review quand le changement est cohérent et vérifié localement.</p>",alternatives:[{name:"Draft PR",description:"Partager tôt sans demander validation finale."},{name:"Ready for review",description:"Demande explicite de relecture."},{name:"Stacked PRs",description:"Découper gros travail en petites PR dépendantes."}]},senior:"<p>Il écrit une description utile : contexte, solution, tests faits, captures si UI, risques. Il évite les PR massives et préfère plusieurs petites PR lisibles.</p>",errors:"<p><strong>Pattern 1 — PR sans description :</strong> le reviewer doit deviner.</p><p><strong>Pattern 2 — PR énorme :</strong> review superficielle.</p><p><strong>Pattern 3 — Mélanger refactor et feature :</strong> diff impossible à analyser.</p>",invariants:"<p>Une PR est une unité de revue. Elle doit être compréhensible par quelqu'un qui n'a pas vécu dans ta tête.</p>",practice:{commands:[{type:"comment",value:"Description PR"},{type:"comment",value:"Contexte"},{type:"comment",value:"Changements"},{type:"comment",value:"Tests effectués"},{type:"comment",value:"Risques / limites"},{type:"cmd",value:'gh pr create --draft --title "feat(auth): add login form" --body "Contexte, changements, tests, risques"'}],debt:"PRs trop grosses → bugs non vus, review lente, frustration."}}},review:{id:"review",label:"Review",icon:"👁",kind:"tool",osLabel:"Collaboration",sections:{why:"<p>La review existe pour détecter bugs, risques et incohérences avant merge. Elle transmet aussi les conventions de l'équipe. Ce n'est pas un jugement de valeur sur la personne : c'est un mécanisme de qualité collective.</p>",system:"<p>La review intervient après CI et avant merge. Elle commente le diff, demande des changements, approuve ou pose des questions. Elle complète les tests : les tests vérifient ce qui est automatisable, la review vérifie l'intention et le design.</p>",choice:{kind:"structured",main:"<p>Une review efficace sépare les bloquants des suggestions. Les commentaires doivent être précis, localisés, et expliquer le risque. Les préférences stylistiques doivent être automatisées par lint/format, pas débattues à la main.</p>",alternatives:[{name:"Request changes",description:"Bug ou risque bloquant."},{name:"Comment",description:"Question ou suggestion non bloquante."},{name:"Approve",description:"Le changement peut être intégré."}]},senior:"<p>Il review d'abord le comportement, puis l'architecture, puis les détails. Il cherche les bugs, les effets de bord, les tests manquants, les noms flous, les responsabilités mal placées.</p>",errors:'<p><strong>Pattern 1 — Review esthétique :</strong> débats de formatage déjà gérables par outil.</p><p><strong>Pattern 2 — Commentaires vagues :</strong> "pas propre" sans explication.</p><p><strong>Pattern 3 — Approve automatique :</strong> la review devient décorative.</p>',invariants:"<p>La review protège la branche principale et diffuse la connaissance. Elle doit être exigeante, respectueuse et orientée risque.</p>",practice:{commands:[{type:"comment",value:"Checklist review"},{type:"comment",value:"Le comportement demandé est-il couvert ?"},{type:"comment",value:"Les tests sont-ils suffisants ?"},{type:"comment",value:"Les responsabilités sont-elles au bon endroit ?"},{type:"comment",value:"Y a-t-il un risque de régression ?"},{type:"cmd",value:"gh pr diff"}],debt:"Review faible → main devient une zone de surprise."}}},conflicts:{id:"conflicts",label:"Conflits",icon:"⚠",kind:"runtime",osLabel:"Git",sections:{why:"<p>Un conflit apparaît quand Git ne peut pas fusionner automatiquement deux modifications sur la même zone. Ce n'est pas une catastrophe : c'est Git qui demande à un humain de décider quelle intention garder.</p>",system:"<p>Les conflits apparaissent pendant merge, rebase ou pull. Ils doivent être résolus localement, testés, puis committés. Plus une branche reste longtemps séparée, plus les conflits deviennent probables.</p>",choice:{kind:"structured",main:"<p>Merge conserve l'historique tel quel. Rebase rejoue tes commits sur une base plus récente et donne un historique plus linéaire. Pour débuter, merge est plus simple. Rebase est puissant mais demande prudence sur branches partagées.</p>",alternatives:[{name:"merge main",description:"Simple, explicite, moins risqué."},{name:"rebase main",description:"Historique linéaire, attention branches partagées."},{name:"résolution manuelle",description:"Choisir intention finale, pas juste supprimer marqueurs."}]},senior:`<p>Il lit le contexte métier avant de résoudre. Il ne choisit pas "ours" ou "theirs" aveuglément. Après résolution, il relance tests et lint, parce qu'un conflit résolu peut compiler mais casser le comportement.</p>`,errors:"<p><strong>Pattern 1 — Supprimer les marqueurs sans comprendre :</strong> code incohérent.</p><p><strong>Pattern 2 — Force push dangereux :</strong> réécrit le travail des autres.</p><p><strong>Pattern 3 — Pas de tests après conflit :</strong> intégration cassée.</p>",invariants:"<p>Résoudre un conflit, c'est réconcilier deux intentions. La bonne résolution est celle qui préserve le comportement attendu, pas celle qui fait disparaître les chevrons.</p>",practice:{commands:[{type:"cmd",value:"git fetch origin"},{type:"cmd",value:"git merge origin/main"},{type:"cmd",value:"git status"},{type:"cmd",value:"git add fichier-resolu"},{type:"cmd",value:"npm test  # ou pytest"}],debt:"Branches longues → conflits plus gros. Intégrer main régulièrement."}}},merge:{id:"merge",label:"Merge",icon:"✓",kind:"vcs",osLabel:"GitHub",sections:{why:"<p>Le merge intègre un changement validé dans la branche principale. C'est le moment où le travail cesse d'être une proposition et devient la version de référence.</p>",system:"<p>Le merge arrive après CI verte, review approuvée, conflits résolus. Il déclenche souvent un déploiement ou une nouvelle étape de pipeline.</p>",choice:{kind:"structured",main:"<p>Merge commit préserve l'historique de branche. Squash merge produit un commit propre par PR. Rebase merge garde un historique linéaire. Pour un catalogue ou une petite équipe, squash merge est souvent lisible.</p>",alternatives:[{name:"Merge commit",description:"Préserve tout l'historique de branche."},{name:"Squash merge",description:"Une PR = un commit final propre."},{name:"Rebase merge",description:"Historique linéaire sans commit de merge."}]},senior:"<p>Il vérifie que la PR correspond encore à son intention initiale. Il supprime la branche après merge. Il surveille le déploiement ou la CI post-merge.</p>",errors:"<p><strong>Pattern 1 — Merge CI rouge :</strong> main cassée par négligence.</p><p><strong>Pattern 2 — Merge sans review :</strong> pas de contrôle collectif.</p><p><strong>Pattern 3 — Branches jamais supprimées :</strong> remote encombré et ambigu.</p>",invariants:"<p>Main doit rester stable. Le merge est une décision de confiance appuyée par tests, review et clarté du changement.</p>",practice:{commands:[{type:"cmd",value:"CI verte"},{type:"cmd",value:"Review approuvée"},{type:"cmd",value:"Squash and merge"},{type:"cmd",value:"Delete branch"},{type:"cmd",value:"git switch main && git pull --ff-only"}],debt:"Main instable → toute l'équipe ralentit. Protéger main avec checks obligatoires."}}}},maps:{workflow:{viewBox:"0 0 900 300",nodes:[{id:"branches",x:20,y:115,w:110,h:65},{id:"commits",x:175,y:55,w:110,h:65},{id:"push",x:175,y:175,w:100,h:65},{id:"pr",x:335,y:115,w:120,h:65},{id:"review",x:510,y:55,w:110,h:65},{id:"conflicts",x:510,y:175,w:110,h:65},{id:"merge",x:680,y:115,w:110,h:65}],edges:[{x1:130,y1:135,x2:173,y2:88},{x1:130,y1:160,x2:173,y2:207},{x1:285,y1:88,x2:333,y2:135},{x1:275,y1:207,x2:333,y2:160},{x1:455,y1:135,x2:508,y2:88},{x1:455,y1:160,x2:508,y2:207},{x1:620,y1:88,x2:678,y2:135},{x1:620,y1:207,x2:678,y2:160}]}}},o={viewBox:"0 0 860 300",nodes:[{id:"variables",x:20,y:115,w:110,h:65},{id:"config",x:175,y:55,w:110,h:65},{id:"validation",x:175,y:175,w:120,h:65},{id:"database",x:345,y:115,w:130,h:65},{id:"modeles",x:535,y:115,w:110,h:65},{id:"migrations",x:700,y:55,w:120,h:65},{id:"cache",x:700,y:175,w:110,h:65}],edges:[{x1:130,y1:135,x2:173,y2:88},{x1:130,y1:160,x2:173,y2:207},{x1:285,y1:88,x2:343,y2:135},{x1:295,y1:207,x2:343,y2:160},{x1:475,y1:147,x2:533,y2:147},{x1:645,y1:135,x2:698,y2:88},{x1:645,y1:160,x2:698,y2:207}]},l={id:"donnees-et-persistance",part:"T",number:6,title:"Données et Persistance",subtitle:"Comprendre comment les données backend sont validées, modélisées, stockées et migrées",badge:"Fiche T06 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds · backend","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte backend pour comprendre configuration, validation, SQL, ORM, modèles, migrations, repositories et cache.",accent:"runtime",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{variables:{id:"variables",label:"Variables",icon:"x=",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Une variable est le plus petit endroit où une information peut vivre pendant l'exécution. Sans variables bien nommées et bien limitées, le programme devient une suite de valeurs anonymes qu'il faut garder en tête mentalement. Les variables existent pour donner un nom à une information, réduire la charge cognitive, et rendre explicite ce que le code manipule.</p><p>Mais une variable est aussi dangereuse : si elle est mutable, globale, ou partagée sans contrôle, elle devient une source d'effets de bord. Comprendre les variables, c'est comprendre que la donnée n'est jamais neutre — elle a une portée, une durée de vie, et un propriétaire.</p>",system:"<p>Les variables sont présentes dans toutes les couches : routes, services, composants, repositories, tests. Elles transportent les données depuis l'entrée utilisateur jusqu'à la base, ou depuis la base jusqu'à l'affichage. Les variables locales vivent le temps d'une fonction. Les variables d'environnement configurent l'application. L'état frontend vit plus longtemps et influence l'interface. La base de données persiste au-delà du processus.</p>",choice:{kind:"structured",main:`<p>La vraie décision n'est pas "variable ou pas", mais "quelle durée de vie et quelle portée ?" Une donnée temporaire reste locale. Une donnée de configuration va dans l'environnement. Une donnée partagée dans l'UI va dans le state. Une donnée durable va en base. Plus une variable vit longtemps et plus elle est accessible, plus elle doit être contrôlée.</p>`,alternatives:[{name:"Variable locale",description:"Pour une donnée temporaire limitée à une fonction."},{name:"Constante",description:"Pour une valeur stable et intentionnelle."},{name:"État partagé",description:"Pour une donnée qui influence plusieurs parties du système."}]},senior:"<p>Il réduit la portée des variables au minimum. Il préfère <code>const</code> à <code>let</code> en JavaScript quand la référence ne change pas. En Python, il évite les variables globales mutables et rend les dépendances explicites via paramètres ou injection. Il nomme les variables selon leur rôle métier, pas selon leur type technique : <code>activeUsers</code> dit plus que <code>list</code>.</p>",errors:"<p><strong>Pattern 1 — La variable globale mutable :</strong> tout le monde peut la modifier, personne ne sait qui l'a changée.</p><p><strong>Pattern 2 — Le nom flou :</strong> <code>data</code>, <code>result</code>, <code>temp</code> partout → impossible de comprendre l'intention.</p><p><strong>Pattern 3 — La mutation cachée :</strong> une fonction modifie un objet reçu en paramètre sans le dire → bugs difficiles à suivre.</p>",invariants:"<p>Une donnée doit avoir un propriétaire clair, une portée limitée, et une durée de vie maîtrisée. Ce principe s'applique partout : variable locale, state React, cache Redis, ligne SQL. Ce qui change : le support. Ce qui ne change pas : une donnée sans propriétaire devient une source de bug.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"const totalPrice = calculateTotal(cartItems)"},{type:"cmd",value:"let retryCount = 0 // uniquement si la valeur change réellement"},{type:"comment",value:"Python"},{type:"cmd",value:"total_price = calculate_total(cart_items)"},{type:"cmd",value:"MAX_RETRIES = 3"},{type:"comment",value:"Vérification"},{type:"cmd",value:"Une variable doit pouvoir répondre à : qui la crée, qui la lit, qui la modifie ?"}],debt:"Variables globales mutables → effets de bord invisibles. Réduire la portée et rendre les mutations explicites."}}},config:{id:"config",label:"Configuration",icon:"⚙",kind:"infra",osLabel:"Universel",sections:{why:"<p>Le même code doit tourner dans plusieurs environnements : local, test, staging, production. Ce qui change entre ces environnements — URLs, ports, clés API, mode debug, niveau de logs — ne doit pas être hardcodé. La configuration existe pour séparer ce que l'application fait de l'endroit où elle s'exécute.</p>",system:"<p>La configuration est chargée au démarrage, souvent depuis les variables d'environnement, puis injectée dans les couches qui en ont besoin : base de données, logger, clients d'API, serveur HTTP. Elle est proche du point d'entrée mais ne doit pas être dispersée dans tout le code.</p>",choice:{kind:"structured",main:"<p>Pour les petits projets : <code>.env</code> + module de config central. Pour les projets plus stricts : validation typée au démarrage. En JavaScript, Zod ou envalid. En Python, Pydantic Settings. Le principe : l'application doit planter immédiatement si une configuration obligatoire manque.</p>",alternatives:[{name:".env + dotenv",description:"Simple et suffisant en développement."},{name:"Config validée",description:"Zod/envalid ou Pydantic Settings pour éviter les erreurs tardives."},{name:"Secrets manager",description:"Doppler, Vault, AWS SSM quand les environnements se multiplient."}]},senior:`<p>Il crée un module unique de configuration et interdit les accès dispersés à <code>process.env</code> ou <code>os.environ</code> dans toute l'application. Il valide les types : un port est un nombre, un booléen n'est pas la chaîne <code>"false"</code>, une URL doit être une URL. Il documente chaque variable dans <code>.env.example</code>.</p>`,errors:"<p><strong>Pattern 1 — process.env partout :</strong> impossible de savoir quelles variables sont requises.</p><p><strong>Pattern 2 — Pas de validation :</strong> l'app démarre avec une config invalide et casse trois couches plus loin.</p><p><strong>Pattern 3 — Config committée :</strong> secrets ou URLs privées versionnés dans Git.</p>",invariants:"<p>La configuration est une dépendance externe du programme. Elle doit être centralisée, validée, documentée, et injectée. Ce qui change : l'outil de validation. Ce qui ne change pas : une app doit refuser de démarrer avec une config invalide.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"npm install dotenv zod"},{type:"cmd",value:"src/config/env.js"},{type:"cmd",value:"const env = EnvSchema.parse(process.env)"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install pydantic-settings python-dotenv"},{type:"cmd",value:"class Settings(BaseSettings): database_url: str"},{type:"comment",value:"Vérification"},{type:"cmd",value:"Supprimer DATABASE_URL → l'app doit refuser de démarrer"}],debt:"Configuration non validée → bugs tardifs et messages incompréhensibles. Centraliser la config avant que le projet grossisse."}}},validation:{id:"validation",label:"Validation",icon:"✓",kind:"tool",osLabel:"Universel",sections:{why:"<p>Le monde extérieur ment, se trompe, ou envoie des données incomplètes. Un formulaire peut envoyer un email invalide, une API peut recevoir un nombre sous forme de chaîne, un client peut omettre un champ obligatoire. La validation existe pour protéger le cœur de l'application : avant d'entrer dans la logique métier, les données doivent être vérifiées, typées, et normalisées.</p>",system:"<p>La validation se place aux frontières : routes HTTP, formulaires frontend, variables d'environnement, messages de queue, fichiers importés. Elle précède les services. Les services ne devraient pas recevoir des données brutes et incertaines, mais des données déjà validées et structurées.</p>",choice:{kind:"structured",main:"<p>JavaScript : Zod est le choix moderne pour valider et inférer les types. Yup existe encore dans beaucoup de formulaires. Python : Pydantic est le standard avec FastAPI. La décision importante : valider à l'entrée, pas au milieu de la logique métier.</p>",alternatives:[{name:"Zod",description:"Validation JS/TS moderne, inférence de types."},{name:"Pydantic",description:"Validation Python standard, intégré à FastAPI."},{name:"Validation DB",description:"Dernier filet, pas remplacement de la validation applicative."}]},senior:"<p>Il distingue validation syntaxique et validation métier. Syntaxique : email valide, champ requis, longueur minimale. Métier : email déjà utilisé, solde insuffisant, commande non annulable. La première appartient aux schémas de validation. La seconde appartient aux services.</p>",errors:"<p><strong>Pattern 1 — Validation absente :</strong> les données invalides atteignent la base.</p><p><strong>Pattern 2 — Validation dupliquée :</strong> règles différentes frontend/backend → incohérences.</p><p><strong>Pattern 3 — Tout mettre dans le schéma :</strong> règles métier complexes cachées dans la validation d'entrée.</p>",invariants:"<p>Toute frontière du système doit valider ce qui la traverse. Une donnée validée peut circuler plus loin avec confiance. Une donnée non validée est contaminante. Ce principe vaut pour HTTP, CLI, fichiers, env vars, formulaires et événements.</p>",practice:{commands:[{type:"comment",value:"JavaScript avec Zod"},{type:"cmd",value:"npm install zod"},{type:"cmd",value:"const UserSchema = z.object({ email: z.string().email() })"},{type:"cmd",value:"const data = UserSchema.parse(req.body)"},{type:"comment",value:"Python avec Pydantic"},{type:"cmd",value:"class CreateUser(BaseModel): email: EmailStr"},{type:"cmd",value:"async def create_user(data: CreateUser):"}],debt:"Validation dispersée → règles incohérentes. Centraliser les schémas et séparer validation syntaxique / règles métier."}}},database:{id:"database",label:"Base de données",icon:"🗄",kind:"runtime",osLabel:"Universel",sections:{why:"<p>La mémoire du programme disparaît quand le processus s'arrête. Une application qui doit conserver des utilisateurs, commandes, messages ou paiements a besoin d'un stockage durable. La base de données existe pour persister les informations, les retrouver efficacement, garantir leur cohérence, et survivre aux redémarrages.</p>",system:"<p>La base de données est derrière les repositories. Les routes ne lui parlent jamais directement. Les services formulent des intentions métier, les repositories traduisent en requêtes, la base persiste et renvoie les données. Elle est une dépendance externe critique : lente, faillible, partagée, et durable.</p>",choice:{kind:"structured",main:"<p>Le choix principal : relationnel ou document. PostgreSQL est le défaut sérieux pour la majorité des applications métier. SQLite est parfait pour local, prototypage et petites apps. MongoDB peut être pertinent pour documents flexibles, mais ne doit pas être choisi pour éviter de modéliser.</p>",alternatives:[{name:"PostgreSQL",description:"Défaut robuste, relationnel, transactions, contraintes."},{name:"SQLite",description:"Simple, local, fichier unique, excellent pour démarrer."},{name:"MongoDB",description:"Documents flexibles, utile si le modèle est réellement documentaire."}]},senior:"<p>Il commence par modéliser les relations et contraintes. Une contrainte en base vaut mieux qu'une règle oubliée dans un service. Il pense transactions quand plusieurs écritures doivent réussir ou échouer ensemble. Il sait que la base est souvent la source de vérité ultime.</p>",errors:"<p><strong>Pattern 1 — Tout en JSON libre :</strong> pas de contraintes, données incohérentes.</p><p><strong>Pattern 2 — Pas d'index :</strong> requêtes rapides en dev, lentes en prod.</p><p><strong>Pattern 3 — Logique uniquement en app :</strong> la base accepte des états impossibles.</p>",invariants:"<p>Une donnée persistante doit être cohérente, requêtable, sauvegardable et migrable. Ce qui change : SQL, NoSQL, ORM, cloud provider. Ce qui ne change pas : la base est une frontière critique qui demande discipline.</p>",practice:{commands:[{type:"comment",value:"Local PostgreSQL"},{type:"cmd",value:"createdb mon_projet_dev"},{type:"cmd",value:"psql mon_projet_dev"},{type:"comment",value:"SQLite"},{type:"cmd",value:"sqlite3 dev.db"},{type:"comment",value:"Vérification"},{type:"cmd",value:"La table a des clés primaires, contraintes NOT NULL, indexes utiles"}],debt:"Pas de contraintes ni d'indexes → dette invisible qui explose avec les données réelles."}}},modeles:{id:"modeles",label:"Modèles",icon:"▦",kind:"tool",osLabel:"Universel",sections:{why:"<p>Une application manipule des concepts : User, Product, Order, Invoice. Les modèles existent pour donner une forme explicite à ces concepts. Sans modèle, les données circulent sous forme de dictionnaires ou objets anonymes, et personne ne sait vraiment quels champs existent, lesquels sont obligatoires, ni quelles relations sont valides.</p>",system:"<p>Les modèles font le pont entre la base, les repositories, les services et parfois la validation. Selon l'outil, ils peuvent représenter le schéma de base (Prisma, SQLAlchemy, Django models), le domaine métier, ou les DTOs d'entrée/sortie. Il faut savoir quel rôle joue chaque modèle.</p>",choice:{kind:"structured",main:"<p>JavaScript : Prisma schema pour la persistance, classes/types pour le domaine, Zod pour les DTOs. Python : SQLAlchemy ou Django models pour la persistance, Pydantic pour les schémas d'API. La séparation devient importante dès que les données exposées ne sont pas exactement les données stockées.</p>",alternatives:[{name:"Modèle persistance",description:"Table, colonnes, relations, contraintes."},{name:"DTO / Schema API",description:"Forme reçue ou renvoyée par l'API."},{name:"Modèle domaine",description:"Concept métier indépendant de la base."}]},senior:"<p>Il évite d'exposer directement les modèles de base de données dans les réponses API. Un User en base peut avoir <code>passwordHash</code>, <code>deletedAt</code>, des champs internes. La réponse publique doit être contrôlée. Il nomme les modèles selon le métier, pas selon l'écran qui les utilise.</p>",errors:"<p><strong>Pattern 1 — Le modèle unique pour tout :</strong> base, API, formulaire, domaine mélangés.</p><p><strong>Pattern 2 — Champs sensibles exposés :</strong> passwordHash ou tokens renvoyés par accident.</p><p><strong>Pattern 3 — Relations floues :</strong> pas de cardinalité claire entre entités.</p>",invariants:"<p>Un modèle est un contrat sur la forme d'une donnée. Les contrats doivent être explicites, nommés, testables, et adaptés à leur frontière. Ce qui change : ORM, framework, langage. Ce qui ne change pas : une donnée sans forme explicite devient fragile.</p>",practice:{commands:[{type:"comment",value:"Prisma"},{type:"cmd",value:"model User { id Int @id @default(autoincrement()) email String @unique }"},{type:"comment",value:"Pydantic"},{type:"cmd",value:"class UserResponse(BaseModel): id: int; email: EmailStr"},{type:"comment",value:"SQLAlchemy"},{type:"cmd",value:"class User(Base): __tablename__ = 'users'"},{type:"comment",value:"Vérification"},{type:"cmd",value:"Aucun champ sensible dans les schémas de réponse"}],debt:"Modèles de persistance exposés directement → fuite de données internes et couplage API/base."}}},migrations:{id:"migrations",label:"Migrations",icon:"⇄",kind:"infra",osLabel:"Universel",sections:{why:"<p>Le schéma de base évolue : ajouter une table, renommer une colonne, créer un index, modifier une contrainte. Si ces changements sont faits à la main, personne ne sait exactement quel état de base correspond à quelle version du code. Les migrations versionnent l'évolution de la base comme Git versionne le code.</p>",system:"<p>Les migrations sont entre les modèles et la base. Elles transforment une intention de modèle en changement durable du schéma. Elles s'exécutent en local, en CI, et au déploiement. Elles doivent être commitées avec le code qui dépend d'elles.</p>",choice:{kind:"structured",main:"<p>JavaScript : Prisma Migrate, Knex migrations, TypeORM migrations. Python : Alembic pour SQLAlchemy, migrations Django natives. Le bon outil est souvent imposé par l'ORM. Le principe : jamais de modification manuelle non versionnée en base partagée.</p>",alternatives:[{name:"Prisma Migrate",description:"Très intégré à Prisma, simple pour JS/TS."},{name:"Alembic",description:"Standard SQLAlchemy."},{name:"Django migrations",description:"Générées et appliquées par Django."}]},senior:"<p>Il relit les migrations générées avant de les appliquer. Renommer une colonne peut être détecté comme drop + create, donc perte de données. Il pense rollback, données existantes, valeurs par défaut, migrations longues, et compatibilité entre ancienne et nouvelle version du code.</p>",errors:"<p><strong>Pattern 1 — Modifier la base à la main :</strong> le schéma local ne correspond plus au repo.</p><p><strong>Pattern 2 — Migration destructive non relue :</strong> drop de colonne avec données utiles.</p><p><strong>Pattern 3 — Migration sans données par défaut :</strong> ajout d'une colonne NOT NULL sur table remplie → échec en production.</p>",invariants:"<p>Le schéma de base est du code. Il doit être versionné, relu, testé, et déployé dans l'ordre. Ce qui change : l'outil. Ce qui ne change pas : pas de changement de schéma non traçable.</p>",practice:{commands:[{type:"comment",value:"Prisma"},{type:"cmd",value:"npx prisma migrate dev --name add_users"},{type:"cmd",value:"npx prisma migrate deploy"},{type:"comment",value:"Alembic"},{type:"cmd",value:'alembic revision --autogenerate -m "add users"'},{type:"cmd",value:"alembic upgrade head"},{type:"comment",value:"Django"},{type:"cmd",value:"python manage.py makemigrations"},{type:"cmd",value:"python manage.py migrate"}],debt:"Migrations non relues → pertes de données. Base modifiée à la main → environnements désynchronisés."}}},cache:{id:"cache",label:"Cache",icon:"⏱",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Certaines données coûtent cher à recalculer ou à récupérer : requête SQL lourde, appel API externe, rendu serveur, liste fréquemment consultée. Le cache existe pour stocker temporairement un résultat et éviter de refaire le même travail. Mais le cache introduit un problème : il peut devenir faux.</p>",system:"<p>Le cache peut vivre côté frontend (React Query), côté serveur (mémoire processus), côté infrastructure (Redis), ou côté HTTP (headers cache-control). Il se place entre la demande et la source de vérité. La base reste la vérité durable ; le cache est une copie temporaire optimisée.</p>",choice:{kind:"structured",main:"<p>Cache local simple pour données peu critiques. React Query pour server state frontend. Redis pour cache partagé entre instances. HTTP cache pour ressources publiques. La vraie décision : quelle stratégie d'invalidation ? TTL, invalidation manuelle, invalidation sur mutation, ou pas de cache.</p>",alternatives:[{name:"TTL",description:"Expire automatiquement après une durée."},{name:"Invalidation sur mutation",description:"On supprime/rafraîchit après modification."},{name:"Redis",description:"Cache partagé robuste côté backend."}]},senior:`<p>Il n'ajoute pas de cache avant d'avoir mesuré. Le cache optimise un problème réel, pas une peur abstraite. Il documente la source de vérité, la durée de vie, et les conditions d'invalidation. Il sait que les bugs de cache ressemblent souvent à des bugs fantômes : "ça dépend de quand tu regardes".</p>`,errors:"<p><strong>Pattern 1 — Cache prématuré :</strong> complexité ajoutée sans problème de performance mesuré.</p><p><strong>Pattern 2 — Pas d'invalidation :</strong> données anciennes servies indéfiniment.</p><p><strong>Pattern 3 — Cache comme source de vérité :</strong> perte ou redémarrage du cache = données incohérentes.</p>",invariants:"<p>Un cache est une copie, jamais la vérité. Toute copie doit avoir une stratégie de fraîcheur. Ce qui change : mémoire, Redis, CDN, React Query. Ce qui ne change pas : plus un cache est efficace, plus son invalidation devient critique.</p>",practice:{commands:[{type:"comment",value:"React Query"},{type:"cmd",value:"queryClient.invalidateQueries({ queryKey: ['users'] })"},{type:"comment",value:"Redis"},{type:"cmd",value:"redis.set('users:active', JSON.stringify(users), 'EX', 60)"},{type:"cmd",value:"redis.del('users:active')"},{type:"comment",value:"HTTP"},{type:"cmd",value:"Cache-Control: public, max-age=3600"}],debt:"Cache sans stratégie d'invalidation → bugs intermittents et difficiles à reproduire."}}}},maps:e(o)},u={viewBox:"0 0 980 300",nodes:[{id:"http",x:20,y:115,w:110,h:65},{id:"rest",x:175,y:55,w:100,h:65},{id:"json",x:175,y:175,w:100,h:65},{id:"status",x:330,y:115,w:120,h:65},{id:"client",x:510,y:55,w:120,h:65},{id:"auth",x:510,y:175,w:100,h:65},{id:"cors",x:690,y:55,w:100,h:65},{id:"network",x:690,y:175,w:130,h:65}],edges:[{x1:130,y1:135,x2:173,y2:88},{x1:130,y1:160,x2:173,y2:207},{x1:275,y1:88,x2:328,y2:135},{x1:275,y1:207,x2:328,y2:160},{x1:450,y1:135,x2:508,y2:88},{x1:450,y1:160,x2:508,y2:207},{x1:630,y1:88,x2:688,y2:88},{x1:610,y1:207,x2:688,y2:207}]},c={id:"api-communication",part:"T",number:7,title:"API et Communication",subtitle:"Comprendre comment deux systèmes se parlent sans partager la même mémoire",badge:"Fiche T07 — Vision Systémique",status:"Modèle stabilisé",meta:["8 nœuds · 2 types","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte pour comprendre HTTP, REST, JSON, status codes, clients API, authentification, CORS et erreurs réseau.",accent:"tool",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{http:{id:"http",label:"HTTP",icon:"⇄",kind:"infra",osLabel:"Universel",sections:{why:"<p>Deux programmes ne partagent pas la même mémoire. Un navigateur, un backend, un service externe, une application mobile : chacun vit dans son propre processus, souvent sur une machine différente. HTTP existe comme protocole commun pour formuler une demande, transporter des données, et recevoir une réponse structurée. Sans protocole partagé, chaque communication serait une intégration sur mesure.</p>",system:"<p>HTTP est la couche de transport applicative. Les routes reçoivent des requêtes HTTP, les services traitent l'intention, les repositories récupèrent les données, puis la réponse remonte. Côté client, fetch/axios/httpx transforment un appel de fonction en requête réseau. HTTP est le langage commun entre frontend, backend et services externes.</p>",choice:{kind:"structured",main:"<p>HTTP repose sur des méthodes qui portent une intention : <code>GET</code> pour lire, <code>POST</code> pour créer ou déclencher, <code>PUT/PATCH</code> pour modifier, <code>DELETE</code> pour supprimer. La décision importante est de respecter la sémantique : ne pas modifier des données avec GET, ne pas utiliser POST pour tout.</p>",alternatives:[{name:"HTTP/REST",description:"Défaut pour APIs web lisibles et simples."},{name:"GraphQL",description:"Client choisit la forme des données, utile pour interfaces complexes."},{name:"gRPC",description:"Contrat fort et performant entre services backend."}]},senior:"<p>Il pense en termes de contrat : méthode, URL, headers, body, réponse, erreurs. Il sait que HTTP est stateless : chaque requête doit contenir tout ce qui permet de la traiter, notamment l'authentification. Il logue méthode, path, status code et durée pour rendre le trafic observable.</p>",errors:"<p><strong>Pattern 1 — POST partout :</strong> l'API devient imprévisible et difficile à documenter.</p><p><strong>Pattern 2 — État caché côté serveur :</strong> une requête dépend d'une requête précédente sans l'exprimer.</p><p><strong>Pattern 3 — Ignorer les headers :</strong> auth, content-type, cache et CORS deviennent incompréhensibles.</p>",invariants:"<p>Communiquer entre systèmes exige un protocole explicite. Ce qui change : HTTP, WebSocket, gRPC. Ce qui ne change pas : une requête doit avoir une intention claire, une forme documentée, et une réponse interprétable.</p>",practice:{commands:[{type:"cmd",value:"curl -i http://localhost:3000/api/v1/health"},{type:"cmd",value:`curl -X POST http://localhost:3000/api/v1/users -H 'Content-Type: application/json' -d '{"email":"a@b.com"}'`},{type:"comment",value:"GET /api/v1/users"},{type:"comment",value:"POST /api/v1/users"},{type:"comment",value:"PATCH /api/v1/users/:id"},{type:"comment",value:"DELETE /api/v1/users/:id"}],debt:"Méthodes HTTP utilisées au hasard → API imprévisible. Documenter méthode, path, body et réponse dès la création d'une route."}}},rest:{id:"rest",label:"REST",icon:"↦",kind:"tool",osLabel:"Universel",sections:{why:"<p>Sans convention d'API, chaque endpoint devient une invention : <code>/getUser</code>, <code>/deleteProduct</code>, <code>/doLogin</code>. REST apporte une grammaire commune : les URLs représentent des ressources, les méthodes HTTP représentent les actions. Le résultat est une API prédictible.</p>",system:"<p>REST se place au niveau des routes. Il influence le nommage, la structure des URLs, les méthodes utilisées, les status codes et les réponses. Les services ne savent pas qu'ils sont appelés via REST : ils reçoivent une intention métier. REST est une convention de frontière, pas une logique métier.</p>",choice:{kind:"structured",main:"<p>REST strict n'est pas toujours nécessaire. L'objectif pratique est une API resource-oriented : ressources au pluriel, hiérarchie simple, actions rares et nommées quand elles ne rentrent pas dans CRUD. Une API lisible vaut mieux qu'une API qui force REST de manière dogmatique.</p>",alternatives:[{name:"REST resource-oriented",description:"Défaut simple : /users, /orders, /products."},{name:"RPC/action",description:"Pour actions métier difficiles à modéliser en ressource."},{name:"GraphQL",description:"Quand le problème principal est la forme des données côté client."}]},senior:"<p>Il versionne l'API quand elle est consommée par d'autres systèmes : <code>/api/v1</code>. Il évite d'exposer la structure interne de la base dans les URLs. Il garde la cohérence : pagination, filtres, erreurs et enveloppes de réponse ont le même format partout.</p>",errors:"<p><strong>Pattern 1 — Verbes dans les URLs :</strong> <code>/getUser</code>, <code>/createOrder</code> au lieu d'utiliser les méthodes HTTP.</p><p><strong>Pattern 2 — Ressources singulières/plurielles mélangées :</strong> <code>/user</code>, <code>/products</code>, <code>/ordersList</code>.</p><p><strong>Pattern 3 — Réponses incohérentes :</strong> parfois <code>{data}</code>, parfois un tableau brut, parfois <code>{result}</code>.</p>",invariants:"<p>Une API est une interface publique. Elle doit être prévisible avant même d'être lue en détail. Ce qui change : REST, RPC, GraphQL. Ce qui ne change pas : un consommateur ne doit pas deviner la forme des routes.</p>",practice:{commands:[{type:"comment",value:"GET    /api/v1/users"},{type:"comment",value:"GET    /api/v1/users/:id"},{type:"comment",value:"POST   /api/v1/users"},{type:"comment",value:"PATCH  /api/v1/users/:id"},{type:"comment",value:"DELETE /api/v1/users/:id"},{type:"comment",value:"GET    /api/v1/users?limit=20&offset=0"},{type:"cmd",value:"curl -i 'http://localhost:3000/api/v1/users?limit=20&offset=0'"}],debt:"Routes incohérentes → documentation lourde et clients fragiles. Définir une convention REST dès le premier endpoint."}}},json:{id:"json",label:"JSON",icon:"{}",kind:"runtime",osLabel:"Universel",sections:{why:"<p>HTTP transporte des octets, pas des objets. JSON est devenu le format commun pour représenter des données structurées entre systèmes : objets, tableaux, chaînes, nombres, booléens, null. Il est lisible par les humains, supporté partout, et assez simple pour devenir le langage de données par défaut des APIs web.</p>",system:"<p>JSON est le corps des requêtes et réponses. Les routes parsuent le JSON entrant, la validation le transforme en données fiables, les services travaillent avec ces objets, puis la réponse est sérialisée en JSON. Côté frontend, fetch ou axios désérialisent la réponse avec <code>response.json()</code>.</p>",choice:{kind:"structured",main:"<p>JSON est le défaut pour les APIs web. FormData est préférable pour fichiers et formulaires multipart. Protocol Buffers ou MessagePack peuvent être utiles pour performance ou contrats stricts, mais ajoutent de la complexité.</p>",alternatives:[{name:"JSON",description:"Défaut lisible et universel."},{name:"FormData",description:"Fichiers, multipart, formulaires complexes."},{name:"Protobuf",description:"Contrat strict et performant entre services."}]},senior:"<p>Il distingue absence de champ, champ à <code>null</code>, et valeur vide. Il sait que JSON ne représente pas nativement les dates, BigInt, undefined ou Decimal sans convention. Il documente les formats : dates ISO 8601, montants en centimes, IDs en string si nécessaire.</p>",errors:"<p><strong>Pattern 1 — Content-Type oublié :</strong> le serveur ne parse pas le body correctement.</p><p><strong>Pattern 2 — Dates ambiguës :</strong> timezone implicite, formats mélangés.</p><p><strong>Pattern 3 — Montants en float :</strong> erreurs d'arrondi sur l'argent.</p>",invariants:"<p>Un format de données est un contrat. Les deux côtés doivent partager les mêmes conventions pour types, nullabilité, dates, erreurs et précision numérique. Ce qui change : JSON ou autre. Ce qui ne change pas : le contrat doit être explicite.</p>",practice:{commands:[{type:"cmd",value:"Content-Type: application/json"},{type:"cmd",value:"Accept: application/json"},{type:"cmd",value:"const data = await response.json()"},{type:"cmd",value:"return res.json({ data: user })"},{type:"cmd",value:'return {"data": user}  # FastAPI'}],debt:"Formats JSON implicites → clients cassés au moindre changement. Documenter nullabilité, dates et enveloppes de réponse."}}},status:{id:"status",label:"Status Codes",icon:"200",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Une réponse HTTP ne contient pas seulement des données : elle contient aussi un statut. Le status code est le résumé machine-readable de ce qui s'est passé. Sans status codes cohérents, le client doit lire le texte de la réponse pour comprendre si l'opération a réussi ou échoué — fragile et non standard.</p>",system:"<p>Les routes choisissent le status code en fonction du résultat. Les erreurs métier sont traduites en 4xx, les erreurs inattendues en 5xx. Le client utilise ces codes pour afficher les bons messages, déclencher une redirection, retenter une requête, ou invalider une session.</p>",choice:{kind:"structured",main:"<p>Les codes essentiels suffisent dans 95% des cas : 200 OK, 201 Created, 204 No Content, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict, 422 Unprocessable Entity, 500 Internal Server Error.</p>",alternatives:[{name:"2xx",description:"Succès : la requête a été comprise et traitée."},{name:"4xx",description:"Erreur côté client : input, auth, ressource absente."},{name:"5xx",description:"Erreur côté serveur : bug ou dépendance indisponible."}]},senior:"<p>Il ne retourne pas 200 pour une erreur métier. Il distingue 401 (pas authentifié) et 403 (authentifié mais pas autorisé). Il utilise 409 pour conflit métier, comme email déjà utilisé. Il garde une forme d'erreur stable : code interne, message, détails éventuels.</p>",errors:"<p><strong>Pattern 1 — Tout en 200 :</strong> le client ne peut pas distinguer succès et échec proprement.</p><p><strong>Pattern 2 — 500 pour erreurs utilisateur :</strong> validation invalide ou ressource absente traitée comme bug serveur.</p><p><strong>Pattern 3 — Messages sans code interne :</strong> impossible pour le frontend de réagir autrement qu'en affichant du texte.</p>",invariants:"<p>Le status code est une partie du contrat d'API. Il doit être cohérent, documenté, et utilisable par des machines. Ce qui change : le framework. Ce qui ne change pas : succès, erreur client et erreur serveur ne doivent jamais être confondus.</p>",practice:{commands:[{type:"cmd",value:"200 OK                 # lecture ou action réussie"},{type:"cmd",value:"201 Created            # ressource créée"},{type:"cmd",value:"400 Bad Request        # requête invalide"},{type:"cmd",value:"401 Unauthorized       # non authentifié"},{type:"cmd",value:"403 Forbidden          # non autorisé"},{type:"cmd",value:"404 Not Found          # ressource absente"},{type:"cmd",value:"409 Conflict           # conflit métier"},{type:"cmd",value:"500 Internal Error     # erreur inattendue"}],debt:"Status codes incohérents → frontend rempli de conditions fragiles. Définir une table d'erreurs API."}}},client:{id:"client",label:"fetch / axios",icon:"↗",kind:"tool",osLabel:"JavaScript / Python",sections:{why:"<p>Un client API transforme une intention locale en requête réseau. Au lieu d'écrire toute la mécanique HTTP à chaque fois, il centralise l'URL de base, les headers, l'authentification, le parsing JSON, les timeouts, et la gestion d'erreur. Sans client centralisé, chaque appel API réinvente le même code avec des variantes.</p>",system:"<p>Côté frontend, le client API est appelé par les hooks ou services de données. Côté backend, il peut appeler une API externe. Il se situe à la frontière réseau sortante. Il ne doit pas contenir de logique métier complexe : il envoie, reçoit, normalise les erreurs.</p>",choice:{kind:"structured",main:"<p>JavaScript : <code>fetch</code> est natif et suffisant, axios ajoute interceptors, timeout ergonomique, parsing automatique. Python : <code>requests</code> pour synchrone, <code>httpx</code> pour async moderne. Le choix dépend surtout du besoin d'interceptors, async et timeouts.</p>",alternatives:[{name:"fetch",description:"Natif navigateur/Node moderne, simple."},{name:"axios",description:"Interceptors et ergonomie riche côté JS."},{name:"httpx",description:"Client HTTP Python moderne, sync et async."}]},senior:"<p>Il crée un client unique avec base URL, timeout, headers, auth et gestion des erreurs. Il ne met pas <code>fetch('/api/...')</code> dispersé dans tous les composants. Il distingue erreur HTTP (réponse 4xx/5xx) et erreur réseau (pas de réponse du tout).</p>",errors:"<p><strong>Pattern 1 — Appels API dispersés :</strong> headers et gestion d'erreurs incohérents.</p><p><strong>Pattern 2 — Pas de timeout :</strong> requêtes suspendues indéfiniment.</p><p><strong>Pattern 3 — Supposer que fetch throw sur 404 :</strong> fetch ne throw pas sur status HTTP non-2xx.</p>",invariants:"<p>Tout appel réseau peut échouer, être lent, ou retourner une réponse inattendue. Le client API doit rendre ces échecs explicites et cohérents. Ce qui change : fetch, axios, httpx. Ce qui ne change pas : centraliser la frontière réseau évite la duplication et les bugs.</p>",practice:{commands:[{type:"comment",value:"JavaScript fetch"},{type:"cmd",value:"const res = await fetch('/api/v1/users')"},{type:"cmd",value:"if (!res.ok) throw new ApiError(res.status)"},{type:"cmd",value:"const data = await res.json()"},{type:"comment",value:"Axios"},{type:"cmd",value:"const api = axios.create({ baseURL: '/api/v1', timeout: 10000 })"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install httpx"},{type:"cmd",value:"async with httpx.AsyncClient(timeout=10) as client:"}],debt:"Client API non centralisé → auth, erreurs et timeouts incohérents. Créer un module apiClient dès les premiers appels."}}},auth:{id:"auth",label:"Auth",icon:"🔐",kind:"infra",osLabel:"Universel",sections:{why:`<p>Une API doit savoir qui fait la requête et ce que cette personne a le droit de faire. L'authentification répond à "qui es-tu ?", l'autorisation répond à "as-tu le droit ?". Sans auth, toutes les ressources sont publiques ou protégées par des suppositions fragiles côté client.</p>`,system:"<p>L'auth traverse plusieurs couches : login route, service d'identité, token/session, middleware d'auth, routes protégées, frontend qui stocke ou transporte le credential. Elle s'appuie souvent sur le header <code>Authorization</code> ou sur des cookies sécurisés.</p>",choice:{kind:"structured",main:"<p>Deux grandes approches web : cookies httpOnly avec session/JWT, ou token Bearer dans Authorization. Cookies httpOnly protègent mieux contre le vol par XSS. Bearer token est simple pour API/mobile mais exige une stratégie de stockage prudente.</p>",alternatives:[{name:"Cookie httpOnly",description:"Bon défaut web, non lisible par JavaScript."},{name:"Bearer JWT",description:"Simple pour APIs, mobile, clients externes."},{name:"OAuth/OIDC",description:"Délégation d'identité via fournisseur externe."}]},senior:"<p>Il sépare login, authentification et autorisation. Il ne fait pas confiance au frontend pour cacher les boutons : le backend vérifie toujours les droits. Il pense expiration, refresh token, révocation, rotation, CSRF si cookies, XSS si stockage côté client.</p>",errors:"<p><strong>Pattern 1 — Auth côté frontend seulement :</strong> l'API reste appelable directement.</p><p><strong>Pattern 2 — Token dans localStorage sans réflexion :</strong> exposition en cas de XSS.</p><p><strong>Pattern 3 — Confondre 401 et 403 :</strong> non authentifié vs non autorisé.</p>",invariants:"<p>L'identité et les droits doivent être vérifiés côté serveur à chaque requête protégée. Ce qui change : session, JWT, OAuth. Ce qui ne change pas : le client n'est jamais une source de confiance.</p>",practice:{commands:[{type:"cmd",value:"Authorization: Bearer <token>"},{type:"cmd",value:"Set-Cookie: session=...; HttpOnly; Secure; SameSite=Lax"},{type:"cmd",value:"401 Unauthorized  # pas connecté"},{type:"cmd",value:"403 Forbidden     # connecté mais pas autorisé"},{type:"comment",value:"Middleware"},{type:"cmd",value:"req.user = verifyToken(token)"},{type:"cmd",value:"current_user = Depends(get_current_user)"}],debt:"Auth sans modèle de menace → failles XSS/CSRF ou droits contournables. Documenter où vit le credential et qui vérifie les droits."}}},cors:{id:"cors",label:"CORS",icon:"🌐",kind:"infra",osLabel:"Frontend / Backend",sections:{why:"<p>Le navigateur protège l'utilisateur : une page ouverte sur un domaine ne peut pas appeler librement n'importe quelle API d'un autre domaine. CORS est le mécanisme qui permet au serveur de déclarer quels origins ont le droit de l'appeler depuis un navigateur. Ce n'est pas une protection backend absolue : c'est une règle de navigateur.</p>",system:"<p>CORS intervient avant que le frontend puisse lire la réponse. Le navigateur envoie parfois une requête preflight <code>OPTIONS</code> pour demander au serveur si la vraie requête est autorisée. Le backend répond avec des headers comme <code>Access-Control-Allow-Origin</code>.</p>",choice:{kind:"structured",main:"<p>En développement, on peut autoriser <code>http://localhost:5173</code>. En production, on autorise uniquement les domaines connus. Éviter <code>*</code> avec credentials. Une autre stratégie locale est le proxy du dev server, qui évite CORS en faisant passer les appels par la même origine.</p>",alternatives:[{name:"Allowlist stricte",description:"Origines explicitement autorisées."},{name:"Proxy dev server",description:"Évite CORS en local via Vite/Next."},{name:"Wildcard",description:"Uniquement pour APIs publiques sans credentials."}]},senior:`<p>Il sait que "corriger CORS" ne veut pas dire désactiver la sécurité. Il identifie l'origin réel, les headers envoyés, la méthode, et si credentials sont inclus. Il configure CORS côté serveur, pas côté client.</p>`,errors:"<p><strong>Pattern 1 — Mettre * partout :</strong> dangereux ou incompatible avec credentials.</p><p><strong>Pattern 2 — Chercher côté frontend :</strong> CORS se décide par les headers du serveur.</p><p><strong>Pattern 3 — Oublier OPTIONS :</strong> preflight bloqué avant la vraie requête.</p>",invariants:"<p>CORS est une politique de navigateur entre origins. Ce qui change : Express, FastAPI, Nginx. Ce qui ne change pas : le serveur doit déclarer explicitement qui peut l'appeler depuis un navigateur.</p>",practice:{commands:[{type:"comment",value:"Express"},{type:"cmd",value:"app.use(cors({ origin: process.env.CORS_ORIGIN, credentials: true }))"},{type:"comment",value:"FastAPI"},{type:"cmd",value:"app.add_middleware(CORSMiddleware, allow_origins=[settings.frontend_url])"},{type:"comment",value:"Headers"},{type:"cmd",value:"Access-Control-Allow-Origin: http://localhost:5173"}],debt:"CORS ouvert trop largement → surface d'abus. CORS mal compris → heures perdues côté frontend."}}},network:{id:"network",label:"Erreurs réseau",icon:"⚠",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Le réseau est incertain par nature : serveur down, DNS cassé, timeout, offline, CORS bloqué, proxy indisponible, latence. Une application qui suppose que le réseau marche toujours est fragile. Les erreurs réseau existent comme catégorie distincte des erreurs métier : parfois il n'y a même pas de réponse HTTP.</p>",system:"<p>Les erreurs réseau apparaissent côté client API, dev server, navigateur, ou backend appelant un service externe. Elles doivent être transformées en états UI ou réponses contrôlées : loading, retry, message utilisateur, fallback, log technique.</p>",choice:{kind:"structured",main:"<p>La stratégie dépend du contexte : retry pour erreurs temporaires, timeout pour ne pas attendre indéfiniment, message clair pour l'utilisateur, circuit breaker pour services externes critiques. Toutes les requêtes ne doivent pas être retry : un POST de paiement répété peut créer un doublon sans idempotency key.</p>",alternatives:[{name:"Timeout",description:"Aucune requête ne doit attendre pour toujours."},{name:"Retry",description:"Utile pour erreurs temporaires et requêtes idempotentes."},{name:"Fallback",description:"Dégradation contrôlée si un service est indisponible."}]},senior:"<p>Il distingue erreur HTTP, erreur réseau, timeout, et erreur de parsing. Il utilise des idempotency keys pour les opérations critiques répétables. Il logue requestId/correlationId pour relier client, backend et service externe.</p>",errors:`<p><strong>Pattern 1 — Catch générique :</strong> afficher "une erreur est survenue" sans contexte exploitable.</p><p><strong>Pattern 2 — Retry aveugle :</strong> répéter des POST non idempotents.</p><p><strong>Pattern 3 — Pas d'état loading/error :</strong> UI bloquée sans explication.</p>`,invariants:"<p>Tout appel réseau est faillible. Une application robuste traite l'échec comme un chemin normal, pas comme une exception rare. Ce qui change : outil et framework. Ce qui ne change pas : timeout, retry raisonné, logs et feedback utilisateur.</p>",practice:{commands:[{type:"cmd",value:"AbortController  # timeout fetch côté JS"},{type:"cmd",value:"axios.create({ timeout: 10000 })"},{type:"cmd",value:"httpx.AsyncClient(timeout=10)"},{type:"cmd",value:"Idempotency-Key: <uuid>"},{type:"cmd",value:"X-Request-ID: <uuid>"},{type:"comment",value:"Tester : couper le backend puis vérifier l'état d'erreur UI"}],debt:"Erreurs réseau non modélisées → UI fragile, doubles actions, bugs impossibles à corréler."}}}},maps:e(u)},p={id:"frontend-et-etat",part:"T",number:8,title:"Frontend et État",subtitle:"Organiser l'interface, la navigation et les données côté client",badge:"Fiche T08 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds · frontend","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte frontend pour comprendre composants, routing, state local, state serveur, formulaires, effets et accessibilité.",accent:"tool",tabs:[{id:"frontend",label:"Frontend"}],nodes:{composants:{id:"composants",label:"Composants",icon:"◫",kind:"tool",osLabel:"Frontend",sections:{why:"<p>Une interface sans composants devient un bloc de JSX/HTML ingérable. Les composants découpent l'UI en unités autonomes, réutilisables et compréhensibles. Ils jouent côté frontend le même rôle que les modules et services côté backend : séparer les responsabilités.</p>",system:"<p>Les composants forment un arbre : App, layouts, pages, features, composants UI. Les données descendent via props, les événements remontent via callbacks, et les hooks isolent la logique réutilisable.</p>",choice:{kind:"structured",main:"<p>Découpe par responsabilité : UI générique, composants de feature, pages. Un bloc mérite un composant s'il est réutilisé, s'il porte une logique propre, ou s'il devient trop complexe pour rester inline.</p>",alternatives:[{name:"UI",description:"Button, Input, Modal : sans logique métier."},{name:"Feature",description:"UserCard, ProductList : logique du domaine."},{name:"Page",description:"Assemblage correspondant à une route."}]},senior:"<p>Il sépare composants intelligents et composants de présentation. Il extrait les effets et appels API dans des hooks. Il garde les props explicites et évite de connecter toute l'application à un store global inutile.</p>",errors:"<p><strong>Pattern 1 — Composant monolithique :</strong> 500 lignes qui font tout.</p><p><strong>Pattern 2 — Props floues :</strong> objet énorme passé partout.</p><p><strong>Pattern 3 — Logique métier dans le rendu :</strong> JSX illisible et non testable.</p>",invariants:"<p>Un composant fait une chose et expose une interface claire. Ce principe vaut en React, Vue, Svelte ou autre.</p>",practice:{commands:[{type:"cmd",value:"src/components/ui/Button.jsx"},{type:"cmd",value:"src/features/users/UserCard.jsx"},{type:"cmd",value:"src/features/users/useUsers.js"},{type:"cmd",value:"src/pages/UsersPage.jsx"}],debt:"Composants trop gros → réutilisation impossible et tests pénibles."}}},routing:{id:"routing",label:"Routing",icon:"⇒",kind:"infra",osLabel:"Frontend",sections:{why:"<p>Une interface multi-écrans doit associer une URL à un état de l'application. Le routing frontend permet de naviguer sans recharger toute la page, de partager des liens, et de restaurer une vue depuis l'URL.</p>",system:"<p>Le routeur se situe au-dessus des pages. Il lit l'URL, choisit le composant de page, gère les paramètres, les layouts, parfois les loaders et redirections. Il relie l'expérience utilisateur à une structure navigable.</p>",choice:{kind:"structured",main:"<p>React Router est le standard React. Next.js utilise un routing par fichiers. TanStack Router apporte typage fort. La règle : l'URL doit porter ce qui est partageable, pas seulement le state interne.</p>",alternatives:[{name:"React Router",description:"Standard SPA React."},{name:"File-based routing",description:"Next, Remix : structure de fichiers = routes."},{name:"TanStack Router",description:"Routing typé et moderne."}]},senior:"<p>Il met les filtres et IDs importants dans l'URL. Il protège les routes côté UI, mais sait que la vraie sécurité reste côté backend. Il prévoit pages 404, loading, error boundary et navigation accessible.</p>",errors:"<p><strong>Pattern 1 — State non partageable :</strong> filtres uniquement en mémoire, impossible de copier l'URL.</p><p><strong>Pattern 2 — Auth frontend seule :</strong> route cachée mais API ouverte.</p><p><strong>Pattern 3 — Pas de fallback :</strong> URL inconnue = écran vide.</p>",invariants:"<p>Une route est un contrat de navigation. Elle doit être lisible, stable et restaurable.</p>",practice:{commands:[{type:"cmd",value:"npm install react-router-dom"},{type:"cmd",value:'<Route path="/users/:id" element={<UserPage />} />'},{type:"cmd",value:"const { id } = useParams()"},{type:"cmd",value:"useSearchParams()"}],debt:"URL qui ne reflète pas l'état partageable → navigation fragile et UX frustrante."}}},"state-local":{id:"state-local",label:"State local",icon:"x=",kind:"runtime",osLabel:"Frontend",sections:{why:"<p>L'interface a besoin de mémoire courte : menu ouvert, champ en cours d'édition, onglet sélectionné, modale visible. Le state local garde cette information au plus près du composant qui l'utilise.</p>",system:"<p>Le state local vit dans un composant ou un hook. Il ne doit pas remonter plus haut que nécessaire. Plus un état est haut dans l'arbre, plus il peut provoquer de complexité et de rendus inutiles.</p>",choice:{kind:"structured",main:"<p><code>useState</code> pour valeurs simples, <code>useReducer</code> quand les transitions deviennent nombreuses. Ne pas sortir vers Context ou Zustand tant que l'état n'est pas réellement partagé.</p>",alternatives:[{name:"useState",description:"Simple et local."},{name:"useReducer",description:"Transitions explicites pour état complexe."},{name:"State global",description:"Seulement si plusieurs zones en dépendent."}]},senior:"<p>Il identifie la source de vérité. Il évite de dupliquer la même donnée dans plusieurs states. Il dérive ce qui peut être calculé au rendu au lieu de le stocker.</p>",errors:"<p><strong>Pattern 1 — State dupliqué :</strong> deux valeurs censées représenter la même chose divergent.</p><p><strong>Pattern 2 — Tout remonter :</strong> parent énorme qui contrôle toute l'UI.</p><p><strong>Pattern 3 — Stocker du dérivable :</strong> bugs de synchronisation inutiles.</p>",invariants:"<p>Un état a une source de vérité et une portée minimale. Ce principe est la base de toute UI maintenable.</p>",practice:{commands:[{type:"cmd",value:"const [isOpen, setIsOpen] = useState(false)"},{type:"cmd",value:"const [selectedTab, setSelectedTab] = useState('details')"},{type:"cmd",value:"const visibleItems = items.filter(...)"}],debt:"State local mal placé → props drilling, rerenders et bugs de synchronisation."}}},"state-serveur":{id:"state-serveur",label:"State serveur",icon:"⇄",kind:"tool",osLabel:"Frontend",sections:{why:"<p>Les données venant de l'API ne sont pas un state local classique. Elles ont loading, error, cache, stale time, retry, invalidation. Réimplémenter ça à la main dans chaque composant produit vite du code fragile.</p>",system:"<p>Le state serveur se situe entre les composants et le client API. React Query/SWR gèrent le cache, les requêtes, les erreurs et l'invalidation après mutation.</p>",choice:{kind:"structured",main:"<p>React Query est le défaut robuste pour applications React. SWR est plus minimaliste. Fetch manuel suffit pour une page simple, mais devient coûteux dès que les données sont partagées ou mutées.</p>",alternatives:[{name:"React Query",description:"Cache, mutations, invalidation, retry."},{name:"SWR",description:"Simple et léger."},{name:"fetch manuel",description:"OK pour prototype très simple."}]},senior:"<p>Il invalide les bonnes queries après mutation. Il évite de copier les données serveur dans un store global. Il distingue données fraîches, stale et loading initial.</p>",errors:"<p><strong>Pattern 1 — Cache jamais invalidé :</strong> UI affiche des données anciennes.</p><p><strong>Pattern 2 — Copier server state dans Zustand :</strong> double source de vérité.</p><p><strong>Pattern 3 — Loading incohérent :</strong> chaque composant invente ses états.</p>",invariants:"<p>Le serveur est la source de vérité des données persistantes. Le frontend n'en possède qu'une copie temporaire.</p>",practice:{commands:[{type:"cmd",value:"npm install @tanstack/react-query"},{type:"cmd",value:"useQuery({ queryKey: ['users'], queryFn: fetchUsers })"},{type:"cmd",value:"queryClient.invalidateQueries({ queryKey: ['users'] })"}],debt:"Server state manuel partout → bugs de cache et états UI incohérents."}}},forms:{id:"forms",label:"Formulaires",icon:"▤",kind:"tool",osLabel:"Frontend",sections:{why:"<p>Les formulaires sont la principale frontière d'entrée utilisateur. Ils collectent des données imparfaites, les valident, affichent des erreurs et déclenchent des mutations. Sans structure, ils deviennent vite le code le plus fragile de l'interface.</p>",system:"<p>Un formulaire relie state local, validation frontend, API, erreurs backend et feedback utilisateur. Il ne remplace jamais la validation backend, mais améliore l'expérience en donnant un retour immédiat.</p>",choice:{kind:"structured",main:"<p>Formulaire simple : state local. Formulaire complexe : React Hook Form + Zod. La validation frontend doit idéalement partager les mêmes règles que l'API ou rester alignée avec elle.</p>",alternatives:[{name:"State local",description:"Suffisant pour deux ou trois champs."},{name:"React Hook Form",description:"Performant pour formulaires complexes."},{name:"Zod",description:"Schéma partagé et typé."}]},senior:"<p>Il gère loading, disabled, erreurs champ par champ, erreur globale, succès et reset. Il évite les doubles soumissions et garde les messages d'erreur utiles.</p>",errors:"<p><strong>Pattern 1 — Double submit :</strong> deux requêtes créent deux ressources.</p><p><strong>Pattern 2 — Erreurs backend perdues :</strong> l'utilisateur ne sait pas quoi corriger.</p><p><strong>Pattern 3 — Validation frontend seule :</strong> sécurité inexistante.</p>",invariants:"<p>Une donnée utilisateur est non fiable jusqu'à validation backend. Le frontend améliore l'UX, le backend garantit l'intégrité.</p>",practice:{commands:[{type:"cmd",value:"npm install react-hook-form zod @hookform/resolvers"},{type:"cmd",value:"const form = useForm({ resolver: zodResolver(schema) })"},{type:"cmd",value:"disabled={mutation.isPending}"}],debt:"Formulaires sans stratégie d'erreurs → UX confuse et données invalides."}}},effects:{id:"effects",label:"Effets",icon:"↻",kind:"infra",osLabel:"Frontend",sections:{why:"<p>Un composant pur calcule son affichage depuis ses props et son state. Mais certaines actions touchent le monde extérieur : requête réseau, abonnement, timer, stockage local, titre de page. Les effets existent pour gérer ces synchronisations avec l'extérieur.</p>",system:"<p>Les effets vivent après le rendu. Ils synchronisent le composant avec un système externe. Ils ne doivent pas servir à recalculer ce qui peut être dérivé directement pendant le rendu.</p>",choice:{kind:"structured",main:"<p>Dans React, <code>useEffect</code> est nécessaire pour synchroniser avec l'extérieur. Mais beaucoup d'effets sont évitables : data fetching avec React Query, calculs dérivés dans le rendu, événements dans les handlers.</p>",alternatives:[{name:"useEffect",description:"Synchronisation avec système externe."},{name:"Event handler",description:"Action directe suite à interaction."},{name:"Query library",description:"Évite les effets manuels de fetching."}]},senior:"<p>Il réduit les effets au minimum. Il nettoie abonnements et timers. Il comprend les dépendances du tableau et évite de les manipuler au hasard pour faire taire le linter.</p>",errors:"<p><strong>Pattern 1 — Effet de synchronisation interne :</strong> state dérivé inutile.</p><p><strong>Pattern 2 — Dépendances menties :</strong> stale closures et bugs subtils.</p><p><strong>Pattern 3 — Cleanup oublié :</strong> memory leaks, timers multiples.</p>",invariants:"<p>Un effet est une synchronisation avec l'extérieur. S'il n'y a pas d'extérieur, il faut probablement supprimer l'effet.</p>",practice:{commands:[{type:"cmd",value:"useEffect(() => { document.title = title }, [title])"},{type:"cmd",value:"return () => clearInterval(timer)"},{type:"cmd",value:"Ne pas ignorer react-hooks/exhaustive-deps"}],debt:"Effets mal maîtrisés → bugs temporels, appels API en boucle, memory leaks."}}},accessibilite:{id:"accessibilite",label:"Accessibilité",icon:"♿",kind:"runtime",osLabel:"Frontend",sections:{why:"<p>Une interface n'est pas seulement visuelle. Elle doit être utilisable au clavier, lisible par lecteur d'écran, compréhensible avec des contrastes corrects, et robuste pour différents utilisateurs. L'accessibilité n'est pas une couche décorative : c'est une condition d'usage.</p>",system:"<p>L'accessibilité traverse composants, formulaires, routing et état. Les boutons doivent être de vrais boutons, les inputs avoir des labels, les erreurs être annoncées, le focus être géré lors des changements de route ou modales.</p>",choice:{kind:"structured",main:"<p>Le meilleur choix est d'utiliser les éléments HTML natifs quand ils existent. Un <code>button</code> accessible vaut mieux qu'une div cliquable. Les composants custom doivent reproduire clavier, focus et rôles ARIA seulement quand nécessaire.</p>",alternatives:[{name:"HTML natif",description:"Premier choix, robuste par défaut."},{name:"ARIA ciblé",description:"Quand le natif ne suffit pas."},{name:"Lib UI accessible",description:"Radix, React Aria, Headless UI."}]},senior:"<p>Il teste au clavier. Il vérifie labels, focus visible, contrastes, ordre de tabulation et messages d'erreur. Il ne remplace pas la sémantique par des divs stylées.</p>",errors:"<p><strong>Pattern 1 — Div cliquable :</strong> inaccessible au clavier.</p><p><strong>Pattern 2 — Input sans label :</strong> lecteur d'écran inutile.</p><p><strong>Pattern 3 — Focus perdu :</strong> modales et routes désorientent l'utilisateur.</p>",invariants:"<p>Une UI professionnelle doit être utilisable sans souris et compréhensible par technologies d'assistance. C'est un critère de qualité, pas un bonus.</p>",practice:{commands:[{type:"cmd",value:'<button type="button">Enregistrer</button>'},{type:"cmd",value:'<label htmlFor="email">Email</label>'},{type:"cmd",value:'<input id="email" aria-describedby="email-error" />'},{type:"cmd",value:"Tester Tab / Enter / Escape"}],debt:"Accessibilité ignorée → UI fragile, non inclusive, souvent moins robuste pour tout le monde."}}}},maps:{frontend:{viewBox:"0 0 920 300",nodes:[{id:"composants",x:20,y:115,w:120,h:65},{id:"routing",x:190,y:55,w:110,h:65},{id:"state-local",x:190,y:175,w:120,h:65},{id:"state-serveur",x:360,y:115,w:130,h:65},{id:"forms",x:550,y:55,w:110,h:65},{id:"effects",x:550,y:175,w:110,h:65},{id:"accessibilite",x:720,y:115,w:130,h:65}],edges:[{x1:140,y1:135,x2:188,y2:88},{x1:140,y1:160,x2:188,y2:207},{x1:300,y1:88,x2:358,y2:135},{x1:310,y1:207,x2:358,y2:160},{x1:490,y1:135,x2:548,y2:88},{x1:490,y1:160,x2:548,y2:207},{x1:660,y1:88,x2:718,y2:135},{x1:660,y1:207,x2:718,y2:160}]}}},d={viewBox:"0 0 900 300",nodes:[{id:"unitaires",x:20,y:115,w:110,h:65},{id:"integration",x:180,y:55,w:120,h:65},{id:"e2e",x:180,y:175,w:100,h:65},{id:"mocks",x:350,y:55,w:110,h:65},{id:"fixtures",x:350,y:175,w:110,h:65},{id:"coverage",x:520,y:115,w:120,h:65},{id:"ci",x:700,y:115,w:100,h:65}],edges:[{x1:130,y1:135,x2:178,y2:88},{x1:130,y1:160,x2:178,y2:207},{x1:300,y1:88,x2:348,y2:88},{x1:280,y1:207,x2:348,y2:207},{x1:460,y1:88,x2:518,y2:135},{x1:460,y1:207,x2:518,y2:160},{x1:640,y1:147,x2:698,y2:147}]},m={id:"tests",part:"T",number:9,title:"Tests",subtitle:"Transformer la confiance en preuve exécutable",badge:"Fiche T09 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds · 2 types","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte pour comprendre la stratégie de test : unitaires, intégration, E2E, mocks, fixtures, couverture et CI.",accent:"runtime",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{unitaires:{id:"unitaires",label:"Unitaires",icon:"①",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Un test unitaire vérifie une petite unité de comportement isolée : une fonction, une méthode, un service sans dépendances réelles. Il existe pour détecter vite les régressions sur la logique pure. Sans tests unitaires, chaque refactoring devient risqué parce qu'on ne sait pas si le comportement attendu est encore respecté.</p>",system:"<p>Les tests unitaires se placent au plus près de la logique métier : services, utilitaires, fonctions de calcul, validation. Ils ne démarrent pas de serveur, n'appellent pas de vraie base, ne dépendent pas du réseau. Ils doivent être rapides, nombreux, et lancés très souvent.</p>",choice:{kind:"structured",main:"<p>JavaScript : Vitest est recommandé pour projets modernes, Jest reste très répandu. Python : pytest est le standard. Le vrai choix n'est pas l'outil, mais ce qu'on teste : comportement observable, pas implémentation interne.</p>",alternatives:[{name:"Vitest / Jest",description:"Runner, assertions, mocks et coverage côté JavaScript."},{name:"pytest",description:"Standard Python, simple et extensible."},{name:"unittest",description:"Inclus dans Python, plus verbeux."}]},senior:"<p>Il suit AAA : Arrange, Act, Assert. Il teste les cas normaux, les cas limites, et les erreurs attendues. Il donne aux tests des noms qui décrivent le comportement métier. Un test doit expliquer ce que le code garantit, pas répéter le nom de la fonction.</p>",errors:`<p><strong>Pattern 1 — Tester l'implémentation :</strong> le test casse au moindre refactoring même si le comportement est identique.</p><p><strong>Pattern 2 — Tests trop larges :</strong> un test unitaire démarre la base, le serveur et le réseau — ce n'est plus unitaire.</p><p><strong>Pattern 3 — Assertions faibles :</strong> tester seulement que "ça ne plante pas".</p>`,invariants:"<p>Un test unitaire doit être rapide, déterministe, isolé, et lisible. Ce qui change : framework et syntaxe. Ce qui ne change pas : il prouve une règle de comportement précise.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"npm install --save-dev vitest"},{type:"cmd",value:"expect(calculateTotal([])).toBe(0)"},{type:"cmd",value:"npx vitest"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install pytest"},{type:"cmd",value:"assert calculate_total([]) == 0"},{type:"cmd",value:"pytest tests/unit/"}],debt:"Logique métier sans tests unitaires → refactoring dangereux et bugs qui reviennent."}}},integration:{id:"integration",label:"Intégration",icon:"⇆",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Des unités correctes peuvent mal fonctionner ensemble. Un service peut appeler le mauvais repository, une route peut mal valider les données, une transaction peut échouer. Les tests d'intégration existent pour vérifier que plusieurs couches collaborent correctement.</p>",system:"<p>Ils se placent entre unitaires et E2E. Ils testent route + validation + service, service + repository, ou repository + base de test. Ils utilisent parfois une vraie base locale ou éphémère, mais évitent de passer par toute l'interface utilisateur.</p>",choice:{kind:"structured",main:"<p>La décision centrale : quelles dépendances réelles garder ? Pour tester une API, garder l'application réelle mais utiliser une base de test. Pour tester un service, mocker l'email externe mais garder le repository si l'accès aux données est critique.</p>",alternatives:[{name:"API integration",description:"Tester les endpoints sans navigateur."},{name:"DB integration",description:"Tester repositories et migrations sur vraie base de test."},{name:"Contract integration",description:"Vérifier qu'un client et une API respectent le même contrat."}]},senior:"<p>Il isole les données de test. Chaque test doit pouvoir tourner seul ou dans n'importe quel ordre. Il réinitialise la base entre tests ou utilise des transactions rollback. Il évite que les tests d'intégration deviennent une simulation E2E lente et fragile.</p>",errors:"<p><strong>Pattern 1 — Base partagée sale :</strong> les tests dépendent de données laissées par d'autres tests.</p><p><strong>Pattern 2 — Trop de mocks :</strong> le test ne teste plus l'intégration réelle.</p><p><strong>Pattern 3 — Trop large :</strong> chaque test démarre toute l'application et devient lent.</p>",invariants:"<p>Un test d'intégration vérifie un contrat entre couches. Il doit garder assez de réalité pour être utile, mais assez de contrôle pour rester fiable.</p>",practice:{commands:[{type:"comment",value:"JavaScript API"},{type:"cmd",value:"npm install --save-dev supertest"},{type:"cmd",value:"await request(app).post('/api/v1/users').send(payload).expect(201)"},{type:"comment",value:"Python FastAPI"},{type:"cmd",value:"from fastapi.testclient import TestClient"},{type:"cmd",value:"client.post('/api/v1/users', json=payload)"},{type:"comment",value:"Base de test"},{type:"cmd",value:"DATABASE_URL=postgresql://localhost/app_test"}],debt:"Tests d'intégration sans isolation des données → faux échecs et confiance détruite."}}},e2e:{id:"e2e",label:"E2E",icon:"🌐",kind:"tool",osLabel:"Universel",sections:{why:"<p>Les tests unitaires et d'intégration prouvent des morceaux du système. Les tests end-to-end prouvent qu'un vrai parcours utilisateur fonctionne de bout en bout : ouvrir l'app, remplir un formulaire, cliquer, appeler l'API, persister en base, afficher le résultat.</p>",system:"<p>Les E2E se placent au sommet de la pyramide de tests. Ils démarrent l'application comme un utilisateur réel la voit. Ils sont précieux mais coûteux : plus lents, plus fragiles, plus dépendants de l'environnement.</p>",choice:{kind:"structured",main:"<p>JavaScript/frontend : Playwright est le choix moderne, Cypress reste répandu. Backend pur : les E2E peuvent être des tests API complets plutôt que navigateur. Python peut aussi piloter Playwright via son binding officiel.</p>",alternatives:[{name:"Playwright",description:"Moderne, multi-navigateurs, robuste."},{name:"Cypress",description:"Très utilisé côté frontend, excellent DX."},{name:"API E2E",description:"Parcours complet sans navigateur pour backend."}]},senior:"<p>Il teste peu de parcours E2E, mais les plus critiques : login, paiement, création d'une ressource, workflow principal. Il évite de tester tous les cas limites en E2E : ils appartiennent aux unitaires/intégration. Il rend les sélecteurs stables avec <code>data-testid</code> ou rôles accessibles.</p>",errors:"<p><strong>Pattern 1 — Trop d'E2E :</strong> suite lente, fragile, ignorée par l'équipe.</p><p><strong>Pattern 2 — Sélecteurs CSS fragiles :</strong> changement visuel = tests cassés.</p><p><strong>Pattern 3 — Dépendance à des services externes :</strong> paiement ou email réel dans les tests.</p>",invariants:"<p>Un E2E valide un parcours métier critique. Il ne remplace pas les tests plus bas niveau. Ce qui change : l'outil. Ce qui ne change pas : peu d'E2E, mais très significatifs.</p>",practice:{commands:[{type:"comment",value:"Playwright JS"},{type:"cmd",value:"npm init playwright@latest"},{type:"cmd",value:"npx playwright test"},{type:"cmd",value:"await page.getByRole('button', { name: 'Connexion' }).click()"},{type:"comment",value:"Playwright Python"},{type:"cmd",value:"pip install pytest-playwright"},{type:"cmd",value:"playwright install"}],debt:"E2E trop nombreux ou instables → pipeline lent et contourné. Garder les E2E pour les chemins critiques."}}},mocks:{id:"mocks",label:"Mocks",icon:"🎭",kind:"infra",osLabel:"Universel",sections:{why:"<p>Tester une unité exige parfois de remplacer ses dépendances : base de données, email, paiement, API externe, horloge. Un mock est un substitut contrôlé. Il existe pour isoler le comportement testé et éviter qu'un test dépende d'un système lent, coûteux ou instable.</p>",system:"<p>Les mocks se placent aux frontières : repositories mockés pour tester un service, client HTTP mocké pour tester une intégration, email service mocké pour vérifier qu'un email aurait été envoyé. Ils doivent être utilisés pour contrôler les dépendances, pas pour mentir au test.</p>",choice:{kind:"structured",main:"<p>Mock, stub, fake, spy : les nuances comptent. Stub retourne une valeur contrôlée. Spy observe un appel. Fake implémente une version simplifiée mais fonctionnelle. Mock vérifie une interaction. Plus le mock est proche de l'implémentation interne, plus le test devient fragile.</p>",alternatives:[{name:"Stub",description:"Retourne une valeur connue."},{name:"Spy",description:"Observe qu'une fonction a été appelée."},{name:"Fake",description:"Implémentation légère, souvent plus réaliste qu'un mock."}]},senior:"<p>Il mocke les dépendances externes, pas le code qu'il veut réellement tester. Il préfère tester le résultat observable plutôt que le nombre exact d'appels internes. Il sait qu'un excès de mocks peut faire passer des tests alors que le système réel ne marche pas.</p>",errors:"<p><strong>Pattern 1 — Mocker tout :</strong> le test vérifie seulement que les mocks ont été appelés.</p><p><strong>Pattern 2 — Mock fragile :</strong> couplé aux détails internes d'une fonction.</p><p><strong>Pattern 3 — Pas de test réel complémentaire :</strong> mocks partout, aucune intégration pour vérifier les contrats.</p>",invariants:"<p>Un mock est un outil d'isolation, pas une preuve que le système complet fonctionne. Il doit rendre un test plus précis, pas plus imaginaire.</p>",practice:{commands:[{type:"comment",value:"Vitest"},{type:"cmd",value:"const repo = { findByEmail: vi.fn().mockResolvedValue(null) }"},{type:"cmd",value:"expect(repo.findByEmail).toHaveBeenCalledWith(email)"},{type:"comment",value:"pytest"},{type:"cmd",value:"from unittest.mock import Mock, AsyncMock"},{type:"cmd",value:"repo.find_by_email = AsyncMock(return_value=None)"}],debt:"Trop de mocks → tests déconnectés du réel. Ajouter des tests d'intégration pour vérifier les contrats entre couches."}}},fixtures:{id:"fixtures",label:"Fixtures",icon:"🧱",kind:"infra",osLabel:"Universel",sections:{why:"<p>Un test a besoin de données connues. Si chaque test construit ses données à la main, le bruit masque l'intention. Les fixtures fournissent des objets, utilisateurs, états de base ou fichiers de test réutilisables, cohérents et nommés.</p>",system:"<p>Les fixtures alimentent tous les niveaux : unitaires, intégration, E2E. Elles peuvent être en mémoire, en base, dans des factories, ou dans des fichiers. Elles créent un monde contrôlé dans lequel le test vérifie un comportement.</p>",choice:{kind:"structured",main:"<p>Pour petits projets : fixtures simples et factories légères. Pour projets plus gros : builders/factories comme factory_boy en Python ou fonctions factory en JS. Les fixtures doivent rester lisibles : trop de magie rend les tests opaques.</p>",alternatives:[{name:"Objet inline",description:"Simple pour un test unique."},{name:"Factory",description:"Réutilisable, personnalisable, bon défaut."},{name:"Seed DB",description:"Pour intégration/E2E avec base réelle."}]},senior:"<p>Il crée des factories avec des valeurs par défaut réalistes et surcharge seulement ce qui compte pour le test. Il évite les fixtures globales énormes que tous les tests partagent. Il nomme les fixtures selon le scénario : <code>expiredToken</code>, <code>adminUser</code>, <code>emptyCart</code>.</p>",errors:"<p><strong>Pattern 1 — Fixture géante globale :</strong> impossible de savoir quelle donnée influence quel test.</p><p><strong>Pattern 2 — Données irréalistes :</strong> tests passent avec des cas qui n'existent jamais en prod.</p><p><strong>Pattern 3 — Couplage entre tests :</strong> un test modifie une fixture utilisée par un autre.</p>",invariants:"<p>Un test doit contrôler explicitement son monde. Les données de test doivent rendre l'intention plus claire, pas la cacher.</p>",practice:{commands:[{type:"comment",value:"Factory JS"},{type:"cmd",value:"const buildUser = (overrides = {}) => ({ id: 1, email: 'a@test.com', ...overrides })"},{type:"comment",value:"pytest fixture"},{type:"cmd",value:"@pytest.fixture"},{type:"cmd",value:"def user(): return User(email='a@test.com')"},{type:"comment",value:"Usage"},{type:"cmd",value:"admin = buildUser({ role: 'admin' })"}],debt:"Fixtures globales opaques → tests difficiles à lire et à maintenir. Préférer factories explicites."}}},coverage:{id:"coverage",label:"Coverage",icon:"%",kind:"tool",osLabel:"Universel",sections:{why:"<p>La couverture mesure quelles lignes ou branches ont été exécutées par les tests. Elle ne prouve pas que les tests sont bons, mais elle révèle les zones totalement non testées. Sans coverage, on ne sait pas où les angles morts se cachent.</p>",system:"<p>Le coverage est généré par le runner de tests et souvent publié en CI. Il donne une carte de risque : fichiers critiques non couverts, branches jamais exécutées, services sans tests. Il complète la revue de code, mais ne remplace pas le jugement.</p>",choice:{kind:"structured",main:"<p>Line coverage est facile à comprendre. Branch coverage est plus utile pour vérifier les chemins conditionnels. Un seuil peut empêcher une régression massive, mais un seuil trop strict pousse à écrire des tests artificiels.</p>",alternatives:[{name:"Line coverage",description:"Pourcentage de lignes exécutées."},{name:"Branch coverage",description:"Vérifie les chemins if/else."},{name:"Mutation testing",description:"Plus avancé : vérifie si les tests détectent des mutations."}]},senior:"<p>Il utilise le coverage comme signal, pas comme objectif absolu. 80% de couverture avec de bons tests vaut mieux que 100% de tests creux. Il regarde surtout les fichiers critiques : auth, paiement, validation, services métier.</p>",errors:"<p><strong>Pattern 1 — Chasser le 100% :</strong> tests inutiles écrits pour satisfaire un chiffre.</p><p><strong>Pattern 2 — Ignorer les branches :</strong> happy path couvert, erreurs non testées.</p><p><strong>Pattern 3 — Seuil global trompeur :</strong> fichiers critiques non couverts cachés par fichiers simples très couverts.</p>",invariants:"<p>Ce qui n'est jamais exécuté par les tests est un risque inconnu. Le coverage révèle ce risque, mais la qualité des assertions détermine la valeur réelle.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"npx vitest --coverage"},{type:"cmd",value:"jest --coverage"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install pytest-cov"},{type:"cmd",value:"pytest --cov=src --cov-report=term-missing"},{type:"comment",value:"Vérification"},{type:"cmd",value:"Regarder les fichiers critiques non couverts"}],debt:"Coverage absent → angles morts invisibles. Coverage idolâtré → tests creux."}}},ci:{id:"ci",label:"CI",icon:"✓",kind:"vcs",osLabel:"Universel",sections:{why:"<p>Des tests qui ne tournent que sur la machine d'un développeur ne protègent pas l'équipe. La CI exécute automatiquement les tests, lint, build et parfois coverage à chaque push ou Pull Request. Elle transforme la qualité en garde-fou collectif.</p>",system:"<p>La CI se branche sur GitHub. Un push déclenche un workflow. Le workflow installe les dépendances, configure l'environnement, lance les scripts du projet, puis bloque ou autorise la fusion. Elle est la dernière ligne de défense avant que le code entre dans la branche principale.</p>",choice:{kind:"structured",main:"<p>GitHub Actions est le choix naturel sur GitHub. Les jobs typiques : install, lint, test, build. Pour projets avec base, ajouter un service PostgreSQL/Redis. Le point essentiel : utiliser les mêmes scripts qu'en local.</p>",alternatives:[{name:"GitHub Actions",description:"Défaut si le dépôt est sur GitHub."},{name:"GitLab CI",description:"Intégré à GitLab."},{name:"CI locale",description:"npm test / pytest avant commit, complément seulement."}]},senior:"<p>Il garde la CI rapide. Il sépare jobs parallélisables : lint, tests unitaires, build. Il cache les dépendances quand utile. Il rend les messages d'échec lisibles pour que l'équipe répare vite. Il protège main avec des checks obligatoires.</p>",errors:"<p><strong>Pattern 1 — CI différente du local :</strong> commandes divergentes, bugs impossibles à reproduire.</p><p><strong>Pattern 2 — CI lente :</strong> l'équipe attend ou contourne les checks.</p><p><strong>Pattern 3 — Checks non obligatoires :</strong> CI rouge mais merge possible.</p>",invariants:"<p>La branche principale doit toujours être dans un état vérifié. Ce qui change : plateforme CI. Ce qui ne change pas : aucun changement non testé ne doit entrer silencieusement dans main.</p>",practice:{commands:[{type:"comment",value:".github/workflows/ci.yml"},{type:"cmd",value:"on: [push, pull_request]"},{type:"cmd",value:"npm ci"},{type:"cmd",value:"npm run lint"},{type:"cmd",value:"npm test"},{type:"cmd",value:"npm run build"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install -r requirements-dev.txt"},{type:"cmd",value:"pytest --cov=src"}],debt:"Pas de CI obligatoire → main peut casser. CI trop lente → développeurs la contournent."}}}},maps:e(d)},v={viewBox:"0 0 940 300",nodes:[{id:"build",x:20,y:115,w:110,h:65},{id:"prod-env",x:180,y:55,w:120,h:65},{id:"hosting",x:180,y:175,w:110,h:65},{id:"release-pipeline",x:360,y:115,w:120,h:65},{id:"prod-logs",x:540,y:55,w:110,h:65},{id:"monitoring",x:540,y:175,w:120,h:65},{id:"rollback",x:730,y:115,w:110,h:65}],edges:[{x1:130,y1:135,x2:178,y2:88},{x1:130,y1:160,x2:178,y2:207},{x1:300,y1:88,x2:358,y2:135},{x1:290,y1:207,x2:358,y2:160},{x1:480,y1:135,x2:538,y2:88},{x1:480,y1:160,x2:538,y2:207},{x1:660,y1:207,x2:728,y2:160},{x1:650,y1:88,x2:728,y2:135}]},g={id:"deploiement",part:"T",number:10,title:"Déploiement",subtitle:"Passer d'un projet qui marche localement à un système qui tourne pour de vrais utilisateurs",badge:"Fiche T10 — Vision Systémique",status:"Modèle stabilisé",meta:["7 nœuds · 2 types","7 sections / nœud"],category:"Technique",level:"Junior",readingTime:"35 min",description:"Une carte pour comprendre build, variables de production, hosting, logs prod, monitoring, rollback et pipeline de déploiement.",accent:"infra",tabs:[{id:"js",label:"JS JavaScript"},{id:"python",label:"Python"}],nodes:{build:{id:"build",label:"Build",icon:"⚙",kind:"tool",osLabel:"JavaScript / Python",sections:{why:"<p>Le code de développement n'est pas toujours le code qu'on exécute en production. Frontend bundlé, TypeScript compilé, assets optimisés, dépendances installées proprement, migrations prêtes : le build transforme un projet de travail en artefact exécutable. Sans étape de build maîtrisée, on déploie un état implicite de machine locale.</p>",system:"<p>Le build se situe entre le code source et le hosting. Il est lancé en CI ou par la plateforme d'hébergement. Il consomme les dépendances, vérifie parfois les types, exécute lint/tests, puis produit un dossier ou une image déployable : <code>dist/</code>, bundle frontend, image Docker, wheel Python, ou serveur prêt à démarrer.</p>",choice:{kind:"structured",main:"<p>JavaScript frontend : Vite/Next génèrent un bundle optimisé. JavaScript backend : parfois pas de compilation, sauf TypeScript. Python : souvent pas de build applicatif lourd, mais installation des dépendances et image Docker. La vraie décision : déployer le source directement ou un artefact immuable.</p>",alternatives:[{name:"Build frontend",description:"Bundle statique optimisé : dist/, .next/, assets hashés."},{name:"Build backend",description:"TypeScript compilé, dépendances prod, image Docker."},{name:"Artefact immuable",description:"Ce qui est testé est exactement ce qui est déployé."}]},senior:"<p>Il veut un build reproductible : lock file commité, commande unique, environnement propre. Il ne build pas à la main sur sa machine pour ensuite envoyer des fichiers. Il sait que <code>npm run build</code> ou l'installation Python doit échouer tôt si une variable ou dépendance manque.</p>",errors:"<p><strong>Pattern 1 — Build local manuel :</strong> impossible de savoir ce qui a vraiment été déployé.</p><p><strong>Pattern 2 — Lock file absent :</strong> build différent selon la date.</p><p><strong>Pattern 3 — Build sans tests :</strong> artefact produit même si le projet est cassé.</p>",invariants:"<p>Un déploiement fiable commence par un artefact reproductible. Ce qui change : dist, Docker, wheel, serverless bundle. Ce qui ne change pas : la production ne doit pas dépendre de l'état implicite d'une machine de développeur.</p>",practice:{commands:[{type:"comment",value:"JavaScript"},{type:"cmd",value:"npm ci"},{type:"cmd",value:"npm run lint"},{type:"cmd",value:"npm test"},{type:"cmd",value:"npm run build"},{type:"comment",value:"Python"},{type:"cmd",value:"pip install -r requirements.txt"},{type:"cmd",value:"pytest"},{type:"cmd",value:"python -m compileall src"}],debt:"Build non reproductible → déploiements impossibles à diagnostiquer. Faire construire par CI ou plateforme, jamais à la main."}}},"prod-env":{id:"prod-env",label:"Variables prod",icon:"🔐",kind:"infra",osLabel:"Universel",sections:{why:"<p>La production n'a pas les mêmes valeurs que le local : vraie base de données, vrais secrets, URLs publiques, mode debug désactivé, niveau de logs différent. Les variables de production existent pour configurer le même code dans un environnement réel sans modifier le code source.</p>",system:"<p>Les variables prod sont injectées par la plateforme de déploiement : GitHub Actions secrets, Vercel, Render, Railway, Fly.io, Docker, Kubernetes. Le code les lit via le module de configuration validé. Elles alimentent DB, auth, services externes, CORS, logs et monitoring.</p>",choice:{kind:"structured",main:"<p>Pour un petit projet : variables dans le dashboard de la plateforme. Pour une équipe : secrets dans GitHub/plateforme + documentation dans <code>.env.example</code>. Pour systèmes plus critiques : secret manager dédié. Jamais de <code>.env</code> prod commité.</p>",alternatives:[{name:"Dashboard hosting",description:"Simple pour Vercel, Render, Railway."},{name:"GitHub Secrets",description:"Pour CI/CD et déploiements automatisés."},{name:"Secrets manager",description:"Doppler, Vault, AWS SSM pour environnements multiples."}]},senior:"<p>Il vérifie que <code>NODE_ENV=production</code> ou équivalent est bien positionné. Il désactive debug et stack traces publiques. Il sépare secrets, variables publiques frontend, et configuration interne backend. Il sait que les variables frontend sont souvent injectées dans le bundle et donc visibles.</p>",errors:"<p><strong>Pattern 1 — Secret dans le repo :</strong> irréversible sans rotation.</p><p><strong>Pattern 2 — Variable frontend secrète :</strong> tout ce qui est dans un bundle navigateur est public.</p><p><strong>Pattern 3 — Prod non validée :</strong> l'app démarre avec une variable manquante et casse au premier vrai utilisateur.</p>",invariants:"<p>La production doit être configurée par l'environnement, pas par le code. Les secrets doivent être stockés hors Git, injectés au runtime, validés au démarrage, et rotables.</p>",practice:{commands:[{type:"cmd",value:"NODE_ENV=production"},{type:"cmd",value:"DATABASE_URL=postgresql://..."},{type:"cmd",value:"JWT_SECRET=..."},{type:"cmd",value:"CORS_ORIGIN=https://app.example.com"},{type:"cmd",value:"LOG_LEVEL=info"},{type:"comment",value:"Vérification"},{type:"cmd",value:'node -e "if (!process.env.DATABASE_URL) process.exit(1)"'}],debt:"Variables prod non documentées → déploiement tribal. Maintenir .env.example et validation stricte."}}},hosting:{id:"hosting",label:"Hosting",icon:"☁",kind:"infra",osLabel:"Universel",sections:{why:"<p>Un projet local ne sert qu'à son développeur. Le hosting donne une adresse, des ressources, un runtime, un réseau, des certificats HTTPS, et un cycle de démarrage. Déployer, c'est confier l'exécution à une plateforme qui doit garder l'application disponible.</p>",system:"<p>Le hosting reçoit un build ou le code source, installe les dépendances, injecte les variables, démarre le processus, expose un domaine, et collecte les logs. Il devient la couche opérationnelle entre l'application et les utilisateurs.</p>",choice:{kind:"structured",main:"<p>Frontend statique : GitHub Pages, Netlify, Vercel. Fullstack/Node/Python : Render, Railway, Fly.io, Heroku-like, VPS, Docker. Le bon choix dépend du type d'app, de la base de données, du besoin de jobs, du budget et du niveau d'opérations accepté.</p>",alternatives:[{name:"Vercel / Netlify",description:"Excellent pour frontend et apps JS orientées edge/serverless."},{name:"Render / Railway / Fly.io",description:"Bon défaut pour backend Node/Python avec services managés."},{name:"VPS / Docker",description:"Plus de contrôle, plus de responsabilité."}]},senior:"<p>Il vérifie le modèle d'exécution : processus long-running, serverless, static, worker. Il sait qu'une app serverless ne gère pas les connexions DB comme un serveur permanent. Il configure health checks, région, domaine, HTTPS et redémarrage automatique.</p>",errors:"<p><strong>Pattern 1 — Mauvais modèle de hosting :</strong> backend long-running sur plateforme statique.</p><p><strong>Pattern 2 — Dépendre du filesystem local :</strong> fichiers écrits localement perdus au redémarrage.</p><p><strong>Pattern 3 — Pas de health check :</strong> plateforme pense que l'app tourne alors qu'elle ne répond pas correctement.</p>",invariants:"<p>La production est un environnement avec contraintes. Ce qui marche localement peut échouer si le modèle d'exécution change. Ce qui ne change pas : une app déployée doit pouvoir démarrer seule, être joignable, loguer, et redémarrer.</p>",practice:{commands:[{type:"comment",value:"Frontend statique"},{type:"cmd",value:"npm run build"},{type:"cmd",value:"ls dist"},{type:"comment",value:"Backend Node"},{type:"cmd",value:"npm start"},{type:"comment",value:"Python ASGI"},{type:"cmd",value:"uvicorn src.main:app --host 0.0.0.0 --port $PORT"},{type:"comment",value:"Health check"},{type:"cmd",value:"curl -i http://localhost:$PORT/health"}],debt:"Hosting choisi sans comprendre le runtime → bugs de prod subtils. Documenter commande de démarrage et modèle d'exécution."}}},"release-pipeline":{id:"release-pipeline",label:"Pipeline",icon:"→",kind:"vcs",osLabel:"Universel",sections:{why:"<p>Déployer à la main fonctionne une fois, puis devient une source d'erreurs : oublier une commande, pousser la mauvaise branche, sauter les tests, déployer depuis une machine sale. Un pipeline formalise l'ordre : installer, vérifier, build, migrer, déployer, vérifier.</p>",system:"<p>Le pipeline relie Git, CI, build, variables, hosting et monitoring. Un push ou merge déclenche un workflow. Le workflow produit un artefact et demande à la plateforme de le publier. Il crée une trace : qui a déployé quoi, quand, depuis quel commit.</p>",choice:{kind:"structured",main:"<p>Déploiement automatique sur main pour petits projets. Déploiement sur tag/release pour projets plus contrôlés. Environnements preview pour PRs quand l'interface doit être testée visuellement avant merge.</p>",alternatives:[{name:"Auto deploy main",description:"Simple, rapide, bon pour petites équipes."},{name:"Release tags",description:"Plus contrôlé, utile quand chaque version compte."},{name:"Preview environments",description:"Tester une PR sur une URL isolée."}]},senior:"<p>Il protège main : pas de merge sans CI verte. Il garde les étapes idempotentes. Il sait que les migrations doivent être compatibles avec le code en cours de déploiement. Il conserve le SHA du commit déployé pour rollback et diagnostic.</p>",errors:"<p><strong>Pattern 1 — Déploiement manuel :</strong> aucune traçabilité, erreurs humaines répétées.</p><p><strong>Pattern 2 — CI verte mais build prod cassé :</strong> la commande build n'est pas testée avant déploiement.</p><p><strong>Pattern 3 — Migration dangereuse dans pipeline :</strong> changement destructif sans plan de rollback.</p>",invariants:"<p>Un déploiement est une procédure reproductible. Ce qui change : GitHub Actions, GitLab CI, dashboard hosting. Ce qui ne change pas : chaque release doit être traçable à un commit et validée par des checks automatisés.</p>",practice:{commands:[{type:"comment",value:"GitHub Actions"},{type:"cmd",value:"npm ci"},{type:"cmd",value:"npm run lint && npm test && npm run build"},{type:"cmd",value:"pip install -r requirements.txt && pytest"},{type:"comment",value:"Release"},{type:"cmd",value:"git tag v1.0.0 && git push origin v1.0.0"},{type:"comment",value:"Trace"},{type:"cmd",value:"DEPLOYED_SHA=$(git rev-parse HEAD)"}],debt:"Pipeline absent → déploiement artisanal. Pipeline non traçable → impossible de savoir quelle version tourne."}}},"prod-logs":{id:"prod-logs",label:"Logs prod",icon:"📋",kind:"tool",osLabel:"Universel",sections:{why:"<p>En production, on ne peut pas ouvrir le debugger ni regarder directement dans le processus. Les logs sont la mémoire observable de ce qui s'est passé : requêtes, erreurs, latence, décisions importantes. Sans logs de production, chaque incident devient une enquête sans témoins.</p>",system:"<p>Les logs prod sont produits par l'application et collectés par la plateforme : stdout/stderr, dashboard hosting, Datadog, Logtail, Grafana Loki, CloudWatch. Ils doivent inclure contexte, niveau, timestamp, requestId, mais jamais de secrets.</p>",choice:{kind:"structured",main:"<p>Logs texte simples suffisent au début. Logs JSON structurés deviennent nécessaires dès qu'on veut filtrer par userId, requestId, status, route. Le choix dépend surtout de la capacité à rechercher et corréler.</p>",alternatives:[{name:"stdout plateforme",description:"Défaut simple, souvent suffisant au début."},{name:"Logs structurés JSON",description:"Filtrables, corrélables, adaptés production."},{name:"Agrégateur dédié",description:"Datadog, Loki, Logtail, CloudWatch."}]},senior:"<p>Il logue les erreurs avec stack trace, route, requestId et contexte utile. Il ne logue jamais tokens, mots de passe, payloads sensibles ou données personnelles inutiles. Il configure le niveau : debug en dev, info/warn/error en prod.</p>",errors:`<p><strong>Pattern 1 — Logs sans contexte :</strong> "error happened" ne permet aucune enquête.</p><p><strong>Pattern 2 — Secrets dans les logs :</strong> fuite souvent plus grave qu'une erreur en base.</p><p><strong>Pattern 3 — Debug trop verbeux en prod :</strong> bruit, coûts, données exposées.</p>`,invariants:"<p>Ce qui n'est pas observé ne peut pas être diagnostiqué. Les logs doivent être utiles, contextualisés, et sûrs. Ce qui change : outil de collecte. Ce qui ne change pas : pas de production sérieuse sans traces.</p>",practice:{commands:[{type:"cmd",value:"LOG_LEVEL=info"},{type:"cmd",value:"logger.info({ requestId, method, path, status, duration }, 'request completed')"},{type:"cmd",value:"logger.error({ err, requestId }, 'unhandled error')"},{type:"comment",value:"Vérification"},{type:"cmd",value:"Une erreur volontaire apparaît dans les logs avec stack trace et requestId"}],debt:"Logs non structurés ou absents → incidents longs à diagnostiquer. Ajouter requestId et niveaux de logs tôt."}}},monitoring:{id:"monitoring",label:"Monitoring",icon:"◉",kind:"runtime",osLabel:"Universel",sections:{why:"<p>Les logs disent ce qui s'est passé quand on cherche. Le monitoring alerte quand quelque chose va mal avant qu'un utilisateur ne le signale : app down, taux d'erreur élevé, latence anormale, CPU/mémoire saturés, jobs bloqués. Sans monitoring, la production peut être cassée pendant des heures dans le silence.</p>",system:"<p>Le monitoring se branche sur l'application et la plateforme. Il collecte métriques, erreurs, traces, uptime checks. Il transforme des signaux techniques en alertes actionnables. Il complète les logs : métriques pour détecter, logs pour comprendre, traces pour suivre un parcours.</p>",choice:{kind:"structured",main:"<p>Au minimum : uptime check + alertes erreurs. Ensuite : Sentry pour exceptions, métriques plateforme, APM si latence complexe. Pas besoin de tout instrumenter au début, mais il faut savoir si l'application est down et si les erreurs montent.</p>",alternatives:[{name:"Uptime monitoring",description:"Vérifie que /health répond régulièrement."},{name:"Sentry",description:"Capture exceptions frontend/backend avec contexte."},{name:"APM",description:"Datadog/New Relic/OpenTelemetry pour traces et performance."}]},senior:"<p>Il définit des alertes utiles, pas bruyantes. Une alerte doit appeler une action. Il surveille golden signals : latence, trafic, erreurs, saturation. Il ajoute un endpoint <code>/health</code> qui vérifie les dépendances critiques selon le besoin.</p>",errors:"<p><strong>Pattern 1 — Pas d'alerte :</strong> les utilisateurs deviennent le système de monitoring.</p><p><strong>Pattern 2 — Trop d'alertes :</strong> fatigue, alertes ignorées.</p><p><strong>Pattern 3 — Health check superficiel :</strong> répond 200 alors que la base est inaccessible.</p>",invariants:"<p>Un système en production doit être observable et alerter sur ses défaillances. Ce qui change : outil et profondeur. Ce qui ne change pas : découvrir une panne par hasard est un échec opérationnel.</p>",practice:{commands:[{type:"cmd",value:"curl -i https://app.example.com/health"},{type:"cmd",value:"SENTRY_DSN=..."},{type:"comment",value:"error_rate > 5% pendant 5 min → alerte"},{type:"comment",value:"p95 latency > 1s → investigation"},{type:"comment",value:"Golden signals : latency, traffic, errors, saturation"}],debt:"Monitoring absent → pannes silencieuses. Alertes bruyantes → personne ne réagit."}}},rollback:{id:"rollback",label:"Rollback",icon:"↩",kind:"vcs",osLabel:"Universel",sections:{why:"<p>Tout déploiement peut casser : bug non détecté, migration problématique, variable manquante, dépendance externe différente. Le rollback existe pour réduire le temps pendant lequel les utilisateurs subissent l'incident. Il ne remplace pas les tests, il limite les dégâts quand les tests n'ont pas suffi.</p>",system:"<p>Le rollback est lié au pipeline, au hosting, aux migrations et au monitoring. Le monitoring détecte, les logs expliquent, le rollback restaure une version précédente. La plateforme doit savoir quelle version était déployée avant, et l'application doit supporter le retour arrière.</p>",choice:{kind:"structured",main:"<p>Rollback applicatif simple : redéployer le commit précédent. Rollback plateforme : bouton ou release précédente. Rollback DB : plus difficile, surtout après migrations destructives. Le vrai choix est souvent d'éviter les migrations irréversibles avec des déploiements compatibles en plusieurs étapes.</p>",alternatives:[{name:"Redéployer commit précédent",description:"Simple si artefacts et variables sont stables."},{name:"Rollback plateforme",description:"Vercel/Render/Fly peuvent garder des releases précédentes."},{name:"Forward fix",description:"Corriger en avançant quand rollback DB est risqué."}]},senior:"<p>Il prépare le rollback avant de déployer. Il sait quelles migrations sont backward compatible. Il évite de supprimer une colonne utilisée par l'ancienne version dans le même déploiement. Il utilise feature flags pour désactiver une fonctionnalité sans redéployer quand c'est pertinent.</p>",errors:"<p><strong>Pattern 1 — Pas de plan rollback :</strong> incident prod, improvisation sous stress.</p><p><strong>Pattern 2 — Migration destructive :</strong> impossible de revenir à l'ancienne version du code.</p><p><strong>Pattern 3 — Rollback non testé :</strong> procédure supposée mais jamais vérifiée.</p>",invariants:"<p>Déployer implique savoir revenir à un état stable. Ce qui change : outil de hosting, stratégie release, type de base. Ce qui ne change pas : une release sans plan de retour augmente le risque opérationnel.</p>",practice:{commands:[{type:"comment",value:"Git"},{type:"cmd",value:"git revert <bad_commit>"},{type:"cmd",value:"git push origin main"},{type:"comment",value:"Platform"},{type:"cmd",value:"Redéployer la release précédente depuis le dashboard"},{type:"comment",value:"Avant déploiement"},{type:"cmd",value:"Identifier commit actuel, migration incluse, procédure rollback"}],debt:"Rollback impossible à cause de migrations destructives → downtime prolongé. Penser compatibilité arrière avant toute migration prod."}}}},maps:e(v)},h=[t,s,n,r,a,l,c,p,m,g];export{h as t};
